INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C1','math',1,1,'u3',2,'9까지의 수 모으기 — 두 수를 모으면 얼마가 되는지 알고, 모으는 순서가 바뀌어도 모은 수는 같음을 알기',ARRAY['2수01-04']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C2','math',1,1,'u3',2,'9까지의 수 가르기 — 한 수를 두 수로 여러 가지로 가르되, 가른 두 수를 모으면 다시 처음 수가 됨을 확인하며 빠뜨리지 않고 찾기',ARRAY['2수01-04']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C3','math',1,1,'u3',4,'덧셈·뺄셈 이야기 만들기 — 모으기·더 오기·덜어 내기·견주기 상황을 그림에서 읽고 「모두 몇·남은 것·몇 더 많은가」를 묻는 이야기로 말하기',ARRAY['2수01-04']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C4','math',1,1,'u3',5,'덧셈식 알기 — +, = 를 쓰고 「더하기·같습니다·합」으로 읽으며, 모으기·더 오기 상황을 덧셈식으로 나타내기',ARRAY['2수01-05']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C5','math',1,1,'u3',6,'덧셈하기 — 모두 세기·이어 세기·십 배열판으로 합이 9까지인 덧셈을 하고, 두 수의 순서를 바꾸어도 합이 같음과 식의 규칙을 알기',ARRAY['2수01-06']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C6','math',1,1,'u3',8,'뺄셈식 알기 — − 를 쓰고 「빼기·차」로 읽으며, 덜어 내기와 견주기(몇 더 많은가) 상황을 모두 뺄셈식으로 나타내기',ARRAY['2수01-05']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C7','math',1,1,'u3',9,'뺄셈하기 — 거꾸로 세기·덜어 내기·십 배열판으로 9까지의 뺄셈을 하고, 한 그림에서 두 뺄셈식을 쓰며 남은 수와 뺀 수를 가르기',ARRAY['2수01-06']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C8','math',1,1,'u3',11,'0이 있는 덧셈과 뺄셈 — 0을 더하거나 빼면 그대로, 같은 수를 모두 빼면 0이 됨을 알고 0을 빼기와 모두 빼기를 가르기',ARRAY['2수01-06']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u3-C9','math',1,1,'u3',12,'여러 가지 덧셈식·뺄셈식 — 결과가 같은 식을 찾고, 한 수로 덧셈식·뺄셈식을 규칙에 따라 빠짐없이 만들기',ARRAY['2수01-06']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X01','math',1,'u3',ARRAY['M1-1-u3-C1']::text[],'두 수를 모을 때 두 수 가운데 하나(주로 큰 수)를 답으로 한다','두 손에 나누어 쥔 구슬을 한 접시에 쏟아 처음부터 다시 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X02','math',1,'u3',ARRAY['M1-1-u3-C2','M1-1-u3-C9']::text[],'가를 때 나머지가 아니라 전체나 엉뚱한 수를 쓴다 — 가른 두 수를 모으면 처음 수가 되는지 확인하지 않음','가른 두 수를 다시 모아 처음 수가 되는지 손가락으로 확인하는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X03','math',1,'u3',ARRAY['M1-1-u3-C2','M1-1-u3-C9']::text[],'가르는 방법이 한 가지뿐이라고 여기거나, 차례 없이 찾아 빠뜨리거나 같은 것을 두 번 쓴다','한쪽 수를 1, 2, 3… 차례로 늘리며 표로 적어 빈 줄이 없는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X04','math',1,'u3',ARRAY['M1-1-u3-C3','M1-1-u3-C4','M1-1-u3-C6']::text[],'모으기·더 오기 이야기와 덜어 내기 이야기를 바꿔 계산한다(덧셈과 뺄셈을 맞바꿈)','이야기를 몸으로 해 보기 — 더 오면 손가락이 늘고, 가 버리면 손가락을 접기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X05','math',1,'u3',ARRAY['M1-1-u3-C3','M1-1-u3-C6']::text[],'「몇 개 더 많은가」를 묻는 견주기 이야기를 덧셈으로 푼다','두 줄을 하나씩 짝 지어 놓고 짝이 없는 것만 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X06','math',1,'u3',ARRAY['M1-1-u3-C4','M1-1-u3-C6']::text[],'+, −, = 기호를 바꿔 쓰거나 식을 잘못 읽는다 — 「=」를 「그리고」나 「답이 더 크다」로 앎','양팔 저울 그림에 식을 올려 「=」는 양쪽이 같다는 뜻임을 보여 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X07','math',1,'u3',ARRAY['M1-1-u3-C5']::text[],'이어 세기에서 처음 수를 다시 세어 하나 적은 답이 나온다(6에서 2 이어 세기 → 7)','처음 수는 머리에 넣고 「다음 수부터」 손가락을 펴며 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X08','math',1,'u3',ARRAY['M1-1-u3-C1','M1-1-u3-C5','M1-1-u3-C9']::text[],'덧셈에서 두 수의 순서를 바꾸면 합이 달라진다고 여기거나, 뺄셈도 순서를 바꿔도 된다고 여긴다','같은 구슬을 왼쪽·오른쪽 바꿔 놓고 모아 보기 / 뺄셈은 덜어 낼 수 있는 쪽이 앞이라는 것 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X09','math',1,'u3',ARRAY['M1-1-u3-C7']::text[],'거꾸로 세기에서 처음 수부터 세어 하나 많은 답이 나온다(9에서 3 거꾸로 → 7)','처음 수는 세지 않고 「바로 아래 수부터」 손가락을 접으며 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X10','math',1,'u3',ARRAY['M1-1-u3-C3','M1-1-u3-C6','M1-1-u3-C7']::text[],'뺄셈에서 남은 수 대신 덜어 낸 수(뺀 수)를 답으로 쓴다','덜어 낸 것은 접시 밖으로 치우고 접시에 남은 것만 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X11','math',1,'u3',ARRAY['M1-1-u3-C6','M1-1-u3-C7','M1-1-u3-C9']::text[],'뺄셈식에서 수의 순서를 거꾸로 쓴다 — 작은 수에서 큰 수를 빼거나 뺀 수를 앞에 씀','「처음에 있던 수」를 먼저 쓰고 「덜어 낸 수」를 − 뒤에 쓰도록 말틀을 붙여 두기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X12','math',1,'u3',ARRAY['M1-1-u3-C8']::text[],'0을 더하거나 빼면 답이 0이 된다고 여긴다','빈 접시(0)를 보여 주며 「아무것도 더하지 않았어」를 몸으로 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X13','math',1,'u3',ARRAY['M1-1-u3-C8']::text[],'같은 수를 모두 빼도 처음 수 그대로라고 여기거나, 0을 빼기와 모두 빼기를 헷갈린다','사탕 4개를 하나씩 다 먹는 모습을 그리고 접시에 남은 것을 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X14','math',1,'u3',ARRAY['M1-1-u3-C5','M1-1-u3-C7','M1-1-u3-C9']::text[],'식의 규칙을 잇지 못하거나, 한 수만 같으면 결과가 같다고 본다','식을 줄 세워 「앞 수는 1씩 커지고 뒤 수는 1씩 작아져」처럼 바뀌는 곳에 색칠하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u3-X15','math',1,'u3',ARRAY['M1-1-u3-C1','M1-1-u3-C3','M1-1-u3-C4','M1-1-u3-C5']::text[],'그림을 세며 하나를 빠뜨리거나 두 번 세어 1 차이 나는 답을 쓴다','센 그림에 점을 찍으며 세고, 끝나면 한 번 더 거꾸로 세어 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#1','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"3","mis":"M1-1-u3-X01"},{"t":"6","mis":"M1-1-u3-X15"}],"explanation":["2와 3을 모아요.","모으면 5예요.","모으기는 두 수를 합쳐서 세는 거예요."],"asset":{"type":"number_bond","whole":null,"parts":[2,3]},"variant_rule":{"bond":{"whole":[3,7],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#2','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',1,'sa','auto','6을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"6을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["2"],"explanation":["6을 4와 무엇으로 갈랐을까요?","4와 2를 모으면 6이니 빈칸은 2예요.","가른 두 수를 다시 모아 6이 되는지 확인해요."],"asset":{"type":"number_bond","whole":6,"parts":[4,null]},"variant_rule":{"bond":{"whole":[3,7],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#3','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C1',1,'mc','auto','병아리 3마리와 1마리를 모으면 모두 몇 마리인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":3,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"병아리 3마리와 1마리를 모으면 모두 몇 마리인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X01"},{"t":"5","mis":"M1-1-u3-X15"}],"explanation":["3마리와 1마리를 모아요.","모두 4마리예요.","두 무리를 한 번에 이어서 세어요."],"asset":{"type":"group_row","groups":[{"item":"🐤","n":3},{"item":"🐤","n":1}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value","max":7}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#4','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',1,'ox','auto','5는 2와 3으로 가를 수 있어요.',ARRAY['M1-1-u3-X03']::text[],true,'{"seq":4,"concept":"M1-1-u3-C2","difficulty":1,"kind":"ox","stem":"5는 2와 3으로 가를 수 있어요.","answer":"O","reason_options":[{"t":"2와 3을 모으면 5가 되니까","correct":true},{"t":"5는 같은 두 수로만 가를 수 있으니까","mis":"M1-1-u3-X03"}],"mis":"M1-1-u3-X03","explanation":["2와 3을 모으면 5예요.","그래서 5는 2와 3으로 가를 수 있어요.","가른 두 수를 모아 처음 수가 되는지 보세요."],"variant_rule":{"alt":[{"stem":"6은 4와 3으로 가를 수 있어요.","answer":"X","reason_options":[{"t":"4와 3을 모으면 7이니까","correct":true},{"t":"두 수가 6보다 작으면 다 되니까","mis":"M1-1-u3-X02"}],"explanation":["4와 3을 모으면 7이에요.","6이 아니니 6을 4와 3으로 가를 수 없어요.","6은 4와 2로 가를 수 있어요."],"asset":null},{"stem":"7은 6과 1로 가를 수 있어요.","answer":"O","reason_options":[{"t":"6과 1을 모으면 7이 되니까","correct":true},{"t":"한쪽이 1이면 가를 수 없으니까","mis":"M1-1-u3-X03"}],"explanation":["6과 1을 모으면 7이에요.","그래서 7은 6과 1로 가를 수 있어요.","한쪽이 1이어도 가르기예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#5','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',2,'mc','auto','7을 둘로 가른 것이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":5,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"7을 둘로 가른 것이 아닌 것은 어느 것인가요?","options":[{"t":"4와 4","correct":true},{"t":"2와 5","mis":"M1-1-u3-X02"},{"t":"6과 1","mis":"M1-1-u3-X02"}],"explanation":["4와 4를 모으면 8이에요.","2와 5, 6과 1은 모으면 7이에요.","두 수를 모아 7이 되는지 하나씩 확인해요."],"variant_rule":{"alt":[{"stem":"6을 둘로 가른 것이 아닌 것은 어느 것인가요?","options":[{"t":"2와 3","correct":true},{"t":"1과 5","mis":"M1-1-u3-X02"},{"t":"3과 3","mis":"M1-1-u3-X02"}],"explanation":["2와 3을 모으면 5예요.","1과 5, 3과 3은 모으면 6이에요.","모아서 6이 되는지 확인해요."],"asset":null},{"stem":"5를 둘로 가른 것이 아닌 것은 어느 것인가요?","options":[{"t":"3과 3","correct":true},{"t":"4와 1","mis":"M1-1-u3-X02"},{"t":"2와 3","mis":"M1-1-u3-X02"}],"explanation":["3과 3을 모으면 6이에요.","4와 1, 2와 3은 모으면 5예요.","모아서 5가 되는지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#6','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C1',2,'sa','auto','4와 3을 모으면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C1","difficulty":2,"kind":"sa","stem":"4와 3을 모으면 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["4에서 3만큼 이어 세어요 — 5, 6, 7.","모으면 7이에요.","큰 수에서 이어 세면 빨라요."],"asset":{"type":"number_bond","whole":null,"parts":[4,3]},"variant_rule":{"bond":{"whole":[4,7],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#7','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',2,'match','auto','6을 가른 두 수가 되도록 짝을 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u3-C2","difficulty":2,"kind":"match","stem":"6을 가른 두 수가 되도록 짝을 이어 보세요.","pairs":[{"l":"1","r":"5"},{"l":"2","r":"4"},{"l":"3","r":"3"}],"mis":"M1-1-u3-X02","explanation":["1과 5, 2와 4, 3과 3을 모으면 모두 6이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 6이 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"7을 가른 두 수가 되도록 짝을 이어 보세요.","pairs":[{"l":"1","r":"6"},{"l":"3","r":"4"},{"l":"5","r":"2"}],"explanation":["1과 6, 3과 4, 5와 2를 모으면 모두 7이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 7이 되는지 확인해요."],"asset":null},{"stem":"5를 가른 두 수가 되도록 짝을 이어 보세요.","pairs":[{"l":"1","r":"4"},{"l":"2","r":"3"},{"l":"5","r":"0"}],"explanation":["1과 4, 2와 3, 5와 0을 모으면 모두 5예요.","0도 가르기에 쓸 수 있어요.","짝을 모아 5가 되는지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#8','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',2,'mc','auto','구슬 6개를 두 손에 나누어 쥐었어요. 왼손에 2개가 있으면 오른손에는 몇 개가 있나요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":8,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"구슬 6개를 두 손에 나누어 쥐었어요. 왼손에 2개가 있으면 오른손에는 몇 개가 있나요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u3-X02"},{"t":"8","mis":"M1-1-u3-X04"}],"explanation":["6을 2와 무엇으로 가를까요?","2와 4를 모으면 6이니 오른손에는 4개예요.","두 손의 구슬을 모으면 다시 6개예요."],"variant_rule":{"alt":[{"stem":"사탕 7개를 두 봉지에 나누어 담았어요. 한 봉지에 3개를 담으면 다른 봉지에는 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["7을 3과 무엇으로 가를까요?","3과 4를 모으면 7이니 4개예요.","두 봉지를 모으면 다시 7개예요."],"asset":null},{"stem":"공 5개를 두 상자에 나누어 넣었어요. 한 상자에 1개를 넣으면 다른 상자에는 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M1-1-u3-X02"},{"t":"6","mis":"M1-1-u3-X04"}],"explanation":["5를 1과 무엇으로 가를까요?","1과 4를 모으면 5이니 4개예요.","두 상자를 모으면 다시 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#9','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C1',2,'blank','auto','3과 모아서 7이 되는 수는 (        )예요.',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":9,"concept":"M1-1-u3-C1","difficulty":2,"kind":"blank","stem":"3과 모아서 7이 되는 수는 (        )예요.","options":[{"t":"4","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["3과 무엇을 모으면 7일까요?","3, 4, 5, 6, 7 — 3에서 4만큼 이어 세면 7이에요.","그래서 빈칸은 4예요."],"variant_rule":{"alt":[{"stem":"2와 모아서 6이 되는 수는 (        )예요.","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u3-X02"},{"t":"8","mis":"M1-1-u3-X04"}],"explanation":["2와 무엇을 모으면 6일까요?","2와 4를 모으면 6이에요.","그래서 빈칸은 4예요."],"asset":null},{"stem":"5와 모아서 7이 되는 수는 (        )예요.","options":[{"t":"2","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"12","mis":"M1-1-u3-X04"}],"explanation":["5와 무엇을 모으면 7일까요?","5와 2를 모으면 7이에요.","그래서 빈칸은 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_basic#10','math',1,1,'u3','L02','g1_1_math_u3_L02_basic','lesson_basic','M1-1-u3-C2',3,'error','auto','친구들이 7을 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":3,"kind":"error","stem":"친구들이 7을 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"서아: 3과 5","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"하루: 2와 5","mis":"M1-1-u3-X02"},{"t":"도이: 6과 1","mis":"M1-1-u3-X02"}],"explanation":["3과 5를 모으면 8이에요 — 7이 아니에요.","2와 5, 6과 1은 모으면 7이에요.","가른 뒤에는 꼭 다시 모아 확인해요."],"variant_rule":{"alt":[{"stem":"친구들이 6을 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"지우: 2와 5","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"유나: 3과 3","mis":"M1-1-u3-X02"},{"t":"하루: 1과 5","mis":"M1-1-u3-X02"}],"explanation":["2와 5를 모으면 7이에요 — 6이 아니에요.","3과 3, 1과 5는 모으면 6이에요.","가른 뒤에는 꼭 다시 모아 확인해요."],"asset":null},{"stem":"친구들이 5를 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"도이: 5와 1","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"서아: 4와 1","mis":"M1-1-u3-X02"},{"t":"지우: 2와 3","mis":"M1-1-u3-X02"}],"explanation":["5와 1을 모으면 6이에요 — 5가 아니에요.","4와 1, 2와 3은 모으면 5예요.","가른 뒤에는 꼭 다시 모아 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#1','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',2,'sa','auto','7을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-1-u3-C2","difficulty":2,"kind":"sa","stem":"7을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["5"],"explanation":["7을 2와 무엇으로 갈랐을까요?","2와 5를 모으면 7이니 빈칸은 5예요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":7,"parts":[2,null]},"variant_rule":{"bond":{"whole":[5,7],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#2','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C1',2,'mc','auto','고구마를 두 바구니에서 꺼내 모았어요. 모두 몇 개인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":2,"concept":"M1-1-u3-C1","difficulty":2,"kind":"mc","stem":"고구마를 두 바구니에서 꺼내 모았어요. 모두 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"4","mis":"M1-1-u3-X01"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["4개와 2개를 모아요.","모두 6개예요.","센 것에 점을 찍으며 세어요."],"asset":{"type":"group_row","groups":[{"item":"🍠","n":4},{"item":"🍠","n":2}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value","max":7}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#3','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',3,'mc','auto','6을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 5, 5와 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],true,'{"seq":3,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"6을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 5, 5와 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"5","correct":true},{"t":"3","mis":"M1-1-u3-X03"},{"t":"6","mis":"M1-1-u3-X03"}],"explanation":["1과 5, 2와 4, 3과 3, 4와 2, 5와 1이에요.","모두 5가지예요.","한쪽 수를 1, 2, 3… 차례로 늘리면 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"5를 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 4, 4와 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u3-X03"},{"t":"5","mis":"M1-1-u3-X03"}],"explanation":["1과 4, 2와 3, 3과 2, 4와 1이에요.","모두 4가지예요.","한쪽 수를 차례로 늘리면 빠뜨리지 않아요."],"asset":null},{"stem":"7을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 6, 6과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"6","correct":true},{"t":"3","mis":"M1-1-u3-X03"},{"t":"7","mis":"M1-1-u3-X03"}],"explanation":["1과 6, 2와 5, 3과 4, 4와 3, 5와 2, 6과 1이에요.","모두 6가지예요.","한쪽 수를 차례로 늘리면 빠뜨리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#4','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',3,'mc','auto','도윤이가 7을 가르는 방법을 차례로 썼어요. 「1과 6, 2와 5, 3과 4, 5와 2, 6과 1」 빠뜨린 것은 무엇인가요?',ARRAY['M1-1-u3-X03','M1-1-u3-X02']::text[],true,'{"seq":4,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"도윤이가 7을 가르는 방법을 차례로 썼어요. 「1과 6, 2와 5, 3과 4, 5와 2, 6과 1」 빠뜨린 것은 무엇인가요?","options":[{"t":"4와 3","correct":true},{"t":"3과 4","mis":"M1-1-u3-X03"},{"t":"2와 6","mis":"M1-1-u3-X02"}],"explanation":["왼쪽 수가 1, 2, 3, 다음은 4여야 해요.","4와 3을 빠뜨렸어요.","한쪽 수를 1씩 늘리며 빈 자리를 찾아요."],"variant_rule":{"alt":[{"stem":"지우가 6을 가르는 방법을 차례로 썼어요. 「1과 5, 2와 4, 4와 2, 5와 1」 빠뜨린 것은 무엇인가요?","options":[{"t":"3과 3","correct":true},{"t":"2와 4","mis":"M1-1-u3-X03"},{"t":"3과 4","mis":"M1-1-u3-X02"}],"explanation":["왼쪽 수가 1, 2, 다음은 3이어야 해요.","3과 3을 빠뜨렸어요.","한쪽 수를 1씩 늘리며 빈 자리를 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#5','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C1',3,'ox','auto','2와 4를 모은 수와 4와 2를 모은 수는 서로 달라요.',ARRAY['M1-1-u3-X08']::text[],true,'{"seq":5,"concept":"M1-1-u3-C1","difficulty":3,"kind":"ox","stem":"2와 4를 모은 수와 4와 2를 모은 수는 서로 달라요.","answer":"X","reason_options":[{"t":"모으는 순서가 바뀌어도 모두 6이니까","correct":true},{"t":"먼저 놓인 수가 다르면 모은 수도 다르니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["2와 4를 모아도, 4와 2를 모아도 6이에요.","순서는 모은 수를 바꾸지 않아요.","구슬을 왼쪽·오른쪽 바꿔 놓아도 개수는 같아요."],"variant_rule":{"alt":[{"stem":"3과 1을 모은 수와 1과 3을 모은 수는 같아요.","answer":"O","reason_options":[{"t":"모으는 순서가 바뀌어도 모두 4니까","correct":true},{"t":"먼저 놓인 수가 크면 모은 수도 크니까","mis":"M1-1-u3-X08"}],"explanation":["3과 1을 모아도, 1과 3을 모아도 4예요.","순서는 모은 수를 바꾸지 않아요.","왼쪽·오른쪽을 바꿔 놓아도 개수는 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#6','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',3,'mc','auto','구슬 7개를 두 주머니에 나누어 넣었어요. 한 주머니에 다른 주머니보다 1개 더 많이 넣었어요. 많은 주머니에는 몇 개가 있나요?',ARRAY['M1-1-u3-X02','M1-1-u3-X03']::text[],true,'{"seq":6,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"구슬 7개를 두 주머니에 나누어 넣었어요. 한 주머니에 다른 주머니보다 1개 더 많이 넣었어요. 많은 주머니에는 몇 개가 있나요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u3-X02"},{"t":"5","mis":"M1-1-u3-X03"}],"explanation":["7을 가르는 방법 가운데 두 수의 차이가 1인 것을 찾아요.","3과 4 — 많은 주머니에는 4개예요.","6과 1, 5와 2는 차이가 너무 커요."],"variant_rule":{"alt":[{"stem":"사탕 5개를 두 친구가 나누었어요. 한 친구가 1개 더 많이 가졌어요. 많이 가진 친구는 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M1-1-u3-X02"},{"t":"5","mis":"M1-1-u3-X02"}],"explanation":["5를 가르는 방법 가운데 차이가 1인 것을 찾아요.","2와 3 — 많이 가진 친구는 3개예요.","4와 1은 차이가 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#7','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C1',3,'mc','auto','모아서 6이 되는 두 수가 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":7,"concept":"M1-1-u3-C1","difficulty":3,"kind":"mc","stem":"모아서 6이 되는 두 수가 아닌 것은 어느 것인가요?","options":[{"t":"2와 3","correct":true},{"t":"1과 5","mis":"M1-1-u3-X02"},{"t":"3과 3","mis":"M1-1-u3-X02"}],"explanation":["2와 3을 모으면 5예요.","1과 5, 3과 3은 모으면 6이에요.","두 수를 하나씩 모아 확인해요."],"variant_rule":{"alt":[{"stem":"모아서 7이 되는 두 수가 아닌 것은 어느 것인가요?","options":[{"t":"5와 3","correct":true},{"t":"4와 3","mis":"M1-1-u3-X02"},{"t":"6과 1","mis":"M1-1-u3-X02"}],"explanation":["5와 3을 모으면 8이에요.","4와 3, 6과 1은 모으면 7이에요.","두 수를 하나씩 모아 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#8','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C1',4,'mc','auto','지우와 서아의 사탕을 모으면 5개, 서아와 하루의 사탕을 모으면 4개예요. 서아가 2개라면 지우와 하루의 사탕을 모으면 몇 개인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":8,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"지우와 서아의 사탕을 모으면 5개, 서아와 하루의 사탕을 모으면 4개예요. 서아가 2개라면 지우와 하루의 사탕을 모으면 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M1-1-u3-X04"},{"t":"4","mis":"M1-1-u3-X01"}],"explanation":["지우는 5를 2와 3으로 — 3개, 하루는 4를 2와 2로 — 2개예요.","3과 2를 모으면 5개예요.","가르기로 한 사람씩 먼저 알아내요."],"variant_rule":{"alt":[{"stem":"도이와 유나의 구슬을 모으면 6개, 유나와 하루의 구슬을 모으면 5개예요. 유나가 3개라면 도이와 하루의 구슬을 모으면 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"11","mis":"M1-1-u3-X04"},{"t":"6","mis":"M1-1-u3-X01"}],"explanation":["도이는 6을 3과 3으로 — 3개, 하루는 5를 3과 2로 — 2개예요.","3과 2를 모으면 5개예요.","가르기로 한 사람씩 먼저 알아내요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#9','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',4,'essay','teacher','7을 둘로 가르는 방법을 빠짐없이 쓰고, 빠뜨리지 않으려고 어떻게 찾았는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u3-C2","difficulty":4,"kind":"essay","stem":"7을 둘로 가르는 방법을 빠짐없이 쓰고, 빠뜨리지 않으려고 어떻게 찾았는지 말해 보세요.","answer_guide":{"answer":"1과 6, 2와 5, 3과 4, 4와 3, 5와 2, 6과 1. 왼쪽 수를 1부터 하나씩 늘리고 오른쪽 수는 하나씩 줄였어요.","scoring_points":["가르기 6가지를 모두 썼는가","가른 두 수를 모으면 7이 되는가","한쪽을 1씩 늘리는 것처럼 차례를 말했는가"]},"explanation":["한쪽 수를 1부터 차례로 써요.","다른 쪽은 모아서 7이 되는 수를 써요.","마지막에 빠진 줄이 없는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L02_challenge#10','math',1,1,'u3','L02','g1_1_math_u3_L02_challenge','lesson_challenge','M1-1-u3-C2',4,'mc','auto','가른 두 수가 서로 같게 되도록 가를 수 있는 수는 어느 것인가요?',ARRAY['M1-1-u3-X03']::text[],true,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":4,"kind":"mc","stem":"가른 두 수가 서로 같게 되도록 가를 수 있는 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M1-1-u3-X03"},{"t":"7","mis":"M1-1-u3-X03"}],"explanation":["6은 3과 3으로 가를 수 있어요.","5와 7은 두 수가 똑같게 가를 수 없어요.","같은 두 수를 모으면 2, 4, 6, 8이 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 가른 두 수가 서로 같게 되도록 가를 수 있는 수는 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X03"},{"t":"5","mis":"M1-1-u3-X03"}],"explanation":["4는 2와 2로 가를 수 있어요.","3과 5는 두 수가 똑같게 가를 수 없어요.","같은 두 수를 모으면 2, 4, 6, 8이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#1','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"5","mis":"M1-1-u3-X01"},{"t":"9","mis":"M1-1-u3-X15"}],"explanation":["5와 3을 모아요.","5에서 3만큼 이어 세면 6, 7, 8 — 8이에요.","모으기는 두 수를 합쳐서 세는 거예요."],"asset":{"type":"number_bond","whole":null,"parts":[5,3]},"variant_rule":{"bond":{"whole":[6,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#2','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C2',1,'sa','auto','9를 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"9를 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["3"],"explanation":["9를 6과 무엇으로 갈랐을까요?","6과 3을 모으면 9이니 빈칸은 3이에요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":9,"parts":[6,null]},"variant_rule":{"bond":{"whole":[6,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#3','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C1',1,'mc','auto','닭이 두 무리 있어요. 닭은 모두 몇 마리인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":3,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"닭이 두 무리 있어요. 닭은 모두 몇 마리인가요?","options":[{"t":"9","correct":true},{"t":"5","mis":"M1-1-u3-X01"},{"t":"8","mis":"M1-1-u3-X15"}],"explanation":["5마리와 4마리를 모아요.","모두 9마리예요.","센 닭에 점을 찍으며 세어요."],"asset":{"type":"group_row","groups":[{"item":"🐔","n":5},{"item":"🐔","n":4}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#4','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C2',1,'mc','auto','8을 둘로 갈랐어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C2","difficulty":1,"kind":"mc","stem":"8을 둘로 갈랐어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"8","mis":"M1-1-u3-X02"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["8을 무엇과 2로 갈랐을까요?","6과 2를 모으면 8이니 빈칸은 6이에요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":8,"parts":[null,2]},"variant_rule":{"bond":{"whole":[6,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#5','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C2',2,'sa','auto','달걀 8개를 두 바구니에 나누어 담았어요. 한 바구니에 5개를 담으면 다른 바구니에는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u3-C2","difficulty":2,"kind":"sa","stem":"달걀 8개를 두 바구니에 나누어 담았어요. 한 바구니에 5개를 담으면 다른 바구니에는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["8을 5와 무엇으로 가를까요?","5와 3을 모으면 8이니 3개예요.","두 바구니를 모으면 다시 8개예요."],"variant_rule":{"alt":[{"stem":"달걀 9개를 두 바구니에 나누어 담았어요. 한 바구니에 7개를 담으면 다른 바구니에는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["9를 7과 무엇으로 가를까요?","7과 2를 모으면 9이니 2개예요.","두 바구니를 모으면 다시 9개예요."],"asset":null},{"stem":"달걀 7개를 두 바구니에 나누어 담았어요. 한 바구니에 4개를 담으면 다른 바구니에는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["7을 4와 무엇으로 가를까요?","4와 3을 모으면 7이니 3개예요.","두 바구니를 모으면 다시 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#6','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C2',2,'ox','auto','9는 4와 4로 가를 수 있어요.',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":6,"concept":"M1-1-u3-C2","difficulty":2,"kind":"ox","stem":"9는 4와 4로 가를 수 있어요.","answer":"X","reason_options":[{"t":"4와 4를 모으면 8이니까","correct":true},{"t":"두 수가 같으면 어떤 수든 가를 수 있으니까","mis":"M1-1-u3-X02"}],"mis":"M1-1-u3-X02","explanation":["4와 4를 모으면 8이에요.","9가 아니니 9를 4와 4로 가를 수 없어요.","9는 4와 5로 가를 수 있어요."],"variant_rule":{"alt":[{"stem":"8은 4와 4로 가를 수 있어요.","answer":"O","reason_options":[{"t":"4와 4를 모으면 8이니까","correct":true},{"t":"같은 수 둘로는 가를 수 없으니까","mis":"M1-1-u3-X03"}],"explanation":["4와 4를 모으면 8이에요.","그래서 8은 4와 4로 가를 수 있어요.","같은 두 수로 가를 수도 있어요."],"asset":null},{"stem":"9는 2와 6으로 가를 수 있어요.","answer":"X","reason_options":[{"t":"2와 6을 모으면 8이니까","correct":true},{"t":"9보다 작은 두 수면 다 되니까","mis":"M1-1-u3-X02"}],"explanation":["2와 6을 모으면 8이에요.","9를 2와 6으로 가를 수 없어요.","9는 2와 7로 가를 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#7','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C1',2,'match','auto','모아서 9가 되는 두 수를 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u3-C1","difficulty":2,"kind":"match","stem":"모아서 9가 되는 두 수를 이어 보세요.","pairs":[{"l":"2","r":"7"},{"l":"3","r":"6"},{"l":"1","r":"8"}],"mis":"M1-1-u3-X01","explanation":["2와 7, 3과 6, 1과 8을 모으면 모두 9예요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 9가 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"모아서 8이 되는 두 수를 이어 보세요.","pairs":[{"l":"2","r":"6"},{"l":"3","r":"5"},{"l":"1","r":"7"}],"explanation":["2와 6, 3과 5, 1과 7을 모으면 모두 8이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 8이 되는지 확인해요."],"asset":null},{"stem":"이번에는 다른 보기예요. 모아서 9가 되는 두 수를 이어 보세요.","pairs":[{"l":"4","r":"5"},{"l":"6","r":"3"},{"l":"8","r":"1"}],"explanation":["4와 5, 6과 3, 8과 1을 모으면 모두 9예요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 9가 되는지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
