INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_basic#10','math',1,1,'u3','L03','g1_1_math_u3_L03_basic','lesson_basic','M1-1-u3-C2',3,'error','auto','하루가 9를 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":3,"kind":"error","stem":"하루가 9를 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"4와 6","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"2와 7","mis":"M1-1-u3-X02"},{"t":"8과 1","mis":"M1-1-u3-X02"}],"explanation":["4와 6을 모으면 10이에요 — 9가 아니에요.","2와 7, 8과 1은 모으면 9예요.","가른 뒤에는 꼭 다시 모아 확인해요."],"variant_rule":{"alt":[{"stem":"하루가 8을 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"3과 4","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"2와 6","mis":"M1-1-u3-X02"},{"t":"7과 1","mis":"M1-1-u3-X02"}],"explanation":["3과 4를 모으면 7이에요 — 8이 아니에요.","2와 6, 7과 1은 모으면 8이에요.","가른 뒤에는 꼭 다시 모아 확인해요."],"asset":null},{"stem":"이번에는 다른 보기예요. 하루가 9를 둘로 갈랐어요. 잘못 가른 것은 어느 것인가요?","options":[{"t":"5와 5","correct":true,"mis_target":"M1-1-u3-X02"},{"t":"3과 6","mis":"M1-1-u3-X02"},{"t":"4와 5","mis":"M1-1-u3-X02"}],"explanation":["5와 5를 모으면 10이에요 — 9가 아니에요.","3과 6, 4와 5는 모으면 9예요.","가른 뒤에는 꼭 다시 모아 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
