INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#2','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C1',2,'sa','auto','두 수를 모으면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C1","difficulty":2,"kind":"sa","stem":"두 수를 모으면 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["3과 6을 모아요.","6에서 3만큼 이어 세면 7, 8, 9 — 9예요.","순서를 바꿔 큰 수부터 세면 빨라요."],"asset":{"type":"number_bond","whole":null,"parts":[3,6]},"variant_rule":{"bond":{"whole":[6,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#3','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C2',3,'mc','auto','8을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 7, 7과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],true,'{"seq":3,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"8을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 7, 7과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"7","correct":true},{"t":"4","mis":"M1-1-u3-X03"},{"t":"8","mis":"M1-1-u3-X03"}],"explanation":["1과 7, 2와 6, 3과 5, 4와 4, 5와 3, 6과 2, 7과 1이에요.","모두 7가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"9를 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 8, 8과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"8","correct":true},{"t":"4","mis":"M1-1-u3-X03"},{"t":"9","mis":"M1-1-u3-X03"}],"explanation":["1과 8부터 8과 1까지 차례로 써요.","모두 8가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#4','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C2',3,'mc','auto','9를 둘로 가를 때, 한쪽 수가 1씩 커지면 다른 쪽 수는 어떻게 되나요?',ARRAY['M1-1-u3-X02','M1-1-u3-X03']::text[],true,'{"seq":4,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"9를 둘로 가를 때, 한쪽 수가 1씩 커지면 다른 쪽 수는 어떻게 되나요?","options":[{"t":"1씩 작아져요","correct":true},{"t":"1씩 커져요","mis":"M1-1-u3-X02"},{"t":"그대로예요","mis":"M1-1-u3-X03"}],"explanation":["1과 8, 2와 7, 3과 6 — 한쪽이 1 커지면 다른 쪽은 1 작아져요.","두 수를 모으면 언제나 9예요.","그래서 한쪽이 늘면 다른 쪽은 줄어요."],"variant_rule":{"alt":[{"stem":"8을 둘로 가를 때, 한쪽 수가 1씩 작아지면 다른 쪽 수는 어떻게 되나요?","options":[{"t":"1씩 커져요","correct":true},{"t":"1씩 작아져요","mis":"M1-1-u3-X02"},{"t":"그대로예요","mis":"M1-1-u3-X03"}],"explanation":["7과 1, 6과 2, 5와 3 — 한쪽이 1 작아지면 다른 쪽은 1 커져요.","두 수를 모으면 언제나 8이에요.","그래서 한쪽이 줄면 다른 쪽은 늘어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#5','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C1',3,'error','auto','서아가 모으기를 하고 말했어요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u3-X08','M1-1-u3-X01']::text[],true,'{"seq":5,"concept":"M1-1-u3-C1","difficulty":3,"kind":"error","stem":"서아가 모으기를 하고 말했어요. 잘못된 말은 어느 것인가요?","options":[{"t":"「5와 4를 모으면, 4와 5를 모은 것보다 커.」","correct":true,"mis_target":"M1-1-u3-X08"},{"t":"「3과 6을 모으면 9야.」","mis":"M1-1-u3-X01"},{"t":"「7과 2를 모으면 9야.」","mis":"M1-1-u3-X01"}],"explanation":["5와 4를 모아도, 4와 5를 모아도 9예요.","모으는 순서는 결과를 바꾸지 않아요.","3과 6, 7과 2는 모두 9가 맞아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 서아가 모으기를 하고 말했어요. 잘못된 말은 어느 것인가요?","options":[{"t":"「2와 6을 모으면 6이야.」","correct":true,"mis_target":"M1-1-u3-X01"},{"t":"「4와 4를 모으면 8이야.」","mis":"M1-1-u3-X01"},{"t":"「1과 7을 모으면 8이야.」","mis":"M1-1-u3-X01"}],"explanation":["2와 6을 모으면 8이에요.","큰 수 6만 답으로 썼어요.","두 수를 다 합쳐서 세어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#6','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C2',3,'ox','auto','8을 둘로 가르면 두 수 가운데 하나가 8보다 클 수도 있어요.',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":6,"concept":"M1-1-u3-C2","difficulty":3,"kind":"ox","stem":"8을 둘로 가르면 두 수 가운데 하나가 8보다 클 수도 있어요.","answer":"X","reason_options":[{"t":"가른 두 수를 모으면 다시 8이 되니까","correct":true},{"t":"수를 가르면 더 커질 수 있으니까","mis":"M1-1-u3-X02"}],"mis":"M1-1-u3-X02","explanation":["8을 가르면 두 수는 모두 8보다 작거나 같아요.","두 수를 모으면 다시 8이 되어야 해요.","가르기는 나누는 거라 커지지 않아요."],"variant_rule":{"alt":[{"stem":"9를 둘로 가른 두 수를 다시 모으면 언제나 9가 돼요.","answer":"O","reason_options":[{"t":"가르기와 모으기는 서로 반대이니까","correct":true},{"t":"가르는 방법마다 모은 수가 다르니까","mis":"M1-1-u3-X02"}],"explanation":["9를 어떻게 갈라도 두 수를 모으면 9예요.","가르기와 모으기는 서로 반대예요.","그래서 가른 뒤에는 모아 보며 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#7','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C1',3,'mc','auto','두 수를 모았더니 9가 되었어요. 한 수가 4라면 다른 수는 무엇인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":7,"concept":"M1-1-u3-C1","difficulty":3,"kind":"mc","stem":"두 수를 모았더니 9가 되었어요. 한 수가 4라면 다른 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M1-1-u3-X02"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["4와 무엇을 모으면 9일까요?","4, 5, 6, 7, 8, 9 — 4에서 5만큼 이어 세면 9예요.","그래서 다른 수는 5예요."],"variant_rule":{"alt":[{"stem":"두 수를 모았더니 8이 되었어요. 한 수가 6이라면 다른 수는 무엇인가요?","options":[{"t":"2","correct":true},{"t":"8","mis":"M1-1-u3-X02"},{"t":"14","mis":"M1-1-u3-X04"}],"explanation":["6과 무엇을 모으면 8일까요?","6과 2를 모으면 8이에요.","그래서 다른 수는 2예요."],"asset":null},{"stem":"두 수를 모았더니 7이 되었어요. 한 수가 3이라면 다른 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["3과 무엇을 모으면 7일까요?","3과 4를 모으면 7이에요.","그래서 다른 수는 4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#8','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C1',4,'mc','auto','같은 수 두 개를 모아서 8을 만들었어요. 그 수는 무엇인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X03']::text[],true,'{"seq":8,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"같은 수 두 개를 모아서 8을 만들었어요. 그 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M1-1-u3-X01"},{"t":"6","mis":"M1-1-u3-X03"}],"explanation":["같은 수 두 개 — 3과 3은 6, 4와 4는 8이에요.","그 수는 4예요.","같은 수를 하나씩 키워 가며 모아 봐요."],"variant_rule":{"alt":[{"stem":"같은 수 두 개를 모아서 6을 만들었어요. 그 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u3-X01"},{"t":"4","mis":"M1-1-u3-X03"}],"explanation":["같은 수 두 개 — 2와 2는 4, 3과 3은 6이에요.","그 수는 3이에요.","같은 수를 하나씩 키워 가며 모아 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#9','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C2',4,'mc','auto','9를 세 수로 갈랐어요. 「2, 3, (    )」 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X02']::text[],true,'{"seq":9,"concept":"M1-1-u3-C2","difficulty":4,"kind":"mc","stem":"9를 세 수로 갈랐어요. 「2, 3, (    )」 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M1-1-u3-X02"},{"t":"9","mis":"M1-1-u3-X02"}],"explanation":["2와 3을 먼저 모으면 5예요.","5와 무엇을 모으면 9일까요? — 4예요.","세 수를 모두 모아 9가 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"8을 세 수로 갈랐어요. 「1, 4, (    )」 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-1-u3-X02"},{"t":"8","mis":"M1-1-u3-X02"}],"explanation":["1과 4를 먼저 모으면 5예요.","5와 무엇을 모으면 8일까요? — 3이에요.","세 수를 모두 모아 8이 되는지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L03_challenge#10','math',1,1,'u3','L03','g1_1_math_u3_L03_challenge','lesson_challenge','M1-1-u3-C2',4,'essay','teacher','달걀 9개를 두 바구니에 나누어 담는 방법을 3가지 쓰고, 어떤 규칙으로 찾았는지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":4,"kind":"essay","stem":"달걀 9개를 두 바구니에 나누어 담는 방법을 3가지 쓰고, 어떤 규칙으로 찾았는지 말해 보세요.","answer_guide":{"answer":"예: 1개와 8개, 2개와 7개, 3개와 6개. 한쪽 바구니를 1개씩 늘리면 다른 바구니는 1개씩 줄어요.","scoring_points":["서로 다른 방법을 3가지 썼는가","두 수를 모으면 9가 되는가","한쪽이 늘면 다른 쪽이 준다는 규칙을 말했는가"]},"explanation":["한쪽 바구니의 수를 먼저 정해요.","다른 바구니는 모아서 9가 되는 수예요.","한쪽을 1씩 늘리며 다음 방법을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#1','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',1,'mc','auto','나비 3마리가 있는데 2마리가 더 날아왔어요. 나비는 모두 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":1,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"나비 3마리가 있는데 2마리가 더 날아왔어요. 나비는 모두 몇 마리인가요?","options":[{"t":"5","correct":true},{"t":"1","mis":"M1-1-u3-X04"},{"t":"3","mis":"M1-1-u3-X01"}],"explanation":["3마리에 2마리가 더 왔어요.","모두 5마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"asset":{"type":"group_row","groups":[{"item":"🦋","n":3},{"item":"🦋","n":2}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#2','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',1,'mc','auto','벌 6마리 가운데 빗금 친 2마리가 날아갔어요. 남은 벌은 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":2,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"벌 6마리 가운데 빗금 친 2마리가 날아갔어요. 남은 벌은 몇 마리인가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M1-1-u3-X04"},{"t":"2","mis":"M1-1-u3-X10"}],"explanation":["6마리에서 2마리가 날아갔어요.","남은 벌은 4마리예요.","날아간 것은 빼고 남은 것만 세어요."],"asset":{"type":"take_row","item":"🐝","n":6,"cross":2},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#3','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',1,'sa','auto','노란 꽃은 빨간 꽃보다 몇 송이 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":1,"kind":"sa","stem":"노란 꽃은 빨간 꽃보다 몇 송이 더 많은가요? 숫자로 쓰세요.","answer":["2"],"explanation":["노란 꽃과 빨간 꽃을 하나씩 짝 지어요.","짝이 없는 노란 꽃은 2송이예요.","「몇 더 많은가」는 짝 짓고 남은 것을 세어요."],"asset":{"type":"compare_groups","rows":[{"label":"노란 꽃","item":"🌼","n":6},{"label":"빨간 꽃","item":"🌹","n":4}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#4','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',1,'mc','auto','「꿀통이 3개, 4개 있어요. 모두 몇 개일까요?」 이 이야기는 무엇을 묻고 있나요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],true,'{"seq":4,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"「꿀통이 3개, 4개 있어요. 모두 몇 개일까요?」 이 이야기는 무엇을 묻고 있나요?","options":[{"t":"모으면 모두 몇인지","correct":true},{"t":"남은 것이 몇인지","mis":"M1-1-u3-X04"},{"t":"어느 쪽이 몇 더 많은지","mis":"M1-1-u3-X05"}],"explanation":["「모두 몇 개」를 묻고 있어요.","두 무리를 모으는 이야기예요.","이야기 끝의 물음을 먼저 읽어요."],"variant_rule":{"alt":[{"stem":"「사과 7개 가운데 3개를 먹었어요. 몇 개가 남았을까요?」 이 이야기는 무엇을 묻고 있나요?","options":[{"t":"남은 것이 몇인지","correct":true},{"t":"모으면 모두 몇인지","mis":"M1-1-u3-X04"},{"t":"어느 쪽이 몇 더 많은지","mis":"M1-1-u3-X05"}],"explanation":["「몇 개가 남았을까요」를 묻고 있어요.","덜어 내는 이야기예요.","이야기 끝의 물음을 먼저 읽어요."],"asset":null},{"stem":"「연필이 5자루, 지우개가 3개 있어요. 연필이 몇 개 더 많을까요?」 이 이야기는 무엇을 묻고 있나요?","options":[{"t":"어느 쪽이 몇 더 많은지","correct":true},{"t":"모으면 모두 몇인지","mis":"M1-1-u3-X05"},{"t":"남은 것이 몇인지","mis":"M1-1-u3-X10"}],"explanation":["「몇 개 더 많을까요」를 묻고 있어요.","두 무리를 견주는 이야기예요.","이야기 끝의 물음을 먼저 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#5','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',2,'match','auto','이야기와 알맞은 물음을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u3-C3","difficulty":2,"kind":"match","stem":"이야기와 알맞은 물음을 이어 보세요.","pairs":[{"l":"나비가 더 날아왔어요","r":"모두 몇 마리일까요"},{"l":"벌이 날아갔어요","r":"남은 것은 몇 마리일까요"},{"l":"꽃을 하나씩 짝 지었어요","r":"몇 송이 더 많을까요"}],"mis":"M1-1-u3-X04","explanation":["더 오면 「모두 몇」, 날아가면 「남은 것」이에요.","짝 지으면 「몇 더 많은가」예요.","이야기에서 무슨 일이 일어났는지 먼저 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기와 알맞은 물음을 이어 보세요.","pairs":[{"l":"친구가 사탕을 더 주었어요","r":"모두 몇 개일까요"},{"l":"사탕을 동생에게 주었어요","r":"남은 것은 몇 개일까요"},{"l":"사탕과 젤리를 견주었어요","r":"몇 개 더 많을까요"}],"explanation":["더 받으면 「모두 몇」, 주면 「남은 것」이에요.","견주면 「몇 더 많은가」예요.","이야기에서 무슨 일이 일어났는지 먼저 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#6','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',2,'mc','auto','그림을 보고 만든 이야기로 알맞은 것은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":6,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"그림을 보고 만든 이야기로 알맞은 것은 어느 것인가요?","options":[{"t":"사과 5개 가운데 2개를 먹어서 3개가 남았어요.","correct":true},{"t":"사과 5개와 2개를 모으면 7개예요.","mis":"M1-1-u3-X04"},{"t":"사과를 먹고 2개가 남았어요.","mis":"M1-1-u3-X10"}],"explanation":["빗금 친 2개는 먹은 사과예요.","5개에서 2개를 먹어 3개가 남았어요.","빗금은 덜어 낸 것, 나머지는 남은 것이에요."],"asset":{"type":"take_row","item":"🍎","n":5,"cross":2},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 만든 이야기로 알맞은 것은 어느 것인가요?","options":[{"t":"오리 4마리에 3마리가 더 와서 모두 7마리예요.","correct":true},{"t":"오리 4마리 가운데 3마리가 가서 1마리가 남았어요.","mis":"M1-1-u3-X04"},{"t":"오리가 모두 4마리예요.","mis":"M1-1-u3-X01"}],"explanation":["두 무리가 모여 있어요.","4마리와 3마리를 모으면 7마리예요.","그림에서 무리가 모이는지 덜어 내는지 봐요."],"asset":{"type":"group_row","groups":[{"item":"🦆","n":4},{"item":"🦆","n":3}],"op":"+"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#7','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',2,'ox','auto','「연못에 오리 4마리가 있었는데 3마리가 더 왔어요.」는 남은 것을 구하는 이야기예요.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":7,"concept":"M1-1-u3-C3","difficulty":2,"kind":"ox","stem":"「연못에 오리 4마리가 있었는데 3마리가 더 왔어요.」는 남은 것을 구하는 이야기예요.","answer":"X","reason_options":[{"t":"더 왔으니 모두 몇 마리인지 구하는 이야기니까","correct":true},{"t":"수가 두 개 나오면 언제나 남은 것을 구하니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["오리가 더 왔어요.","모두 몇 마리인지 구하는 이야기예요.","「더 왔다」·「모였다」는 모두 몇을 구해요."],"variant_rule":{"alt":[{"stem":"「풍선 6개 가운데 2개가 터졌어요.」는 남은 것을 구하는 이야기예요.","answer":"O","reason_options":[{"t":"터져서 없어졌으니 남은 것을 구하니까","correct":true},{"t":"수가 두 개 나오면 언제나 모두 몇을 구하니까","mis":"M1-1-u3-X04"}],"explanation":["풍선이 터져서 없어졌어요.","남은 것을 구하는 이야기예요.","「없어졌다」·「먹었다」는 남은 것을 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#8','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',2,'sa','auto','꿀벌이 꿀을 두 번 모았어요. 모은 꿀은 모두 몇 통인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u3-C3","difficulty":2,"kind":"sa","stem":"꿀벌이 꿀을 두 번 모았어요. 모은 꿀은 모두 몇 통인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["2통과 5통을 모아요.","모두 7통이에요.","큰 수 5에서 이어 세면 6, 7이에요."],"asset":{"type":"group_row","groups":[{"item":"🍯","n":2},{"item":"🍯","n":5}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#9','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',2,'mc','auto','접시에 쿠키가 7개 있었어요. 3개를 먹었어요. 남은 쿠키는 몇 개인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":9,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"접시에 쿠키가 7개 있었어요. 3개를 먹었어요. 남은 쿠키는 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"10","mis":"M1-1-u3-X04"},{"t":"3","mis":"M1-1-u3-X10"}],"explanation":["7개에서 3개를 먹었어요.","남은 쿠키는 4개예요.","먹은 것은 빼고 남은 것만 세어요."],"variant_rule":{"addsub":{"op":"sub","ask":"story","story":"take"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_basic#10','math',1,1,'u3','L04','g1_1_math_u3_L04_basic','lesson_basic','M1-1-u3-C3',3,'error','auto','서아가 그림을 보고 이야기를 만들었어요. 잘못 만든 것은 어느 것인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X04']::text[],true,'{"seq":10,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"서아가 그림을 보고 이야기를 만들었어요. 잘못 만든 것은 어느 것인가요?","options":[{"t":"「강아지와 고양이를 모으면 모두 2마리예요.」","correct":true,"mis_target":"M1-1-u3-X05"},{"t":"「강아지가 고양이보다 2마리 더 많아요.」","mis":"M1-1-u3-X05"},{"t":"「강아지와 고양이는 모두 8마리예요.」","mis":"M1-1-u3-X04"}],"explanation":["강아지 5마리와 고양이 3마리를 모으면 8마리예요.","2는 「몇 더 많은가」의 답이에요.","모두 몇인지와 몇 더 많은지를 가르세요."],"asset":{"type":"compare_groups","rows":[{"label":"강아지","item":"🐶","n":5},{"label":"고양이","item":"🐱","n":3}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 서아가 그림을 보고 이야기를 만들었어요. 잘못 만든 것은 어느 것인가요?","options":[{"t":"「딸기가 귤보다 9개 더 많아요.」","correct":true,"mis_target":"M1-1-u3-X05"},{"t":"「딸기와 귤은 모두 9개예요.」","mis":"M1-1-u3-X04"},{"t":"「딸기가 귤보다 3개 더 많아요.」","mis":"M1-1-u3-X05"}],"explanation":["딸기 6개와 귤 3개를 짝 지으면 딸기 3개가 남아요.","9는 「모두 몇」의 답이에요.","모두 몇인지와 몇 더 많은지를 가르세요."],"asset":{"type":"compare_groups","rows":[{"label":"딸기","item":"🍓","n":6},{"label":"귤","item":"🍊","n":3}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#1','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',2,'mc','auto','딸기는 귤보다 몇 개 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":1,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"딸기는 귤보다 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"11","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["딸기와 귤을 하나씩 짝 지어요.","짝이 없는 딸기는 3개예요.","「몇 더 많은가」는 모으지 않아요."],"asset":{"type":"compare_groups","rows":[{"label":"딸기","item":"🍓","n":7},{"label":"귤","item":"🍊","n":4}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#2','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',2,'sa','auto','나뭇가지에 참새가 3마리 앉아 있었어요. 4마리가 더 날아왔어요. 참새는 모두 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C3","difficulty":2,"kind":"sa","stem":"나뭇가지에 참새가 3마리 앉아 있었어요. 4마리가 더 날아왔어요. 참새는 모두 몇 마리인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["3마리에 4마리가 더 왔어요.","모두 7마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"variant_rule":{"addsub":{"op":"add","ask":"story"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#3','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',3,'mc','auto','다음 가운데 「남은 것」을 구하는 이야기는 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 「남은 것」을 구하는 이야기는 어느 것인가요?","options":[{"t":"풍선 6개 가운데 2개가 터졌어요.","correct":true},{"t":"풍선 6개에 2개를 더 불었어요.","mis":"M1-1-u3-X04"},{"t":"빨간 풍선이 파란 풍선보다 많아요.","mis":"M1-1-u3-X05"}],"explanation":["터진 풍선은 없어졌어요.","그래서 남은 것을 구하는 이야기예요.","더 불면 모두 몇, 견주면 몇 더 많은가예요."],"variant_rule":{"alt":[{"stem":"다음 가운데 「몇 더 많은가」를 구하는 이야기는 어느 것인가요?","options":[{"t":"사자 5마리와 호랑이 2마리를 하나씩 짝 지었어요.","correct":true},{"t":"사자 5마리에 2마리가 더 왔어요.","mis":"M1-1-u3-X04"},{"t":"사자 5마리 가운데 2마리가 잠들러 갔어요.","mis":"M1-1-u3-X10"}],"explanation":["짝 지으면 남는 것이 몇 더 많은 수예요.","그래서 「몇 더 많은가」를 구해요.","더 오면 모두 몇, 가 버리면 남은 것이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#4','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',3,'mc','auto','「모두 몇 개인가」를 묻는 이야기가 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C3","difficulty":3,"kind":"mc","stem":"「모두 몇 개인가」를 묻는 이야기가 아닌 것은 어느 것인가요?","options":[{"t":"사탕 8개 가운데 3개를 동생에게 주었어요.","correct":true},{"t":"사탕 5개와 3개를 한 봉지에 담았어요.","mis":"M1-1-u3-X04"},{"t":"사탕 4개가 있는데 2개를 더 받았어요.","mis":"M1-1-u3-X04"}],"explanation":["동생에게 주면 사탕이 줄어요.","남은 것을 묻는 이야기예요.","담거나 더 받으면 모두 몇 개인지 물어요."],"variant_rule":{"alt":[{"stem":"「남은 것」을 묻는 이야기가 아닌 것은 어느 것인가요?","options":[{"t":"구슬 3개가 있는데 친구가 4개를 더 주었어요.","correct":true},{"t":"구슬 7개 가운데 4개를 잃어버렸어요.","mis":"M1-1-u3-X04"},{"t":"구슬 9개 가운데 2개를 친구에게 주었어요.","mis":"M1-1-u3-X04"}],"explanation":["더 받으면 구슬이 늘어요.","모두 몇 개인지 묻는 이야기예요.","잃어버리거나 주면 남은 것을 물어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#5','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',3,'ox','auto','「노란 꽃이 빨간 꽃보다 몇 송이 더 많은가」를 알려면 두 수를 모아야 해요.',ARRAY['M1-1-u3-X05']::text[],true,'{"seq":5,"concept":"M1-1-u3-C3","difficulty":3,"kind":"ox","stem":"「노란 꽃이 빨간 꽃보다 몇 송이 더 많은가」를 알려면 두 수를 모아야 해요.","answer":"X","reason_options":[{"t":"하나씩 짝 짓고 남는 것을 세어야 하니까","correct":true},{"t":"많은지 알려면 모두 모아서 세면 되니까","mis":"M1-1-u3-X05"}],"mis":"M1-1-u3-X05","explanation":["견주는 이야기는 모으지 않아요.","하나씩 짝 짓고 남는 것을 세요.","모으면 「모두 몇」이 되어 버려요."],"variant_rule":{"alt":[{"stem":"「강아지가 고양이보다 몇 마리 더 많은가」는 하나씩 짝 짓고 남는 것을 세면 알 수 있어요.","answer":"O","reason_options":[{"t":"짝이 없이 남는 강아지가 더 많은 수니까","correct":true},{"t":"두 수를 모으면 더 많은 수가 나오니까","mis":"M1-1-u3-X05"}],"explanation":["강아지와 고양이를 하나씩 짝 지어요.","남는 강아지 수가 더 많은 수예요.","모으면 「모두 몇」이 되어 버려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#6','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',3,'mc','auto','개구리 8마리 가운데 빗금 친 개구리가 뛰어 나갔어요. 연못에 남은 개구리는 몇 마리인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":6,"concept":"M1-1-u3-C3","difficulty":3,"kind":"mc","stem":"개구리 8마리 가운데 빗금 친 개구리가 뛰어 나갔어요. 연못에 남은 개구리는 몇 마리인가요?","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-1-u3-X10"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["8마리에서 5마리가 뛰어 나갔어요.","남은 개구리는 3마리예요.","나간 개구리는 빼고 남은 것만 세어요."],"asset":{"type":"take_row","item":"🐸","n":8,"cross":5},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#7','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',3,'error','auto','하루가 이야기를 만들었어요. 「바구니에 귤이 6개 있었어요. 2개를 더 넣었어요. 남은 귤은 몇 개일까요?」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],true,'{"seq":7,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"하루가 이야기를 만들었어요. 「바구니에 귤이 6개 있었어요. 2개를 더 넣었어요. 남은 귤은 몇 개일까요?」 무엇이 잘못되었나요?","options":[{"t":"더 넣었으니 「모두 몇 개」를 물어야 해요","correct":true,"mis_target":"M1-1-u3-X04"},{"t":"「몇 개 더 많은가」를 물어야 해요","mis":"M1-1-u3-X05"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X04"}],"explanation":["귤을 더 넣으면 귤이 늘어요.","「남은 귤」이 아니라 「모두 몇 개」를 물어야 해요.","일어난 일과 물음이 맞는지 봐요."],"variant_rule":{"alt":[{"stem":"하루가 이야기를 만들었어요. 「연못에 오리가 7마리 있었어요. 3마리가 날아갔어요. 오리는 모두 몇 마리일까요?」 무엇이 잘못되었나요?","options":[{"t":"날아갔으니 「남은 것은 몇 마리」를 물어야 해요","correct":true,"mis_target":"M1-1-u3-X04"},{"t":"「몇 마리 더 많은가」를 물어야 해요","mis":"M1-1-u3-X05"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X04"}],"explanation":["오리가 날아가면 줄어요.","「모두 몇」이 아니라 「남은 것」을 물어야 해요.","일어난 일과 물음이 맞는지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#8','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',4,'mc','auto','그림으로 만들 수 없는 이야기는 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],true,'{"seq":8,"concept":"M1-1-u3-C3","difficulty":4,"kind":"mc","stem":"그림으로 만들 수 없는 이야기는 어느 것인가요?","options":[{"t":"「공 5개 가운데 3개를 버렸어요.」","correct":true},{"t":"「공은 모두 8개예요.」","mis":"M1-1-u3-X04"},{"t":"「빨간 공이 파란 공보다 2개 더 많아요.」","mis":"M1-1-u3-X05"}],"explanation":["그림에는 빨간 공과 파란 공이 따로 있어요.","모으거나 견주는 이야기는 되지만 버린 공은 그림에 없어요.","그림에서 일어난 일을 먼저 봐요."],"asset":{"type":"compare_groups","rows":[{"label":"빨간 공","item":"🔴","n":5},{"label":"파란 공","item":"🔵","n":3}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림으로 만들 수 없는 이야기는 어느 것인가요?","options":[{"t":"「별 4개와 달 2개를 모으면 모두 8개예요.」","correct":true},{"t":"「별이 달보다 2개 더 많아요.」","mis":"M1-1-u3-X05"},{"t":"「별과 달은 모두 6개예요.」","mis":"M1-1-u3-X04"}],"explanation":["별 4개와 달 2개를 모으면 6개예요.","8개라는 이야기는 그림과 맞지 않아요.","이야기의 수를 그림과 맞춰 봐요."],"asset":{"type":"compare_groups","rows":[{"label":"별","item":"⭐","n":4},{"label":"달","item":"🌙","n":2}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#9','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',4,'mc','auto','도윤이는 구슬이 4개 있어요. 서아는 도윤이보다 2개 더 많이 가지고 있어요. 서아의 구슬은 몇 개인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":9,"concept":"M1-1-u3-C3","difficulty":4,"kind":"mc","stem":"도윤이는 구슬이 4개 있어요. 서아는 도윤이보다 2개 더 많이 가지고 있어요. 서아의 구슬은 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"2","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["서아는 도윤이보다 2개 더 많아요.","4개에 2개를 더하면 6개예요.","누가 더 많은지 먼저 정해요."],"variant_rule":{"alt":[{"stem":"유나는 딱지가 7장 있어요. 하루는 유나보다 3장 더 적게 가지고 있어요. 하루의 딱지는 몇 장인가요?","options":[{"t":"4","correct":true},{"t":"10","mis":"M1-1-u3-X05"},{"t":"3","mis":"M1-1-u3-X10"}],"explanation":["하루는 유나보다 3장 적어요.","7장에서 3장을 덜면 4장이에요.","누가 더 많은지 먼저 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L04_challenge#10','math',1,1,'u3','L04','g1_1_math_u3_L04_challenge','lesson_challenge','M1-1-u3-C3',4,'essay','teacher','그림을 보고 「모두 몇」을 묻는 이야기와 「남은 것」을 묻는 이야기를 하나씩 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C3","difficulty":4,"kind":"essay","stem":"그림을 보고 「모두 몇」을 묻는 이야기와 「남은 것」을 묻는 이야기를 하나씩 만들어 보세요.","answer_guide":{"answer":"모두 몇: 벌 4마리가 있는데 3마리가 더 날아왔어요. 벌은 모두 몇 마리일까요? (7마리) / 남은 것: 벌 7마리 가운데 3마리가 날아갔어요. 남은 벌은 몇 마리일까요? (4마리)","scoring_points":["「모두 몇」 이야기에 모으거나 더 오는 일이 있는가","「남은 것」 이야기에 덜어 내는 일이 있는가","이야기의 수가 그림과 맞는가"]},"explanation":["그림 속 수 4와 3을 먼저 찾아요.","더 오는 이야기와 가 버리는 이야기를 떠올려요.","이야기 끝에 물음을 꼭 넣어요."],"asset":{"type":"group_row","groups":[{"item":"🐝","n":4},{"item":"🐝","n":3}],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#1','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',1,'mc','auto','그림에 알맞은 덧셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 덧셈식은 어느 것인가요?","options":[{"t":"3 + 2 = 5","correct":true},{"t":"3 − 2 = 1","mis":"M1-1-u3-X04"},{"t":"3 + 2 = 6","mis":"M1-1-u3-X15"}],"explanation":["벌 3마리와 2마리를 모아요.","덧셈식으로 3 + 2 = 5예요.","모으는 그림은 + 로 나타내요."],"asset":{"type":"group_row","groups":[{"item":"🐝","n":3},{"item":"🐝","n":2}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#2','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',1,'mc','auto','「4 + 3 = 7」을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":2,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"「4 + 3 = 7」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"4 더하기 3은 7과 같습니다","correct":true},{"t":"4 빼기 3은 7과 같습니다","mis":"M1-1-u3-X06"},{"t":"4와 3은 7보다 큽니다","mis":"M1-1-u3-X06"}],"explanation":["+ 는 「더하기」, = 는 「같습니다」라고 읽어요.","4 더하기 3은 7과 같습니다.","「4와 3의 합은 7입니다」라고도 읽어요."],"variant_rule":{"alt":[{"stem":"「2 + 6 = 8」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"2와 6의 합은 8입니다","correct":true},{"t":"2와 6의 차는 8입니다","mis":"M1-1-u3-X06"},{"t":"2 더하기 6은 8보다 큽니다","mis":"M1-1-u3-X06"}],"explanation":["+ 로 모은 수를 「합」이라고 해요.","2와 6의 합은 8입니다.","「2 더하기 6은 8과 같습니다」라고도 읽어요."],"asset":null},{"stem":"「5 + 1 = 6」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"5 더하기 1은 6과 같습니다","correct":true},{"t":"5 빼기 1은 6과 같습니다","mis":"M1-1-u3-X06"},{"t":"5와 1은 6보다 작습니다","mis":"M1-1-u3-X06"}],"explanation":["+ 는 「더하기」, = 는 「같습니다」라고 읽어요.","5 더하기 1은 6과 같습니다.","「5와 1의 합은 6입니다」라고도 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#3','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',1,'sa','auto','2 + 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u3-C4","difficulty":1,"kind":"sa","stem":"2 + 4는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2와 4를 모아요.","2 + 4 = 6이에요.","큰 수 4에서 2만큼 이어 세면 5, 6이에요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#4','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',1,'blank','auto','「5와 2의 합은 7입니다」를 덧셈식으로 쓰면 「5 (    ) 2 = 7」이에요.',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":1,"kind":"blank","stem":"「5와 2의 합은 7입니다」를 덧셈식으로 쓰면 「5 (    ) 2 = 7」이에요.","options":[{"t":"+","correct":true},{"t":"−","mis":"M1-1-u3-X06"},{"t":"=","mis":"M1-1-u3-X06"}],"explanation":["「합」은 더한 수예요.","그래서 + 를 써서 5 + 2 = 7이에요.","= 는 양쪽이 같다는 뜻이라 식 끝에 와요."],"variant_rule":{"alt":[{"stem":"「3 더하기 4는 7과 같습니다」를 덧셈식으로 쓰면 「3 + 4 (    ) 7」이에요.","options":[{"t":"=","correct":true},{"t":"+","mis":"M1-1-u3-X06"},{"t":"−","mis":"M1-1-u3-X06"}],"explanation":["「같습니다」는 = 로 써요.","3 + 4 = 7이에요.","+ 는 「더하기」, = 는 「같습니다」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#5','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',2,'mc','auto','나비가 모여 있는데 몇 마리가 더 날아왔어요. 알맞은 덧셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C4","difficulty":2,"kind":"mc","stem":"나비가 모여 있는데 몇 마리가 더 날아왔어요. 알맞은 덧셈식은 어느 것인가요?","options":[{"t":"4 + 4 = 8","correct":true},{"t":"4 − 4 = 0","mis":"M1-1-u3-X04"},{"t":"4 + 4 = 9","mis":"M1-1-u3-X15"}],"explanation":["4마리에 4마리가 더 왔어요.","4 + 4 = 8이에요.","더 오는 그림은 + 로 나타내요."],"asset":{"type":"group_row","groups":[{"item":"🦋","n":4},{"item":"🦋","n":4}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#6','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',2,'ox','auto','6 + 1 = 7 입니다.',ARRAY['M1-1-u3-X01']::text[],true,'{"seq":6,"concept":"M1-1-u3-C4","difficulty":2,"kind":"ox","stem":"6 + 1 = 7 입니다.","answer":"O","reason_options":[{"t":"6과 1을 모으면 7이 되니까","correct":true},{"t":"두 수 가운데 큰 수가 답이니까","mis":"M1-1-u3-X01"}],"mis":"M1-1-u3-X01","explanation":["6과 1을 모으면 7이에요.","7이에요 — 맞아요.","1을 더하면 바로 다음 수예요."],"variant_rule":{"addsub":{"op":"add","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#7','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',2,'match','auto','덧셈식과 읽는 말을 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u3-C4","difficulty":2,"kind":"match","stem":"덧셈식과 읽는 말을 이어 보세요.","pairs":[{"l":"2 + 5 = 7","r":"2 더하기 5는 7과 같습니다"},{"l":"3 + 3 = 6","r":"3과 3의 합은 6입니다"},{"l":"1 + 7 = 8","r":"1 더하기 7은 8과 같습니다"}],"mis":"M1-1-u3-X06","explanation":["+ 는 「더하기」 또는 「합」으로 읽어요.","= 는 「같습니다」·「입니다」로 읽어요.","식의 수와 말의 수가 같은지 짚어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 덧셈식과 읽는 말을 이어 보세요.","pairs":[{"l":"4 + 2 = 6","r":"4 더하기 2는 6과 같습니다"},{"l":"5 + 4 = 9","r":"5와 4의 합은 9입니다"},{"l":"6 + 2 = 8","r":"6 더하기 2는 8과 같습니다"}],"explanation":["+ 는 「더하기」 또는 「합」으로 읽어요.","= 는 「같습니다」·「입니다」로 읽어요.","식의 수와 말의 수가 같은지 짚어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#8','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',2,'mc','auto','꽃밭에 노란 꽃이 2송이, 빨간 꽃이 5송이 피었어요. 꽃은 모두 몇 송이인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":8,"concept":"M1-1-u3-C4","difficulty":2,"kind":"mc","stem":"꽃밭에 노란 꽃이 2송이, 빨간 꽃이 5송이 피었어요. 꽃은 모두 몇 송이인가요?","options":[{"t":"7","correct":true},{"t":"3","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X01"}],"explanation":["2송이와 5송이를 모아요.","2 + 5 = 7, 모두 7송이예요.","「모두 몇」은 덧셈으로 구해요."],"variant_rule":{"addsub":{"op":"add","ask":"story"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#9','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',2,'mc','auto','덧셈식에 쓰는 「=」는 무엇을 뜻하나요?',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":9,"concept":"M1-1-u3-C4","difficulty":2,"kind":"mc","stem":"덧셈식에 쓰는 「=」는 무엇을 뜻하나요?","options":[{"t":"양쪽이 같아요","correct":true},{"t":"더해요","mis":"M1-1-u3-X06"},{"t":"오른쪽이 더 커요","mis":"M1-1-u3-X06"}],"explanation":["= 는 「같습니다」라는 뜻이에요.","3 + 4 = 7은 3 + 4와 7이 같다는 말이에요.","+ 가 「더해요」를 뜻해요."],"variant_rule":{"alt":[{"stem":"덧셈식에 쓰는 「+」는 무엇을 뜻하나요?","options":[{"t":"더해요","correct":true},{"t":"양쪽이 같아요","mis":"M1-1-u3-X06"},{"t":"덜어 내요","mis":"M1-1-u3-X04"}],"explanation":["+ 는 「더하기」라는 뜻이에요.","두 수를 모을 때 써요.","= 는 양쪽이 같다는 뜻이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_basic#10','math',1,1,'u3','L05','g1_1_math_u3_L05_basic','lesson_basic','M1-1-u3-C4',3,'error','auto','지우가 덧셈식을 썼어요. 잘못 쓴 것은 어느 것인가요?',ARRAY['M1-1-u3-X15','M1-1-u3-X06']::text[],true,'{"seq":10,"concept":"M1-1-u3-C4","difficulty":3,"kind":"error","stem":"지우가 덧셈식을 썼어요. 잘못 쓴 것은 어느 것인가요?","options":[{"t":"「2 + 6 = 9」","correct":true,"mis_target":"M1-1-u3-X15"},{"t":"「4 + 1 = 5」","mis":"M1-1-u3-X06"},{"t":"「3 + 3 = 6」","mis":"M1-1-u3-X06"}],"explanation":["2와 6을 모으면 8이에요 — 9가 아니에요.","4 + 1 = 5, 3 + 3 = 6은 맞아요.","다 쓴 뒤 다시 세어 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 지우가 덧셈식을 썼어요. 잘못 쓴 것은 어느 것인가요?","options":[{"t":"「7 − 2 = 9」","correct":true,"mis_target":"M1-1-u3-X06"},{"t":"「5 + 2 = 7」","mis":"M1-1-u3-X06"},{"t":"「1 + 8 = 9」","mis":"M1-1-u3-X06"}],"explanation":["7과 2를 모았는데 − 를 썼어요.","모으면 + 를 써서 7 + 2 = 9예요.","기호와 계산이 맞는지 같이 봐요."],"asset":null},{"stem":"이번에는 다른 보기예요. 지우가 덧셈식을 썼어요. 잘못 쓴 것은 어느 것인가요?","options":[{"t":"「3 + 5 = 7」","correct":true,"mis_target":"M1-1-u3-X15"},{"t":"「2 + 2 = 4」","mis":"M1-1-u3-X06"},{"t":"「6 + 3 = 9」","mis":"M1-1-u3-X06"}],"explanation":["3과 5를 모으면 8이에요 — 7이 아니에요.","2 + 2 = 4, 6 + 3 = 9는 맞아요.","다 쓴 뒤 다시 세어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#1','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',2,'mc','auto','그림에 알맞은 덧셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C4","difficulty":2,"kind":"mc","stem":"그림에 알맞은 덧셈식은 어느 것인가요?","options":[{"t":"2 + 6 = 8","correct":true},{"t":"6 − 2 = 4","mis":"M1-1-u3-X04"},{"t":"2 + 6 = 9","mis":"M1-1-u3-X15"}],"explanation":["무당벌레 2마리와 6마리를 모아요.","2 + 6 = 8이에요.","모으는 그림은 + 로 나타내요."],"asset":{"type":"group_row","groups":[{"item":"🐞","n":2},{"item":"🐞","n":6}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#2','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',2,'sa','auto','3 + 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C4","difficulty":2,"kind":"sa","stem":"3 + 5는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["3과 5를 모아요.","3 + 5 = 8이에요.","큰 수 5에서 3만큼 이어 세면 6, 7, 8이에요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#3','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',3,'mc','auto','「나비 5마리가 모여 있는데 3마리가 더 날아왔어요.」를 덧셈식으로 바르게 쓴 것은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":3,"concept":"M1-1-u3-C4","difficulty":3,"kind":"mc","stem":"「나비 5마리가 모여 있는데 3마리가 더 날아왔어요.」를 덧셈식으로 바르게 쓴 것은 어느 것인가요?","options":[{"t":"5 + 3 = 8","correct":true},{"t":"5 − 3 = 2","mis":"M1-1-u3-X04"},{"t":"5 + 3 = 9","mis":"M1-1-u3-X15"}],"explanation":["5마리에 3마리가 더 왔어요.","5 + 3 = 8이에요.","더 오는 이야기는 덧셈식으로 써요."],"variant_rule":{"addsub":{"op":"add","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#4','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',3,'mc','auto','「□ + 2 = 6」에서 □에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":3,"kind":"mc","stem":"「□ + 2 = 6」에서 □에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M1-1-u3-X02"},{"t":"8","mis":"M1-1-u3-X04"}],"explanation":["무엇에 2를 더하면 6일까요?","4 + 2 = 6 — □는 4예요.","□에 답을 넣어 다시 계산해 봐요."],"variant_rule":{"addsub":{"op":"add","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#5','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',3,'error','auto','친구들이 「3 + 5 = 8」을 읽었어요. 잘못 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":5,"concept":"M1-1-u3-C4","difficulty":3,"kind":"error","stem":"친구들이 「3 + 5 = 8」을 읽었어요. 잘못 읽은 것은 어느 것인가요?","options":[{"t":"「3 더하기 5는 8보다 큽니다.」","correct":true,"mis_target":"M1-1-u3-X06"},{"t":"「3과 5의 합은 8입니다.」","mis":"M1-1-u3-X06"},{"t":"「3 더하기 5는 8과 같습니다.」","mis":"M1-1-u3-X06"}],"explanation":["= 는 「같습니다」라는 뜻이에요.","「8보다 큽니다」는 틀린 말이에요.","+ 는 더하기·합, = 는 같습니다예요."],"variant_rule":{"alt":[{"stem":"친구들이 「4 + 2 = 6」을 읽었어요. 잘못 읽은 것은 어느 것인가요?","options":[{"t":"「4와 2의 차는 6입니다.」","correct":true,"mis_target":"M1-1-u3-X06"},{"t":"「4와 2의 합은 6입니다.」","mis":"M1-1-u3-X06"},{"t":"「4 더하기 2는 6과 같습니다.」","mis":"M1-1-u3-X06"}],"explanation":["+ 로 모은 수는 「합」이에요.","「차」는 뺄셈에서 써요.","+ 는 더하기·합으로 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#6','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',3,'ox','auto','「4 + 2 = 6」과 「6 = 4 + 2」는 같은 뜻이에요.',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":6,"concept":"M1-1-u3-C4","difficulty":3,"kind":"ox","stem":"「4 + 2 = 6」과 「6 = 4 + 2」는 같은 뜻이에요.","answer":"O","reason_options":[{"t":"「=」는 양쪽이 같다는 뜻이니까","correct":true},{"t":"답은 늘 「=」 오른쪽에만 써야 하니까","mis":"M1-1-u3-X06"}],"mis":"M1-1-u3-X06","explanation":["= 는 왼쪽과 오른쪽이 같다는 뜻이에요.","6과 4 + 2는 같으니 두 식 모두 맞아요.","= 를 「답은」으로만 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「3 + 4 = 7」의 「=」는 「그리고」라는 뜻이에요.","answer":"X","reason_options":[{"t":"「=」는 양쪽이 같다는 뜻이니까","correct":true},{"t":"두 수 다음에 오는 말이니까","mis":"M1-1-u3-X06"}],"explanation":["= 는 「같습니다」라는 뜻이에요.","3 + 4와 7이 같다는 말이에요.","「그리고」는 + 쪽에 가까운 말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#7','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',3,'mc','auto','합이 7인 덧셈식은 어느 것인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C4","difficulty":3,"kind":"mc","stem":"합이 7인 덧셈식은 어느 것인가요?","options":[{"t":"2 + 5","correct":true},{"t":"2 + 7","mis":"M1-1-u3-X02"},{"t":"3 + 3","mis":"M1-1-u3-X15"}],"explanation":["2 + 5 = 7이에요.","2 + 7 = 9, 3 + 3 = 6이에요.","두 수를 하나씩 모아 확인해요."],"variant_rule":{"alt":[{"stem":"합이 8인 덧셈식은 어느 것인가요?","options":[{"t":"3 + 5","correct":true},{"t":"3 + 8","mis":"M1-1-u3-X02"},{"t":"4 + 3","mis":"M1-1-u3-X15"}],"explanation":["3 + 5 = 8이에요.","3 + 8은 8보다 크고, 4 + 3 = 7이에요.","두 수를 하나씩 모아 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#8','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',4,'mc','auto','그림을 보고 지우는 「3 + 4 = 7」, 서아는 「4 + 3 = 7」이라고 썼어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u3-X08','M1-1-u3-X06']::text[],true,'{"seq":8,"concept":"M1-1-u3-C4","difficulty":4,"kind":"mc","stem":"그림을 보고 지우는 「3 + 4 = 7」, 서아는 「4 + 3 = 7」이라고 썼어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요 — 모은 수는 같아요","correct":true},{"t":"지우만 맞아요 — 앞의 무리부터 써야 해요","mis":"M1-1-u3-X08"},{"t":"둘 다 틀렸어요 — 7 + 0이어야 해요","mis":"M1-1-u3-X06"}],"explanation":["딸기 3개와 4개를 어느 쪽부터 모아도 7개예요.","3 + 4 = 7, 4 + 3 = 7 둘 다 맞아요.","덧셈은 두 수의 순서를 바꾸어도 합이 같아요."],"asset":{"type":"group_row","groups":[{"item":"🍓","n":3},{"item":"🍓","n":4}],"op":"+"},"variant_rule":{"alt":[{"stem":"그림을 보고 하루는 「2 + 5 = 7」, 유나는 「5 + 2 = 7」이라고 썼어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요 — 모은 수는 같아요","correct":true},{"t":"하루만 맞아요 — 왼쪽 무리부터 써야 해요","mis":"M1-1-u3-X08"},{"t":"유나만 맞아요 — 큰 수를 먼저 써야 해요","mis":"M1-1-u3-X08"}],"explanation":["2개와 5개를 어느 쪽부터 모아도 7개예요.","두 식 모두 맞아요.","덧셈은 순서를 바꾸어도 합이 같아요."],"asset":{"type":"group_row","groups":[{"item":"🍎","n":2},{"item":"🍎","n":5}],"op":"+"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#9','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',4,'mc','auto','어떤 수에 3을 더했더니 9가 되었어요. 어떤 수에 2를 더하면 얼마인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X15']::text[],true,'{"seq":9,"concept":"M1-1-u3-C4","difficulty":4,"kind":"mc","stem":"어떤 수에 3을 더했더니 9가 되었어요. 어떤 수에 2를 더하면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"6","mis":"M1-1-u3-X02"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["□ + 3 = 9 — 어떤 수는 6이에요.","6 + 2 = 8이에요.","어떤 수를 먼저 찾고 나서 다시 더해요."],"variant_rule":{"alt":[{"stem":"어떤 수에 4를 더했더니 7이 되었어요. 어떤 수에 5를 더하면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"3","mis":"M1-1-u3-X02"},{"t":"9","mis":"M1-1-u3-X15"}],"explanation":["□ + 4 = 7 — 어떤 수는 3이에요.","3 + 5 = 8이에요.","어떤 수를 먼저 찾고 나서 다시 더해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L05_challenge#10','math',1,1,'u3','L05','g1_1_math_u3_L05_challenge','lesson_challenge','M1-1-u3-C4',4,'essay','teacher','「2 + 5 = 7」에 맞는 이야기를 만들고, 이야기에서 2, 5, 7이 각각 무엇인지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C4","difficulty":4,"kind":"essay","stem":"「2 + 5 = 7」에 맞는 이야기를 만들고, 이야기에서 2, 5, 7이 각각 무엇인지 써 보세요.","answer_guide":{"answer":"예: 연못에 오리 2마리가 있었는데 5마리가 더 왔어요. 오리는 모두 7마리예요. 2는 처음 있던 오리, 5는 더 온 오리, 7은 모두 모인 오리예요.","scoring_points":["모으거나 더 오는 이야기인가","이야기의 수가 2, 5, 7과 맞는가","세 수가 각각 무엇인지 말했는가"]},"explanation":["2와 5가 모이는 장면을 떠올려요.","이야기 끝에 「모두 몇」을 넣어요.","7은 모두 모인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#1','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',1,'mc','auto','6부터 2번 이어 세면 얼마인가요?',ARRAY['M1-1-u3-X07','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C5","difficulty":1,"kind":"mc","stem":"6부터 2번 이어 세면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"7","mis":"M1-1-u3-X07"},{"t":"9","mis":"M1-1-u3-X15"}],"explanation":["6은 이미 있는 수예요 — 7부터 세어요.","7, 8 — 2번 이어 세면 8이에요.","처음 수는 다시 세지 않아요."],"asset":{"type":"count_on","start":6,"steps":2,"dir":"up"},"variant_rule":{"counton":{"dir":"up","start":[1,6],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#2','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',1,'sa','auto','5 + 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C5","difficulty":1,"kind":"sa","stem":"5 + 3은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["5에서 3만큼 이어 세요 — 6, 7, 8.","5 + 3 = 8이에요.","큰 수에서 이어 세면 빨라요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#3','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',1,'mc','auto','십 배열판에 6개가 있고, 2개를 더 놓았어요. 6 + 2는 얼마인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":3,"concept":"M1-1-u3-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 6개가 있고, 2개를 더 놓았어요. 6 + 2는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"4","mis":"M1-1-u3-X04"},{"t":"6","mis":"M1-1-u3-X01"}],"explanation":["십 배열판에서 놓인 칸을 모두 세어요.","6 + 2 = 8이에요.","빈칸이 2개 남았으니 10보다 2 작은 8이에요."],"asset":{"type":"ten_frame","filled":6,"add":2},"variant_rule":{"alt":[{"stem":"십 배열판에 5개가 있고, 3개를 더 놓았어요. 5 + 3은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X01"}],"explanation":["십 배열판에서 놓인 칸을 모두 세어요.","5 + 3 = 8이에요.","첫 줄 5칸이 다 차고 둘째 줄에 3칸이에요."],"asset":{"type":"ten_frame","filled":5,"add":3}},{"stem":"십 배열판에 4개가 있고, 3개를 더 놓았어요. 4 + 3은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M1-1-u3-X04"},{"t":"4","mis":"M1-1-u3-X01"}],"explanation":["십 배열판에서 놓인 칸을 모두 세어요.","4 + 3 = 7이에요.","빈칸이 3개 남았으니 10보다 3 작은 7이에요."],"asset":{"type":"ten_frame","filled":4,"add":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#4','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',1,'mc','auto','2 + 7은 얼마인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":4,"concept":"M1-1-u3-C5","difficulty":1,"kind":"mc","stem":"2 + 7은 얼마인가요?","options":[{"t":"9","correct":true},{"t":"5","mis":"M1-1-u3-X04"},{"t":"7","mis":"M1-1-u3-X01"}],"explanation":["7에서 2만큼 이어 세요 — 8, 9.","2 + 7 = 9예요.","순서를 바꿔 큰 수부터 세면 빨라요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#5','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',2,'ox','auto','3 + 6과 6 + 3의 합은 같아요.',ARRAY['M1-1-u3-X08']::text[],true,'{"seq":5,"concept":"M1-1-u3-C5","difficulty":2,"kind":"ox","stem":"3 + 6과 6 + 3의 합은 같아요.","answer":"O","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 오는 수가 크면 합도 크니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["3 + 6 = 9, 6 + 3 = 9예요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."],"variant_rule":{"alt":[{"stem":"1 + 8의 합이 8 + 1의 합보다 작아요.","answer":"X","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 작은 수가 오면 합도 작으니까","mis":"M1-1-u3-X08"}],"explanation":["1 + 8 = 9, 8 + 1 = 9예요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#6','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',2,'mc','auto','딸기를 모두 모으면 몇 개인가요?',ARRAY['M1-1-u3-X15','M1-1-u3-X04']::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":2,"kind":"mc","stem":"딸기를 모두 모으면 몇 개인가요?","options":[{"t":"9","correct":true},{"t":"8","mis":"M1-1-u3-X15"},{"t":"1","mis":"M1-1-u3-X04"}],"explanation":["5개와 4개를 모아요.","5 + 4 = 9예요.","센 딸기에 점을 찍으며 세어요."],"asset":{"type":"group_row","groups":[{"item":"🍓","n":5},{"item":"🍓","n":4}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#7','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',2,'blank','auto','규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":7,"concept":"M1-1-u3-C5","difficulty":2,"kind":"blank","stem":"규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"8","correct":true},{"t":"7","mis":"M1-1-u3-X14"},{"t":"9","mis":"M1-1-u3-X14"}],"explanation":["더하는 수가 1씩 커져요.","그래서 합도 1씩 커져요 — 5, 6, 7 다음은 8이에요.","2 + 6 = 8로 확인해요."],"asset":{"type":"expr_grid","rows":[["2 + 3","2 + 4","2 + 5","2 + 6"],["5","6","7",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"9","correct":true},{"t":"8","mis":"M1-1-u3-X14"},{"t":"7","mis":"M1-1-u3-X14"}],"explanation":["앞의 수가 1씩 커져요.","그래서 합도 1씩 커져요 — 6, 7, 8 다음은 9예요.","6 + 3 = 9로 확인해요."],"asset":{"type":"expr_grid","rows":[["3 + 3","4 + 3","5 + 3","6 + 3"],["6","7","8",null]]}},{"stem":"이번에는 다른 보기예요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"7","correct":true},{"t":"8","mis":"M1-1-u3-X14"},{"t":"6","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","그래서 합은 언제나 7이에요.","4 + 3 = 7로 확인해요."],"asset":{"type":"expr_grid","rows":[["1 + 6","2 + 5","3 + 4","4 + 3"],["7","7","7",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#8','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',2,'mc','auto','달걀이 왼쪽에 3개, 오른쪽에 5개 있어요. 두 덧셈식으로 나타낸 것은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X06']::text[],true,'{"seq":8,"concept":"M1-1-u3-C5","difficulty":2,"kind":"mc","stem":"달걀이 왼쪽에 3개, 오른쪽에 5개 있어요. 두 덧셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"3 + 5 = 8, 5 + 3 = 8","correct":true},{"t":"3 + 5 = 8, 5 − 3 = 2","mis":"M1-1-u3-X04"},{"t":"3 + 5 = 8, 8 + 3 = 11","mis":"M1-1-u3-X06"}],"explanation":["왼쪽부터 모으면 3 + 5, 오른쪽부터 모으면 5 + 3이에요.","두 식 모두 8이에요.","덧셈은 순서를 바꾸어도 합이 같아요."],"asset":{"type":"group_row","groups":[{"item":"🥚","n":3},{"item":"🥚","n":5}],"op":"+"},"variant_rule":{"alt":[{"stem":"구슬이 왼쪽에 2개, 오른쪽에 7개 있어요. 두 덧셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"2 + 7 = 9, 7 + 2 = 9","correct":true},{"t":"2 + 7 = 9, 7 − 2 = 5","mis":"M1-1-u3-X04"},{"t":"2 + 7 = 9, 9 + 2 = 11","mis":"M1-1-u3-X06"}],"explanation":["왼쪽부터 2 + 7, 오른쪽부터 7 + 2예요.","두 식 모두 9예요.","덧셈은 순서를 바꾸어도 합이 같아요."],"asset":{"type":"group_row","groups":[{"item":"🔵","n":2},{"item":"🔵","n":7}],"op":"+"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#9','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',2,'sa','auto','4부터 3번 이어 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-1-u3-C5","difficulty":2,"kind":"sa","stem":"4부터 3번 이어 세면 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["4는 이미 있는 수예요 — 5부터 세어요.","5, 6, 7 — 7이에요.","그래서 4 + 3 = 7이에요."],"asset":{"type":"count_on","start":4,"steps":3,"dir":"up"},"variant_rule":{"counton":{"dir":"up","start":[1,6],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_basic#10','math',1,1,'u3','L06','g1_1_math_u3_L06_basic','lesson_basic','M1-1-u3-C5',3,'error','auto','하루가 5 + 3을 이어 세기로 풀었어요. 「5, 6, 7 — 답은 7이야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X07','M1-1-u3-X04']::text[],true,'{"seq":10,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"하루가 5 + 3을 이어 세기로 풀었어요. 「5, 6, 7 — 답은 7이야!」 무엇이 잘못되었나요?","options":[{"t":"5를 다시 세었어요 — 6, 7, 8로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"5 + 3은 뺄셈으로 풀어야 해요","mis":"M1-1-u3-X04"}],"explanation":["5는 이미 있는 수라 다시 세지 않아요.","6, 7, 8 — 답은 8이에요.","이어 셀 때는 다음 수부터 세어요."],"variant_rule":{"alt":[{"stem":"유나가 4 + 2를 이어 세기로 풀었어요. 「4, 5 — 답은 5야!」 무엇이 잘못되었나요?","options":[{"t":"4를 다시 세었어요 — 5, 6으로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"2부터 세어야 해요","mis":"M1-1-u3-X08"}],"explanation":["4는 이미 있는 수라 다시 세지 않아요.","5, 6 — 답은 6이에요.","이어 셀 때는 다음 수부터 세어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#1','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',2,'mc','auto','7부터 2번 이어 세면 얼마인가요?',ARRAY['M1-1-u3-X07','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C5","difficulty":2,"kind":"mc","stem":"7부터 2번 이어 세면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"8","mis":"M1-1-u3-X07"},{"t":"10","mis":"M1-1-u3-X15"}],"explanation":["7은 이미 있는 수예요 — 8부터 세어요.","8, 9 — 9예요.","처음 수는 다시 세지 않아요."],"asset":{"type":"count_on","start":7,"steps":2,"dir":"up"},"variant_rule":{"counton":{"dir":"up","start":[1,6],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#2','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',2,'sa','auto','4 + 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C5","difficulty":2,"kind":"sa","stem":"4 + 4는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["4에서 4만큼 이어 세요 — 5, 6, 7, 8.","4 + 4 = 8이에요.","같은 수 두 개를 모으면 짝수가 돼요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#3','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',3,'mc','auto','합이 6인 덧셈식을 규칙에 맞게 늘어놓았어요. 빈칸에 들어갈 식은 어느 것인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":3,"concept":"M1-1-u3-C5","difficulty":3,"kind":"mc","stem":"합이 6인 덧셈식을 규칙에 맞게 늘어놓았어요. 빈칸에 들어갈 식은 어느 것인가요?","options":[{"t":"3 + 3","correct":true},{"t":"3 + 4","mis":"M1-1-u3-X14"},{"t":"6 + 0","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1, 2, 3… 커지고 뒤의 수는 5, 4, 3… 작아져요.","빈칸은 3 + 3이에요.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["1 + 5","2 + 4",null,"4 + 2","5 + 1"]]},"variant_rule":{"alt":[{"stem":"합이 7인 덧셈식을 규칙에 맞게 늘어놓았어요. 빈칸에 들어갈 식은 어느 것인가요?","options":[{"t":"4 + 3","correct":true},{"t":"4 + 4","mis":"M1-1-u3-X14"},{"t":"7 + 0","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","빈칸은 4 + 3이에요.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["1 + 6","2 + 5","3 + 4",null,"5 + 2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#4','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',3,'mc','auto','「□ + 3 = 8」에서 □에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C5","difficulty":3,"kind":"mc","stem":"「□ + 3 = 8」에서 □에 알맞은 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M1-1-u3-X02"},{"t":"11","mis":"M1-1-u3-X04"}],"explanation":["무엇에 3을 더하면 8일까요?","5 + 3 = 8 — □는 5예요.","□에 답을 넣어 다시 계산해 봐요."],"variant_rule":{"addsub":{"op":"add","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#5','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',3,'ox','auto','2 + 7을 계산할 때 7부터 이어 세면 더 빨라요.',ARRAY['M1-1-u3-X08']::text[],true,'{"seq":5,"concept":"M1-1-u3-C5","difficulty":3,"kind":"ox","stem":"2 + 7을 계산할 때 7부터 이어 세면 더 빨라요.","answer":"O","reason_options":[{"t":"큰 수에서 작은 수만큼 이어 세면 셀 것이 적으니까","correct":true},{"t":"앞에 있는 수부터 세어야만 답이 맞으니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["7부터 2만큼 이어 세면 8, 9 — 두 번이면 돼요.","2부터 7만큼 세면 일곱 번 세야 해요.","순서를 바꾸어도 합은 같으니 큰 수부터 세어요."],"variant_rule":{"alt":[{"stem":"1 + 6은 꼭 1부터 6번 이어 세어야 해요.","answer":"X","reason_options":[{"t":"순서를 바꾸어도 합이 같으니 6부터 1번 세도 되니까","correct":true},{"t":"덧셈은 쓰인 순서대로만 세어야 하니까","mis":"M1-1-u3-X08"}],"explanation":["1 + 6과 6 + 1은 합이 같아요.","6부터 1번 세면 7 — 한 번에 끝나요.","큰 수부터 이어 세면 빨라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#6','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',3,'mc','auto','공깃돌을 두 손에 나누어 쥐었어요. 왼손에 4개, 오른손에 몇 개를 쥐었더니 모두 7개였어요. 오른손에는 몇 개가 있나요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":3,"kind":"mc","stem":"공깃돌을 두 손에 나누어 쥐었어요. 왼손에 4개, 오른손에 몇 개를 쥐었더니 모두 7개였어요. 오른손에는 몇 개가 있나요?","options":[{"t":"3","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"11","mis":"M1-1-u3-X04"}],"explanation":["4 + □ = 7 — 4에 무엇을 더하면 7일까요?","4, 5, 6, 7 — 3만큼 이어 세면 7이에요.","그래서 오른손에는 3개예요."],"variant_rule":{"alt":[{"stem":"공깃돌을 두 손에 나누어 쥐었어요. 왼손에 2개, 오른손에 몇 개를 쥐었더니 모두 9개였어요. 오른손에는 몇 개가 있나요?","options":[{"t":"7","correct":true},{"t":"9","mis":"M1-1-u3-X02"},{"t":"11","mis":"M1-1-u3-X04"}],"explanation":["2 + □ = 9 — 2에 무엇을 더하면 9일까요?","2와 7을 모으면 9예요.","그래서 오른손에는 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#7','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',3,'error','auto','친구들이 「6 + 3」을 풀었어요. 잘못 푼 친구는 누구인가요?',ARRAY['M1-1-u3-X07','M1-1-u3-X08','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 「6 + 3」을 풀었어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"하루: 「6부터 이어 세면 6, 7, 8이니까 8이야.」","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"서아: 「3 + 6으로 바꿔도 9야.」","mis":"M1-1-u3-X08"},{"t":"도이: 「십 배열판에 6개, 3개를 놓으면 9야.」","mis":"M1-1-u3-X15"}],"explanation":["6은 이미 있는 수예요 — 7, 8, 9로 세어야 해요.","하루는 6을 다시 세었어요.","서아·도이처럼 풀면 9가 나와요."],"variant_rule":{"alt":[{"stem":"친구들이 「3 + 4」를 풀었어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"유나: 「3 + 4는 4 + 3보다 작아.」","correct":true,"mis_target":"M1-1-u3-X08"},{"t":"하루: 「4부터 이어 세면 5, 6, 7이야.」","mis":"M1-1-u3-X07"},{"t":"지우: 「3과 4를 모으면 7이야.」","mis":"M1-1-u3-X01"}],"explanation":["3 + 4와 4 + 3은 둘 다 7이에요.","순서를 바꾸어도 합은 같아요.","하루와 지우는 바르게 풀었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#8','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',4,'mc','auto','합이 8인 덧셈식을 「1 + 7」부터 차례로 쓰면 모두 몇 개인가요? (1 + 7과 7 + 1은 다른 식으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":8,"concept":"M1-1-u3-C5","difficulty":4,"kind":"mc","stem":"합이 8인 덧셈식을 「1 + 7」부터 차례로 쓰면 모두 몇 개인가요? (1 + 7과 7 + 1은 다른 식으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"7","correct":true},{"t":"4","mis":"M1-1-u3-X14"},{"t":"8","mis":"M1-1-u3-X14"}],"explanation":["1 + 7, 2 + 6, 3 + 5, 4 + 4, 5 + 3, 6 + 2, 7 + 1이에요.","모두 7개예요.","앞의 수를 1씩 늘리면 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"합이 5인 덧셈식을 「1 + 4」부터 차례로 쓰면 모두 몇 개인가요? (1 + 4와 4 + 1은 다른 식으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u3-X14"},{"t":"5","mis":"M1-1-u3-X14"}],"explanation":["1 + 4, 2 + 3, 3 + 2, 4 + 1이에요.","모두 4개예요.","앞의 수를 1씩 늘리면 빠뜨리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#9','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',4,'mc','auto','4 + 3 = 7이에요. 그러면 4 + 4는 얼마인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":9,"concept":"M1-1-u3-C5","difficulty":4,"kind":"mc","stem":"4 + 3 = 7이에요. 그러면 4 + 4는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"7","mis":"M1-1-u3-X14"},{"t":"9","mis":"M1-1-u3-X14"}],"explanation":["더하는 수가 3에서 4로 1 커졌어요.","그래서 합도 7에서 1 커진 8이에요.","아는 식에서 출발하면 빨라요."],"variant_rule":{"alt":[{"stem":"5 + 2 = 7이에요. 그러면 5 + 1은 얼마인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M1-1-u3-X14"},{"t":"8","mis":"M1-1-u3-X14"}],"explanation":["더하는 수가 2에서 1로 1 작아졌어요.","그래서 합도 7에서 1 작아진 6이에요.","아는 식에서 출발하면 빨라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L06_challenge#10','math',1,1,'u3','L06','g1_1_math_u3_L06_challenge','lesson_challenge','M1-1-u3-C5',4,'essay','teacher','3 + 5를 계산하는 방법을 두 가지(이어 세기, 십 배열판, 모두 세기 가운데) 쓰고, 어느 방법이 더 편한지 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C5","difficulty":4,"kind":"essay","stem":"3 + 5를 계산하는 방법을 두 가지(이어 세기, 십 배열판, 모두 세기 가운데) 쓰고, 어느 방법이 더 편한지 까닭을 써 보세요.","answer_guide":{"answer":"예: 이어 세기 — 5부터 6, 7, 8. 십 배열판 — 3칸과 5칸을 칠하면 8칸. 이어 세기가 편해요. 큰 수 5부터 세 번만 세면 되니까요.","scoring_points":["두 가지 방법을 바르게 썼는가","두 방법 모두 답이 8인가","편한 까닭을 말했는가"]},"explanation":["한 가지 방법으로 먼저 풀어요.","다른 방법으로 다시 풀어 답이 같은지 봐요.","어느 쪽이 셀 것이 적은지 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#1','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',1,'mc','auto','딸기 6개 가운데 빗금 친 2개를 따 갔어요. 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"딸기 6개 가운데 빗금 친 2개를 따 갔어요. 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"6 − 2 = 4","correct":true},{"t":"6 + 2 = 8","mis":"M1-1-u3-X04"},{"t":"6 − 2 = 5","mis":"M1-1-u3-X15"}],"explanation":["6개에서 2개를 덜어 냈어요.","뺄셈식으로 6 − 2 = 4예요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🍓","n":6,"cross":2},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#2','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',1,'mc','auto','「7 − 3 = 4」를 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06','M1-1-u3-X11']::text[],true,'{"seq":2,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"「7 − 3 = 4」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"7 빼기 3은 4와 같습니다","correct":true},{"t":"7 더하기 3은 4와 같습니다","mis":"M1-1-u3-X06"},{"t":"3 빼기 7은 4와 같습니다","mis":"M1-1-u3-X11"}],"explanation":["− 는 「빼기」라고 읽어요.","7 빼기 3은 4와 같습니다.","「7과 3의 차는 4입니다」라고도 읽어요."],"variant_rule":{"alt":[{"stem":"「9 − 5 = 4」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"9와 5의 차는 4입니다","correct":true},{"t":"9와 5의 합은 4입니다","mis":"M1-1-u3-X06"},{"t":"5와 9의 차는 14입니다","mis":"M1-1-u3-X06"}],"explanation":["− 로 구한 수를 「차」라고 해요.","9와 5의 차는 4입니다.","「9 빼기 5는 4와 같습니다」라고도 읽어요."],"asset":null},{"stem":"「8 − 6 = 2」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"8 빼기 6은 2와 같습니다","correct":true},{"t":"8 더하기 6은 2와 같습니다","mis":"M1-1-u3-X06"},{"t":"6 빼기 8은 2와 같습니다","mis":"M1-1-u3-X11"}],"explanation":["− 는 「빼기」라고 읽어요.","8 빼기 6은 2와 같습니다.","처음에 있던 수 8을 먼저 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#3','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',1,'sa','auto','8 − 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u3-C6","difficulty":1,"kind":"sa","stem":"8 − 3은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["8에서 3을 덜어 내요.","8 − 3 = 5예요.","8부터 거꾸로 7, 6, 5 — 세 번 세어도 돼요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#4','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',1,'blank','auto','「9와 4의 차는 5입니다」를 뺄셈식으로 쓰면 「9 (    ) 4 = 5」예요.',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":4,"concept":"M1-1-u3-C6","difficulty":1,"kind":"blank","stem":"「9와 4의 차는 5입니다」를 뺄셈식으로 쓰면 「9 (    ) 4 = 5」예요.","options":[{"t":"−","correct":true},{"t":"+","mis":"M1-1-u3-X06"},{"t":"=","mis":"M1-1-u3-X06"}],"explanation":["「차」는 뺄셈으로 구한 수예요.","그래서 − 를 써서 9 − 4 = 5예요.","「합」이면 + , 「차」면 − 예요."],"variant_rule":{"alt":[{"stem":"「6 빼기 2는 4와 같습니다」를 뺄셈식으로 쓰면 「6 − 2 (    ) 4」예요.","options":[{"t":"=","correct":true},{"t":"−","mis":"M1-1-u3-X06"},{"t":"+","mis":"M1-1-u3-X06"}],"explanation":["「같습니다」는 = 로 써요.","6 − 2 = 4예요.","− 는 「빼기」, = 는 「같습니다」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#5','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',2,'mc','auto','세모는 네모보다 몇 개 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":2,"kind":"mc","stem":"세모는 네모보다 몇 개 더 많은가요?","options":[{"t":"2","correct":true},{"t":"10","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["세모와 네모를 하나씩 짝 지어요.","짝이 없는 세모는 2개 — 6 − 4 = 2예요.","견주는 그림도 뺄셈으로 나타내요."],"asset":{"type":"compare_groups","rows":[{"label":"세모","item":"🔺","n":6},{"label":"네모","item":"🟦","n":4}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#6','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',2,'ox','auto','5 − 2 = 3 입니다.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":6,"concept":"M1-1-u3-C6","difficulty":2,"kind":"ox","stem":"5 − 2 = 3 입니다.","answer":"O","reason_options":[{"t":"5에서 2를 빼면 3이 되니까","correct":true},{"t":"뺄셈도 두 수를 모으는 것이니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["5에서 2를 덜어 내요.","3이에요 — 맞아요.","덜어 낸 것은 세지 않고 남은 것만 세어요."],"variant_rule":{"addsub":{"op":"sub","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#7','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',2,'match','auto','뺄셈식과 읽는 말을 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u3-C6","difficulty":2,"kind":"match","stem":"뺄셈식과 읽는 말을 이어 보세요.","pairs":[{"l":"8 − 5 = 3","r":"8 빼기 5는 3과 같습니다"},{"l":"6 − 1 = 5","r":"6과 1의 차는 5입니다"},{"l":"9 − 2 = 7","r":"9 빼기 2는 7과 같습니다"}],"mis":"M1-1-u3-X06","explanation":["− 는 「빼기」 또는 「차」로 읽어요.","= 는 「같습니다」·「입니다」로 읽어요.","식의 수와 말의 수가 같은지 짚어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 뺄셈식과 읽는 말을 이어 보세요.","pairs":[{"l":"7 − 4 = 3","r":"7 빼기 4는 3과 같습니다"},{"l":"5 − 3 = 2","r":"5와 3의 차는 2입니다"},{"l":"9 − 1 = 8","r":"9 빼기 1은 8과 같습니다"}],"explanation":["− 는 「빼기」 또는 「차」로 읽어요.","= 는 「같습니다」·「입니다」로 읽어요.","식의 수와 말의 수가 같은지 짚어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#8','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',2,'mc','auto','그림을 보고 「몇 마리 더 많은지」를 식으로 나타낸 것은 어느 것인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C6","difficulty":2,"kind":"mc","stem":"그림을 보고 「몇 마리 더 많은지」를 식으로 나타낸 것은 어느 것인가요?","options":[{"t":"7 − 3 = 4","correct":true},{"t":"7 + 3 = 10","mis":"M1-1-u3-X05"},{"t":"7 − 3 = 5","mis":"M1-1-u3-X15"}],"explanation":["강아지와 고양이를 하나씩 짝 지으면 강아지 4마리가 남아요.","7 − 3 = 4예요.","견주는 그림도 − 로 나타내요."],"asset":{"type":"compare_groups","rows":[{"label":"강아지","item":"🐶","n":7},{"label":"고양이","item":"🐱","n":3}]},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#9','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',2,'mc','auto','풍선이 8개 있었어요. 3개가 터졌어요. 남은 풍선은 몇 개인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":9,"concept":"M1-1-u3-C6","difficulty":2,"kind":"mc","stem":"풍선이 8개 있었어요. 3개가 터졌어요. 남은 풍선은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"11","mis":"M1-1-u3-X04"},{"t":"3","mis":"M1-1-u3-X10"}],"explanation":["8개에서 3개가 터졌어요.","8 − 3 = 5, 남은 풍선은 5개예요.","없어지는 이야기는 뺄셈이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"story","story":"take"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_basic#10','math',1,1,'u3','L08','g1_1_math_u3_L08_basic','lesson_basic','M1-1-u3-C6',3,'error','auto','도윤이가 그림을 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X10']::text[],true,'{"seq":10,"concept":"M1-1-u3-C6","difficulty":3,"kind":"error","stem":"도윤이가 그림을 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「뺄셈식은 4 − 7 = 3이에요.」","correct":true,"mis_target":"M1-1-u3-X11"},{"t":"「사과 7개에서 4개를 덜어 냈어요.」","mis":"M1-1-u3-X11"},{"t":"「남은 사과는 3개예요.」","mis":"M1-1-u3-X10"}],"explanation":["처음에 있던 수 7을 앞에 써야 해요.","바른 식은 7 − 4 = 3이에요.","뺄셈식은 「처음 수 − 덜어 낸 수」예요."],"asset":{"type":"take_row","item":"🍎","n":7,"cross":4},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 도윤이가 그림을 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「남은 쿠키는 3개예요.」","correct":true,"mis_target":"M1-1-u3-X10"},{"t":"「쿠키 8개에서 3개를 덜어 냈어요.」","mis":"M1-1-u3-X11"},{"t":"「뺄셈식은 8 − 3 = 5예요.」","mis":"M1-1-u3-X11"}],"explanation":["빗금 친 3개는 덜어 낸 쿠키예요.","남은 쿠키는 5개예요.","덜어 낸 수와 남은 수를 가르세요."],"asset":{"type":"take_row","item":"🍪","n":8,"cross":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#1','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',2,'mc','auto','그림에 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C6","difficulty":2,"kind":"mc","stem":"그림에 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"9 − 3 = 6","correct":true},{"t":"9 + 3 = 12","mis":"M1-1-u3-X04"},{"t":"9 − 3 = 7","mis":"M1-1-u3-X15"}],"explanation":["9개에서 빗금 친 3개를 덜어 냈어요.","9 − 3 = 6이에요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🍪","n":9,"cross":3},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#2','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',2,'sa','auto','7 − 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C6","difficulty":2,"kind":"sa","stem":"7 − 5는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["7에서 5를 덜어 내요.","7 − 5 = 2예요.","5와 2를 모으면 7이니 2예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#3','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',3,'mc','auto','「연필이 6자루, 지우개가 2개 있어요. 연필은 지우개보다 몇 개 더 많은가요?」 알맞은 식은 어느 것인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X15']::text[],true,'{"seq":3,"concept":"M1-1-u3-C6","difficulty":3,"kind":"mc","stem":"「연필이 6자루, 지우개가 2개 있어요. 연필은 지우개보다 몇 개 더 많은가요?」 알맞은 식은 어느 것인가요?","options":[{"t":"6 − 2 = 4","correct":true},{"t":"6 + 2 = 8","mis":"M1-1-u3-X05"},{"t":"6 − 2 = 3","mis":"M1-1-u3-X15"}],"explanation":["연필과 지우개를 하나씩 짝 지으면 연필 4자루가 남아요.","6 − 2 = 4예요.","「몇 개 더 많은가」도 뺄셈이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"expr","story":"compare"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#4','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',3,'mc','auto','「9 − □ = 4」에서 □에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C6","difficulty":3,"kind":"mc","stem":"「9 − □ = 4」에서 □에 알맞은 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u3-X10"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["9에서 얼마를 빼야 4가 남을까요?","9 − 5 = 4 — □는 5예요.","4와 □를 모으면 9가 돼요."],"variant_rule":{"addsub":{"op":"sub","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#5','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',3,'ox','auto','「8 − 3」과 「3 − 8」은 같은 뜻이에요.',ARRAY['M1-1-u3-X08']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":3,"kind":"ox","stem":"「8 − 3」과 「3 − 8」은 같은 뜻이에요.","answer":"X","reason_options":[{"t":"뺄셈은 처음 수에서 덜어 내니 순서를 바꾸면 안 되니까","correct":true},{"t":"덧셈처럼 순서를 바꾸어도 같으니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["8 − 3은 8개에서 3개를 덜어 내는 거예요.","3개에서 8개는 덜어 낼 수 없어요.","뺄셈은 덧셈과 달리 순서를 바꾸면 안 돼요."],"variant_rule":{"alt":[{"stem":"뺄셈식은 처음에 있던 수를 − 앞에 써요.","answer":"O","reason_options":[{"t":"처음 수에서 덜어 낸 수를 빼니까","correct":true},{"t":"작은 수를 먼저 써야 하니까","mis":"M1-1-u3-X11"}],"explanation":["8개에서 3개를 먹었으면 8 − 3이에요.","처음에 있던 수가 앞이에요.","덜어 낸 수는 − 뒤에 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#6','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',3,'mc','auto','(가) 사탕 8개 가운데 3개를 먹었어요. (나) 사탕 8개와 초콜릿 3개를 견주었어요. 뺄셈으로 나타낼 수 있는 것은 어느 것인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X04']::text[],true,'{"seq":6,"concept":"M1-1-u3-C6","difficulty":3,"kind":"mc","stem":"(가) 사탕 8개 가운데 3개를 먹었어요. (나) 사탕 8개와 초콜릿 3개를 견주었어요. 뺄셈으로 나타낼 수 있는 것은 어느 것인가요?","options":[{"t":"(가)와 (나) 둘 다","correct":true},{"t":"(가)만","mis":"M1-1-u3-X05"},{"t":"(나)만","mis":"M1-1-u3-X04"}],"explanation":["(가)는 덜어 내는 이야기 — 8 − 3이에요.","(나)는 견주는 이야기 — 이것도 8 − 3이에요.","덜어 내기와 견주기는 모두 뺄셈이에요."],"variant_rule":{"alt":[{"stem":"(가) 연못의 오리 7마리 가운데 2마리가 날아갔어요. (나) 오리 7마리와 거위 2마리를 견주었어요. 뺄셈으로 나타낼 수 있는 것은 어느 것인가요?","options":[{"t":"(가)와 (나) 둘 다","correct":true},{"t":"(가)만","mis":"M1-1-u3-X05"},{"t":"(나)만","mis":"M1-1-u3-X04"}],"explanation":["(가)는 덜어 내는 이야기 — 7 − 2예요.","(나)는 견주는 이야기 — 이것도 7 − 2예요.","덜어 내기와 견주기는 모두 뺄셈이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#7','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',3,'error','auto','친구들이 「6 − 4 = 2」를 읽었어요. 잘못 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],true,'{"seq":7,"concept":"M1-1-u3-C6","difficulty":3,"kind":"error","stem":"친구들이 「6 − 4 = 2」를 읽었어요. 잘못 읽은 것은 어느 것인가요?","options":[{"t":"「6과 4의 합은 2입니다.」","correct":true,"mis_target":"M1-1-u3-X06"},{"t":"「6 빼기 4는 2와 같습니다.」","mis":"M1-1-u3-X06"},{"t":"「6과 4의 차는 2입니다.」","mis":"M1-1-u3-X06"}],"explanation":["− 로 구한 수는 「차」예요.","「합」은 덧셈에서 써요.","+ 는 합, − 는 차예요."],"variant_rule":{"alt":[{"stem":"친구들이 「9 − 7 = 2」를 읽었어요. 잘못 읽은 것은 어느 것인가요?","options":[{"t":"「7 빼기 9는 2와 같습니다.」","correct":true,"mis_target":"M1-1-u3-X11"},{"t":"「9 빼기 7은 2와 같습니다.」","mis":"M1-1-u3-X06"},{"t":"「9와 7의 차는 2입니다.」","mis":"M1-1-u3-X06"}],"explanation":["식에 쓰인 순서대로 9를 먼저 읽어요.","9 빼기 7은 2와 같습니다.","뺄셈은 순서를 바꾸면 뜻이 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#8','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',4,'mc','auto','두 수의 차가 3인 뺄셈식이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X11']::text[],true,'{"seq":8,"concept":"M1-1-u3-C6","difficulty":4,"kind":"mc","stem":"두 수의 차가 3인 뺄셈식이 아닌 것은 어느 것인가요?","options":[{"t":"6 − 2","correct":true},{"t":"5 − 2","mis":"M1-1-u3-X10"},{"t":"9 − 6","mis":"M1-1-u3-X11"}],"explanation":["6 − 2 = 4예요.","5 − 2 = 3, 9 − 6 = 3이에요.","하나씩 계산해 확인해요."],"variant_rule":{"alt":[{"stem":"두 수의 차가 2인 뺄셈식이 아닌 것은 어느 것인가요?","options":[{"t":"7 − 2","correct":true},{"t":"7 − 5","mis":"M1-1-u3-X10"},{"t":"4 − 2","mis":"M1-1-u3-X11"}],"explanation":["7 − 2 = 5예요.","7 − 5 = 2, 4 − 2 = 2예요.","하나씩 계산해 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#9','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',4,'mc','auto','지우는 구슬이 9개 있어요. 서아는 지우보다 4개 더 적게 가지고 있어요. 서아의 구슬은 몇 개인가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":9,"concept":"M1-1-u3-C6","difficulty":4,"kind":"mc","stem":"지우는 구슬이 9개 있어요. 서아는 지우보다 4개 더 적게 가지고 있어요. 서아의 구슬은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["서아는 지우보다 4개 적어요.","9 − 4 = 5, 서아는 5개예요.","「더 적게」는 많은 쪽에서 빼요."],"variant_rule":{"alt":[{"stem":"하루는 딱지가 8장 있어요. 도이는 하루보다 5장 더 적게 가지고 있어요. 도이의 딱지는 몇 장인가요?","options":[{"t":"3","correct":true},{"t":"13","mis":"M1-1-u3-X05"},{"t":"5","mis":"M1-1-u3-X10"}],"explanation":["도이는 하루보다 5장 적어요.","8 − 5 = 3, 도이는 3장이에요.","「더 적게」는 많은 쪽에서 빼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L08_challenge#10','math',1,1,'u3','L08','g1_1_math_u3_L08_challenge','lesson_challenge','M1-1-u3-C6',4,'essay','teacher','「7 − 2 = 5」에 맞는 이야기를 「덜어 내는 이야기」와 「견주는 이야기」로 하나씩 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C6","difficulty":4,"kind":"essay","stem":"「7 − 2 = 5」에 맞는 이야기를 「덜어 내는 이야기」와 「견주는 이야기」로 하나씩 만들어 보세요.","answer_guide":{"answer":"덜어 내기: 사과 7개 가운데 2개를 먹었어요. 남은 사과는 5개예요. / 견주기: 사과가 7개, 배가 2개 있어요. 사과가 배보다 5개 더 많아요.","scoring_points":["덜어 내는 이야기에 7, 2, 5가 맞게 들어갔는가","견주는 이야기에 「몇 더 많은가」가 들어갔는가","두 이야기 모두 뺄셈에 맞는가"]},"explanation":["7개에서 2개가 없어지는 장면을 떠올려요.","7개와 2개를 나란히 놓는 장면도 떠올려요.","두 이야기 모두 답은 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#1','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',1,'mc','auto','9부터 3번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"9부터 3번 거꾸로 세면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M1-1-u3-X09"},{"t":"5","mis":"M1-1-u3-X15"}],"explanation":["9는 이미 있는 수예요 — 8부터 세어요.","8, 7, 6 — 6이에요.","그래서 9 − 3 = 6이에요."],"asset":{"type":"count_on","start":9,"steps":3,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#2','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',1,'sa','auto','6 − 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C7","difficulty":1,"kind":"sa","stem":"6 − 4는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6에서 4를 덜어 내요.","6 − 4 = 2예요.","4와 2를 모으면 6이니 2예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#3','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',1,'mc','auto','오이 9개에서 빗금 친 3개를 빼면 남는 것은 몇 개인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":3,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"오이 9개에서 빗금 친 3개를 빼면 남는 것은 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"3","mis":"M1-1-u3-X10"},{"t":"12","mis":"M1-1-u3-X04"}],"explanation":["9개에서 3개를 덜어 내요.","남은 오이는 6개예요.","빗금 친 것은 빼고 남은 것만 세어요."],"asset":{"type":"take_row","item":"🥒","n":9,"cross":3},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#4','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',1,'mc','auto','7 − 2는 얼마인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":4,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"7 − 2는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M1-1-u3-X04"},{"t":"2","mis":"M1-1-u3-X10"}],"explanation":["7에서 2를 덜어 내요.","7 − 2 = 5예요.","7부터 거꾸로 6, 5 — 두 번 세어요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#5','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',2,'mc','auto','빨간 구슬과 파란 구슬이 모두 9개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C7","difficulty":2,"kind":"mc","stem":"빨간 구슬과 파란 구슬이 모두 9개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"9 − 3 = 6, 9 − 6 = 3","correct":true},{"t":"9 − 3 = 6, 6 − 9 = 3","mis":"M1-1-u3-X11"},{"t":"9 − 3 = 6, 9 − 6 = 4","mis":"M1-1-u3-X15"}],"explanation":["전체 9개에서 빨간 3개를 빼면 파란 6개 — 9 − 3 = 6이에요.","전체 9개에서 파란 6개를 빼면 빨간 3개 — 9 − 6 = 3이에요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":3},{"item":"🔵","n":6}],"op":"+"},"variant_rule":{"alt":[{"stem":"빨간 구슬과 파란 구슬이 모두 8개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"8 − 5 = 3, 8 − 3 = 5","correct":true},{"t":"8 − 5 = 3, 3 − 8 = 5","mis":"M1-1-u3-X11"},{"t":"8 − 5 = 3, 8 − 3 = 4","mis":"M1-1-u3-X15"}],"explanation":["전체 8개에서 빨간 5개를 빼면 파란 3개예요.","전체 8개에서 파란 3개를 빼면 빨간 5개예요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":5},{"item":"🔵","n":3}],"op":"+"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#6','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',2,'ox','auto','8 − 5 = 3 이면 8 − 3 = 5 예요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":6,"concept":"M1-1-u3-C7","difficulty":2,"kind":"ox","stem":"8 − 5 = 3 이면 8 − 3 = 5 예요.","answer":"O","reason_options":[{"t":"8을 5와 3으로 가를 수 있으니 두 뺄셈식이 다 맞으니까","correct":true},{"t":"빼는 수를 바꾸면 답이 늘 같으니까","mis":"M1-1-u3-X14"}],"mis":"M1-1-u3-X14","explanation":["8은 5와 3으로 가를 수 있어요.","그래서 8 − 5 = 3, 8 − 3 = 5 둘 다 맞아요.","가르기를 알면 뺄셈식 두 개가 나와요."],"variant_rule":{"alt":[{"stem":"9 − 2 = 7 이면 9 − 7 = 3 이에요.","answer":"X","reason_options":[{"t":"9를 2와 7로 가를 수 있으니 9 − 7 = 2가 맞으니까","correct":true},{"t":"빼는 수가 커지면 답도 커지니까","mis":"M1-1-u3-X14"}],"explanation":["9는 2와 7로 가를 수 있어요.","그래서 9 − 7 = 2예요 — 3이 아니에요.","가르기를 알면 뺄셈식 두 개가 나와요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#7','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',2,'sa','auto','8부터 2번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"8부터 2번 거꾸로 세면 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["8은 이미 있는 수예요 — 7부터 세어요.","7, 6 — 6이에요.","그래서 8 − 2 = 6이에요."],"asset":{"type":"count_on","start":8,"steps":2,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#8','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',2,'mc','auto','의자 7개에 친구 5명이 한 명씩 앉았어요. 빈 의자는 몇 개인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":8,"concept":"M1-1-u3-C7","difficulty":2,"kind":"mc","stem":"의자 7개에 친구 5명이 한 명씩 앉았어요. 빈 의자는 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"5","mis":"M1-1-u3-X10"},{"t":"12","mis":"M1-1-u3-X04"}],"explanation":["의자 7개와 친구 5명을 짝 지어요.","7 − 5 = 2, 빈 의자는 2개예요.","짝 짓고 남은 것을 뺄셈으로 구해요."],"variant_rule":{"alt":[{"stem":"의자 9개에 친구 6명이 한 명씩 앉았어요. 빈 의자는 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u3-X10"},{"t":"15","mis":"M1-1-u3-X04"}],"explanation":["의자 9개와 친구 6명을 짝 지어요.","9 − 6 = 3, 빈 의자는 3개예요.","짝 짓고 남은 것을 뺄셈으로 구해요."],"asset":null},{"stem":"의자 6개에 친구 2명이 한 명씩 앉았어요. 빈 의자는 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u3-X10"},{"t":"8","mis":"M1-1-u3-X04"}],"explanation":["의자 6개와 친구 2명을 짝 지어요.","6 − 2 = 4, 빈 의자는 4개예요.","짝 짓고 남은 것을 뺄셈으로 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#9','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',2,'blank','auto','규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":9,"concept":"M1-1-u3-C7","difficulty":2,"kind":"blank","stem":"규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"5","correct":true},{"t":"7","mis":"M1-1-u3-X14"},{"t":"6","mis":"M1-1-u3-X14"}],"explanation":["빼는 수가 1씩 커져요.","그래서 남는 수는 1씩 작아져요 — 8, 7, 6 다음은 5예요.","9 − 4 = 5로 확인해요."],"asset":{"type":"expr_grid","rows":[["9 − 1","9 − 2","9 − 3","9 − 4"],["8","7","6",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-1-u3-X14"},{"t":"4","mis":"M1-1-u3-X14"}],"explanation":["처음 수가 1씩 작아져요.","그래서 남는 수도 1씩 작아져요 — 6, 5, 4 다음은 3이에요.","5 − 2 = 3으로 확인해요."],"asset":{"type":"expr_grid","rows":[["8 − 2","7 − 2","6 − 2","5 − 2"],["6","5","4",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_basic#10','math',1,1,'u3','L09','g1_1_math_u3_L09_basic','lesson_basic','M1-1-u3-C7',3,'error','auto','하루가 7 − 3을 거꾸로 세기로 풀었어요. 「7, 6, 5 — 답은 5야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X09','M1-1-u3-X11']::text[],true,'{"seq":10,"concept":"M1-1-u3-C7","difficulty":3,"kind":"error","stem":"하루가 7 − 3을 거꾸로 세기로 풀었어요. 「7, 6, 5 — 답은 5야!」 무엇이 잘못되었나요?","options":[{"t":"7을 다시 세었어요 — 6, 5, 4로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X09"},{"t":"3부터 세어야 해요","mis":"M1-1-u3-X11"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X09"}],"explanation":["7은 이미 있는 수라 세지 않아요.","6, 5, 4 — 답은 4예요.","거꾸로 셀 때는 바로 아래 수부터 세어요."],"variant_rule":{"alt":[{"stem":"유나가 9 − 2를 거꾸로 세기로 풀었어요. 「9, 8 — 답은 8이야!」 무엇이 잘못되었나요?","options":[{"t":"9를 다시 세었어요 — 8, 7로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X09"},{"t":"2부터 세어야 해요","mis":"M1-1-u3-X11"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X09"}],"explanation":["9는 이미 있는 수라 세지 않아요.","8, 7 — 답은 7이에요.","거꾸로 셀 때는 바로 아래 수부터 세어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#1','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',2,'mc','auto','6부터 3번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C7","difficulty":2,"kind":"mc","stem":"6부터 3번 거꾸로 세면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M1-1-u3-X09"},{"t":"2","mis":"M1-1-u3-X15"}],"explanation":["6은 이미 있는 수예요 — 5부터 세어요.","5, 4, 3 — 3이에요.","그래서 6 − 3 = 3이에요."],"asset":{"type":"count_on","start":6,"steps":3,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#2','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',2,'sa','auto','9 − 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"9 − 5는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["9에서 5를 덜어 내요.","9 − 5 = 4예요.","5와 4를 모으면 9니까 4예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#3','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',3,'mc','auto','「8 − □ = 2」에서 □에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":3,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"「8 − □ = 2」에서 □에 알맞은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"2","mis":"M1-1-u3-X10"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["8에서 얼마를 빼야 2가 남을까요?","8 − 6 = 2 — □는 6이에요.","2와 □를 모으면 8이 돼요."],"variant_rule":{"addsub":{"op":"sub","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#4','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',3,'mc','auto','뽑기 기계에 공이 9개 있었어요. 몇 개를 뽑았더니 4개가 남았어요. 뽑은 공은 몇 개인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"뽑기 기계에 공이 9개 있었어요. 몇 개를 뽑았더니 4개가 남았어요. 뽑은 공은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u3-X10"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["9 − □ = 4예요.","9를 4와 5로 가를 수 있으니 뽑은 공은 5개예요.","남은 수와 뽑은 수를 모으면 처음 수예요."],"variant_rule":{"alt":[{"stem":"바구니에 귤이 7개 있었어요. 몇 개를 먹었더니 3개가 남았어요. 먹은 귤은 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X10"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["7 − □ = 3이에요.","7을 3과 4로 가를 수 있으니 먹은 귤은 4개예요.","남은 수와 먹은 수를 모으면 처음 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#5','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',3,'ox','auto','9 − 2보다 9 − 3의 답이 더 커요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":5,"concept":"M1-1-u3-C7","difficulty":3,"kind":"ox","stem":"9 − 2보다 9 − 3의 답이 더 커요.","answer":"X","reason_options":[{"t":"빼는 수가 커지면 남는 수는 작아지니까","correct":true},{"t":"빼는 수가 큰 쪽이 답도 크니까","mis":"M1-1-u3-X14"}],"mis":"M1-1-u3-X14","explanation":["9 − 2 = 7, 9 − 3 = 6이에요.","빼는 수가 1 커지면 남는 수는 1 작아져요.","덜어 낼수록 남는 것은 줄어요."],"variant_rule":{"alt":[{"stem":"8 − 5보다 8 − 4의 답이 더 커요.","answer":"O","reason_options":[{"t":"빼는 수가 작을수록 남는 수는 크니까","correct":true},{"t":"빼는 수가 큰 쪽이 답도 크니까","mis":"M1-1-u3-X14"}],"explanation":["8 − 5 = 3, 8 − 4 = 4예요.","덜 덜어 내면 더 많이 남아요.","빼는 수와 남는 수는 반대로 움직여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#6','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',3,'mc','auto','그림을 보고 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X11']::text[],true,'{"seq":6,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"그림을 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"8 − 6 = 2, 남은 것은 2개예요","correct":true},{"t":"8 − 6 = 2, 남은 것은 6개예요","mis":"M1-1-u3-X10"},{"t":"6 − 8 = 2, 남은 것은 2개예요","mis":"M1-1-u3-X11"}],"explanation":["8개에서 빗금 친 6개를 덜어 냈어요.","8 − 6 = 2, 남은 것은 2개예요.","덜어 낸 수와 남은 수를 가르세요."],"asset":{"type":"take_row","item":"🥒","n":8,"cross":6},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"7 − 4 = 3, 남은 것은 3개예요","correct":true},{"t":"7 − 4 = 3, 남은 것은 4개예요","mis":"M1-1-u3-X10"},{"t":"4 − 7 = 3, 남은 것은 3개예요","mis":"M1-1-u3-X11"}],"explanation":["7개에서 빗금 친 4개를 덜어 냈어요.","7 − 4 = 3, 남은 것은 3개예요.","덜어 낸 수와 남은 수를 가르세요."],"asset":{"type":"take_row","item":"🍎","n":7,"cross":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#7','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',3,'error','auto','친구들이 「9 − 6」을 풀었어요. 잘못 푼 친구는 누구인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X02','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":3,"kind":"error","stem":"친구들이 「9 − 6」을 풀었어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"하루: 「9부터 거꾸로 9, 8, 7, 6, 5, 4 — 4야.」","correct":true,"mis_target":"M1-1-u3-X09"},{"t":"서아: 「9는 6과 3으로 가를 수 있으니 3이야.」","mis":"M1-1-u3-X02"},{"t":"도이: 「십 배열판 9칸에서 6칸을 지우면 3칸이야.」","mis":"M1-1-u3-X15"}],"explanation":["9는 이미 있는 수예요 — 8부터 여섯 번 세면 3이에요.","하루는 9를 다시 세어 하나 많은 4가 나왔어요.","서아·도이처럼 풀면 3이에요."],"variant_rule":{"alt":[{"stem":"친구들이 「7 − 3」을 풀었어요. 잘못 푼 친구는 누구인가요?","options":[{"t":"유나: 「3에서 7을 빼면 4야.」","correct":true,"mis_target":"M1-1-u3-X11"},{"t":"지우: 「7부터 거꾸로 6, 5, 4 — 4야.」","mis":"M1-1-u3-X09"},{"t":"하루: 「7은 3과 4로 가를 수 있으니 4야.」","mis":"M1-1-u3-X02"}],"explanation":["3에서 7은 덜어 낼 수 없어요.","7에서 3을 빼야 해요.","답은 같아도 식의 순서가 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#8','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',4,'mc','auto','어떤 수에서 3을 뺐더니 5가 되었어요. 어떤 수는 무엇인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":8,"concept":"M1-1-u3-C7","difficulty":4,"kind":"mc","stem":"어떤 수에서 3을 뺐더니 5가 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X10"}],"explanation":["□ − 3 = 5예요.","5와 3을 모으면 8 — 어떤 수는 8이에요.","8 − 3 = 5로 확인해요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 4를 뺐더니 2가 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"2","mis":"M1-1-u3-X04"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["□ − 4 = 2예요.","2와 4를 모으면 6 — 어떤 수는 6이에요.","6 − 4 = 2로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#9','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',4,'mc','auto','「9 − □ = 6」과 「9 − 6 = △」에서 □와 △는 같은 수예요. 그 수는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":9,"concept":"M1-1-u3-C7","difficulty":4,"kind":"mc","stem":"「9 − □ = 6」과 「9 − 6 = △」에서 □와 △는 같은 수예요. 그 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u3-X10"},{"t":"15","mis":"M1-1-u3-X04"}],"explanation":["9는 6과 3으로 가를 수 있어요.","9 − 3 = 6, 9 − 6 = 3 — 그 수는 3이에요.","가르기 하나로 뺄셈식 두 개가 나와요."],"variant_rule":{"alt":[{"stem":"「8 − □ = 5」와 「8 − 5 = △」에서 □와 △는 같은 수예요. 그 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-1-u3-X10"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["8은 5와 3으로 가를 수 있어요.","8 − 3 = 5, 8 − 5 = 3 — 그 수는 3이에요.","가르기 하나로 뺄셈식 두 개가 나와요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L09_challenge#10','math',1,1,'u3','L09','g1_1_math_u3_L09_challenge','lesson_challenge','M1-1-u3-C7',4,'essay','teacher','8 − 3을 거꾸로 세기와 십 배열판 두 가지 방법으로 풀고, 두 방법의 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C7","difficulty":4,"kind":"essay","stem":"8 − 3을 거꾸로 세기와 십 배열판 두 가지 방법으로 풀고, 두 방법의 답이 같은지 확인해 보세요.","answer_guide":{"answer":"거꾸로 세기: 8부터 7, 6, 5 — 5. 십 배열판: 8칸을 칠하고 3칸을 지우면 5칸. 두 방법 모두 5로 같아요.","scoring_points":["거꾸로 세기를 바르게 했는가(처음 수를 다시 세지 않음)","십 배열판으로 덜어 내기를 했는가","두 답이 같은지 견주었는가"]},"explanation":["8부터 바로 아래 수부터 거꾸로 세어요.","십 배열판에서는 지운 칸을 빼고 남은 칸을 세요.","두 답을 나란히 놓고 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#1','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',1,'mc','auto','4 + 0은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"4 + 0은 얼마인가요?","options":[{"t":"4","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"5","mis":"M1-1-u3-X15"}],"explanation":["0은 아무것도 없다는 뜻이에요.","4에 아무것도 더하지 않으면 4 그대로예요.","어떤 수에 0을 더하면 그 수예요."],"variant_rule":{"addsub":{"op":"add","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#2','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',1,'mc','auto','콩 5개에서 아무것도 빼지 않았어요(빗금 0개). 남은 콩은 몇 개인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":2,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"콩 5개에서 아무것도 빼지 않았어요(빗금 0개). 남은 콩은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"4","mis":"M1-1-u3-X15"}],"explanation":["빗금 친 콩이 없어요 — 0개를 뺐어요.","5 − 0 = 5, 그대로 5개예요.","0을 빼면 처음 수 그대로예요."],"asset":{"type":"take_row","item":"🫘","n":5,"cross":0},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#3','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',1,'sa','auto','6 − 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u3-C8","difficulty":1,"kind":"sa","stem":"6 − 6은 얼마인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["6개에서 6개를 모두 덜어 내요.","남은 것이 없으니 0이에요.","같은 수를 빼면 0이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#4','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',1,'mc','auto','0 + 3은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":4,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"0 + 3은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"4","mis":"M1-1-u3-X15"}],"explanation":["아무것도 없는 데에 3을 더해요.","0 + 3 = 3이에요.","0에 어떤 수를 더하면 그 수예요."],"variant_rule":{"addsub":{"op":"add","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#5','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',2,'ox','auto','7 − 0 = 0 입니다.',ARRAY['M1-1-u3-X12']::text[],true,'{"seq":5,"concept":"M1-1-u3-C8","difficulty":2,"kind":"ox","stem":"7 − 0 = 0 입니다.","answer":"X","reason_options":[{"t":"0을 빼면 아무것도 덜어 내지 않아 7 그대로니까","correct":true},{"t":"0이 있는 식은 답이 늘 0이니까","mis":"M1-1-u3-X12"}],"mis":"M1-1-u3-X12","explanation":["7에서 아무것도 덜어 내지 않았어요.","7 − 0 = 7이에요.","0을 빼면 그대로, 같은 수를 빼면 0이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"check","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#6','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',2,'match','auto','식과 답을 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C8","difficulty":2,"kind":"match","stem":"식과 답을 이어 보세요.","pairs":[{"l":"3 + 0","r":"3"},{"l":"3 − 3","r":"0"},{"l":"0 + 5","r":"5"}],"mis":"M1-1-u3-X12","explanation":["3 + 0 = 3, 0 + 5 = 5 — 0을 더하면 그대로예요.","3 − 3 = 0 — 같은 수를 빼면 0이에요.","0이 식 어디에 있는지 먼저 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 식과 답을 이어 보세요.","pairs":[{"l":"6 − 0","r":"6"},{"l":"4 − 4","r":"0"},{"l":"0 + 2","r":"2"}],"explanation":["6 − 0 = 6 — 0을 빼면 그대로예요.","4 − 4 = 0 — 같은 수를 빼면 0이에요.","0 + 2 = 2 — 0에 더하면 그 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#7','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',2,'mc','auto','사탕 4개를 모두 먹었어요. 남은 사탕은 몇 개인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X04']::text[],true,'{"seq":7,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"사탕 4개를 모두 먹었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"0","correct":true},{"t":"4","mis":"M1-1-u3-X13"},{"t":"8","mis":"M1-1-u3-X04"}],"explanation":["4개를 모두 덜어 냈어요.","4 − 4 = 0, 남은 사탕은 없어요.","모두 빼면 0이에요."],"asset":{"type":"take_row","item":"🍬","n":4,"cross":4},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#8','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',2,'blank','auto','「8 − □ = 8」에서 □에 알맞은 수는 (        )예요.',ARRAY['M1-1-u3-X13','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":2,"kind":"blank","stem":"「8 − □ = 8」에서 □에 알맞은 수는 (        )예요.","options":[{"t":"0","correct":true},{"t":"8","mis":"M1-1-u3-X13"},{"t":"1","mis":"M1-1-u3-X15"}],"explanation":["8에서 얼마를 빼야 그대로 8일까요?","아무것도 빼지 않아야 해요 — □는 0이에요.","8을 빼면 0이 되어 버려요."],"variant_rule":{"alt":[{"stem":"「□ − 5 = 0」에서 □에 알맞은 수는 (        )예요.","options":[{"t":"5","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["어떤 수에서 5를 빼야 0일까요?","같은 수를 빼면 0 — □는 5예요.","5 − 5 = 0으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#9','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',2,'mc','auto','접시에 귤이 하나도 없었어요. 귤 3개를 올려놓았어요. 귤은 모두 몇 개인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":9,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"접시에 귤이 하나도 없었어요. 귤 3개를 올려놓았어요. 귤은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"4","mis":"M1-1-u3-X15"}],"explanation":["처음 귤은 0개예요.","0 + 3 = 3, 귤은 3개예요.","0에 더하면 더한 수 그대로예요."],"variant_rule":{"alt":[{"stem":"필통에 연필이 6자루 있었어요. 아무도 연필을 넣지 않았어요. 연필은 모두 몇 자루인가요?","options":[{"t":"6","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["더 넣은 연필은 0자루예요.","6 + 0 = 6, 연필은 6자루예요.","0을 더하면 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_basic#10','math',1,1,'u3','L11','g1_1_math_u3_L11_basic','lesson_basic','M1-1-u3-C8',3,'error','auto','친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],true,'{"seq":10,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「5 − 5 = 5」","correct":true,"mis_target":"M1-1-u3-X13"},{"t":"「5 + 0 = 5」","mis":"M1-1-u3-X12"},{"t":"「0 + 5 = 5」","mis":"M1-1-u3-X12"}],"explanation":["5개에서 5개를 모두 빼면 하나도 안 남아요.","5 − 5 = 0이에요.","0을 빼기와 모두 빼기를 가르세요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「7 − 0 = 0」","correct":true,"mis_target":"M1-1-u3-X12"},{"t":"「7 − 7 = 0」","mis":"M1-1-u3-X13"},{"t":"「0 + 7 = 7」","mis":"M1-1-u3-X12"}],"explanation":["7에서 아무것도 빼지 않으면 7이에요.","7 − 0 = 7이에요.","0을 빼면 그대로, 같은 수를 빼면 0이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
