INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#2','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',2,'sa','auto','0 + 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C8","difficulty":2,"kind":"sa","stem":"0 + 7은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["아무것도 없는 데에 7을 더해요.","0 + 7 = 7이에요.","0에 더하면 더한 수 그대로예요."],"variant_rule":{"addsub":{"op":"add","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#3','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',3,'mc','auto','답이 0인 식은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],true,'{"seq":3,"concept":"M1-1-u3-C8","difficulty":3,"kind":"mc","stem":"답이 0인 식은 어느 것인가요?","options":[{"t":"6 − 6","correct":true},{"t":"6 − 0","mis":"M1-1-u3-X13"},{"t":"6 + 0","mis":"M1-1-u3-X12"}],"explanation":["6 − 6은 모두 빼서 0이에요.","6 − 0 = 6, 6 + 0 = 6이에요.","0이 들어 있다고 답이 0인 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 답이 0인 식은 어느 것인가요?","options":[{"t":"3 − 3","correct":true},{"t":"0 + 3","mis":"M1-1-u3-X12"},{"t":"3 − 0","mis":"M1-1-u3-X13"}],"explanation":["3 − 3은 모두 빼서 0이에요.","0 + 3 = 3, 3 − 0 = 3이에요.","0이 들어 있다고 답이 0인 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#4','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',3,'ox','auto','어떤 수에 0을 더하면 그 수보다 1 커져요.',ARRAY['M1-1-u3-X12']::text[],true,'{"seq":4,"concept":"M1-1-u3-C8","difficulty":3,"kind":"ox","stem":"어떤 수에 0을 더하면 그 수보다 1 커져요.","answer":"X","reason_options":[{"t":"0은 아무것도 없으니 더해도 그대로니까","correct":true},{"t":"더하면 언제나 커지니까","mis":"M1-1-u3-X12"}],"mis":"M1-1-u3-X12","explanation":["0은 아무것도 없다는 뜻이에요.","0을 더해도 그 수 그대로예요.","1을 더해야 1 커져요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 그 수를 빼면 언제나 0이 돼요.","answer":"O","reason_options":[{"t":"있던 것을 모두 덜어 내니까","correct":true},{"t":"빼도 처음 수 그대로니까","mis":"M1-1-u3-X13"}],"explanation":["5 − 5, 8 − 8처럼 같은 수를 빼요.","있던 것을 모두 덜어 내면 0이에요.","0을 빼면 그대로, 같은 수를 빼면 0이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#5','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',3,'mc','auto','수 카드 「3」, 「0」, 「3」을 한 번씩 써서 「모두 빼기」 식을 만들었어요. 알맞은 것은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],true,'{"seq":5,"concept":"M1-1-u3-C8","difficulty":3,"kind":"mc","stem":"수 카드 「3」, 「0」, 「3」을 한 번씩 써서 「모두 빼기」 식을 만들었어요. 알맞은 것은 어느 것인가요?","options":[{"t":"3 − 3 = 0","correct":true},{"t":"3 − 0 = 3","mis":"M1-1-u3-X13"},{"t":"0 + 3 = 3","mis":"M1-1-u3-X12"}],"explanation":["모두 빼기는 같은 수를 빼는 거예요.","3 − 3 = 0이에요.","3 − 0 = 3은 「0 빼기」 식이에요."],"variant_rule":{"alt":[{"stem":"수 카드 「4」, 「0」, 「4」를 한 번씩 써서 「0 더하기」 식을 만들었어요. 알맞은 것은 어느 것인가요?","options":[{"t":"4 + 0 = 4","correct":true},{"t":"4 − 4 = 0","mis":"M1-1-u3-X13"},{"t":"4 + 4 = 0","mis":"M1-1-u3-X12"}],"explanation":["0 더하기는 어떤 수에 0을 더하는 거예요.","4 + 0 = 4예요.","4 − 4 = 0은 「모두 빼기」 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#6','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',3,'mc','auto','「□ + 0 = 6」에서 □에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":6,"concept":"M1-1-u3-C8","difficulty":3,"kind":"mc","stem":"「□ + 0 = 6」에서 □에 알맞은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["어떤 수에 0을 더하면 그 수 그대로예요.","□ + 0 = 6이니 □는 6이에요.","6 + 0 = 6으로 확인해요."],"variant_rule":{"addsub":{"op":"add","ask":"missing","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#7','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',3,'error','auto','지우가 말했어요. 틀린 말은 어느 것인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X13']::text[],true,'{"seq":7,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"지우가 말했어요. 틀린 말은 어느 것인가요?","options":[{"t":"「4에서 0을 빼면 0이야.」","correct":true,"mis_target":"M1-1-u3-X12"},{"t":"「4에서 4를 빼면 0이야.」","mis":"M1-1-u3-X13"},{"t":"「0에 4를 더하면 4야.」","mis":"M1-1-u3-X12"}],"explanation":["4에서 아무것도 빼지 않으면 4예요.","4 − 0 = 4예요.","0을 빼면 그대로예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 지우가 말했어요. 틀린 말은 어느 것인가요?","options":[{"t":"「2에서 2를 빼면 2야.」","correct":true,"mis_target":"M1-1-u3-X13"},{"t":"「2에 0을 더하면 2야.」","mis":"M1-1-u3-X12"},{"t":"「2에서 0을 빼면 2야.」","mis":"M1-1-u3-X12"}],"explanation":["2에서 2를 모두 빼면 하나도 안 남아요.","2 − 2 = 0이에요.","같은 수를 빼면 0이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#8','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',4,'mc','auto','다음 가운데 답이 가장 큰 식은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 가운데 답이 가장 큰 식은 어느 것인가요?","options":[{"t":"8 − 0","correct":true},{"t":"8 − 8","mis":"M1-1-u3-X13"},{"t":"0 + 7","mis":"M1-1-u3-X12"}],"explanation":["8 − 0 = 8, 8 − 8 = 0, 0 + 7 = 7이에요.","가장 큰 것은 8 − 0이에요.","0이 어디에 있는지 보고 하나씩 계산해요."],"variant_rule":{"alt":[{"stem":"다음 가운데 답이 가장 작은 식은 어느 것인가요?","options":[{"t":"5 − 5","correct":true},{"t":"5 − 0","mis":"M1-1-u3-X13"},{"t":"0 + 1","mis":"M1-1-u3-X12"}],"explanation":["5 − 5 = 0, 5 − 0 = 5, 0 + 1 = 1이에요.","가장 작은 것은 5 − 5예요.","0이 어디에 있는지 보고 하나씩 계산해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#9','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',4,'mc','auto','규칙을 찾아 빈칸에 알맞은 수를 고르세요.',ARRAY['M1-1-u3-X13','M1-1-u3-X14']::text[],true,'{"seq":9,"concept":"M1-1-u3-C8","difficulty":4,"kind":"mc","stem":"규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"0","correct":true},{"t":"5","mis":"M1-1-u3-X13"},{"t":"1","mis":"M1-1-u3-X14"}],"explanation":["빼는 수가 1씩 커지고 답은 1씩 작아져요.","2, 1 다음은 0 — 5 − 5 = 0이에요.","같은 수를 빼면 0이에요."],"asset":{"type":"expr_grid","rows":[["5 − 3","5 − 4","5 − 5"],["2","1",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 규칙을 찾아 빈칸에 알맞은 수를 고르세요.","options":[{"t":"4","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"5","mis":"M1-1-u3-X14"}],"explanation":["빼는 수가 1씩 작아지고 답은 1씩 커져요.","2, 3 다음은 4 — 4 − 0 = 4예요.","0을 빼면 그대로예요."],"asset":{"type":"expr_grid","rows":[["4 − 2","4 − 1","4 − 0"],["2","3",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L11_challenge#10','math',1,1,'u3','L11','g1_1_math_u3_L11_challenge','lesson_challenge','M1-1-u3-C8',4,'essay','teacher','「0을 더하는 이야기」와 「모두 빼는 이야기」를 하나씩 만들고 식으로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C8","difficulty":4,"kind":"essay","stem":"「0을 더하는 이야기」와 「모두 빼는 이야기」를 하나씩 만들고 식으로 써 보세요.","answer_guide":{"answer":"0 더하기: 바구니에 사과가 5개 있었는데 아무도 사과를 넣지 않았어요. 5 + 0 = 5. / 모두 빼기: 쿠키 3개를 모두 먹었어요. 3 − 3 = 0.","scoring_points":["0을 더하는 장면이 이야기에 있는가","모두 빼는 장면이 이야기에 있는가","두 식의 답이 바른가"]},"explanation":["「아무것도 더하지 않았다」는 장면을 떠올려요.","「모두 먹었다」·「모두 날아갔다」는 장면을 떠올려요.","이야기를 식으로 옮겨 답을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#1','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',1,'mc','auto','계산 결과가 5인 식은 어느 것인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":1,"concept":"M1-1-u3-C9","difficulty":1,"kind":"mc","stem":"계산 결과가 5인 식은 어느 것인가요?","options":[{"t":"2 + 3","correct":true},{"t":"2 + 5","mis":"M1-1-u3-X14"},{"t":"8 − 2","mis":"M1-1-u3-X14"}],"explanation":["2 + 3 = 5예요.","2 + 5 = 7, 8 − 2 = 6이에요.","보기마다 하나씩 계산해 봐요."],"variant_rule":{"alt":[{"stem":"계산 결과가 6인 식은 어느 것인가요?","options":[{"t":"9 − 3","correct":true},{"t":"9 − 6","mis":"M1-1-u3-X14"},{"t":"2 + 3","mis":"M1-1-u3-X14"}],"explanation":["9 − 3 = 6이에요.","9 − 6 = 3, 2 + 3 = 5예요.","보기마다 하나씩 계산해 봐요."],"asset":null},{"stem":"계산 결과가 4인 식은 어느 것인가요?","options":[{"t":"1 + 3","correct":true},{"t":"1 + 4","mis":"M1-1-u3-X14"},{"t":"7 − 2","mis":"M1-1-u3-X14"}],"explanation":["1 + 3 = 4예요.","1 + 4 = 5, 7 − 2 = 5예요.","보기마다 하나씩 계산해 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#2','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',1,'sa','auto','「1 + □ = 5」에서 □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C9","difficulty":1,"kind":"sa","stem":"「1 + □ = 5」에서 □에 알맞은 수를 숫자로 쓰세요.","answer":["4"],"explanation":["1에 무엇을 더하면 5일까요?","1 + 4 = 5 — □는 4예요.","5를 1과 4로 가를 수 있어요."],"variant_rule":{"addsub":{"op":"add","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#3','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',1,'mc','auto','「6 − 2」와 계산 결과가 같은 식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X14']::text[],true,'{"seq":3,"concept":"M1-1-u3-C9","difficulty":1,"kind":"mc","stem":"「6 − 2」와 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"1 + 3","correct":true},{"t":"6 + 2","mis":"M1-1-u3-X04"},{"t":"6 − 3","mis":"M1-1-u3-X14"}],"explanation":["6 − 2 = 4예요.","1 + 3 = 4 — 결과가 같아요.","6 + 2 = 8, 6 − 3 = 3이에요."],"variant_rule":{"alt":[{"stem":"「2 + 5」와 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"9 − 2","correct":true},{"t":"9 − 5","mis":"M1-1-u3-X14"},{"t":"5 − 2","mis":"M1-1-u3-X04"}],"explanation":["2 + 5 = 7이에요.","9 − 2 = 7 — 결과가 같아요.","같은 수가 들어 있어도 결과는 다를 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#4','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',1,'mc','auto','5에서 시작하는 뺄셈식 가운데 결과가 1인 것은 어느 것인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X04']::text[],true,'{"seq":4,"concept":"M1-1-u3-C9","difficulty":1,"kind":"mc","stem":"5에서 시작하는 뺄셈식 가운데 결과가 1인 것은 어느 것인가요?","options":[{"t":"5 − 4","correct":true},{"t":"5 − 1","mis":"M1-1-u3-X10"},{"t":"5 + 1","mis":"M1-1-u3-X04"}],"explanation":["5 − 4 = 1이에요.","5 − 1 = 4예요 — 1을 뺀 것이지 결과가 1은 아니에요.","결과는 = 오른쪽의 수예요."],"variant_rule":{"alt":[{"stem":"5에서 시작하는 뺄셈식 가운데 결과가 3인 것은 어느 것인가요?","options":[{"t":"5 − 2","correct":true},{"t":"5 − 3","mis":"M1-1-u3-X10"},{"t":"5 + 3","mis":"M1-1-u3-X04"}],"explanation":["5 − 2 = 3이에요.","5 − 3 = 2예요 — 3을 뺀 것이지 결과가 3은 아니에요.","결과는 = 오른쪽의 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#5','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',2,'match','auto','계산 결과가 같은 식끼리 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u3-C9","difficulty":2,"kind":"match","stem":"계산 결과가 같은 식끼리 이어 보세요.","pairs":[{"l":"2 + 4","r":"7 − 1"},{"l":"3 + 4","r":"9 − 2"},{"l":"1 + 1","r":"5 − 3"}],"mis":"M1-1-u3-X14","explanation":["2 + 4 = 6, 7 − 1 = 6이에요.","3 + 4 = 7, 9 − 2 = 7 / 1 + 1 = 2, 5 − 3 = 2예요.","양쪽을 먼저 계산하고 이어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 같은 식끼리 이어 보세요.","pairs":[{"l":"5 + 3","r":"9 − 1"},{"l":"2 + 2","r":"6 − 2"},{"l":"4 + 5","r":"9 − 0"}],"explanation":["5 + 3 = 8, 9 − 1 = 8이에요.","2 + 2 = 4, 6 − 2 = 4 / 4 + 5 = 9, 9 − 0 = 9예요.","양쪽을 먼저 계산하고 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#6','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',2,'ox','auto','3 + 3과 9 − 3은 계산 결과가 같아요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":6,"concept":"M1-1-u3-C9","difficulty":2,"kind":"ox","stem":"3 + 3과 9 − 3은 계산 결과가 같아요.","answer":"O","reason_options":[{"t":"둘 다 6이 되니까","correct":true},{"t":"같은 수 3이 들어 있으면 결과가 같으니까","mis":"M1-1-u3-X14"}],"mis":"M1-1-u3-X14","explanation":["3 + 3 = 6, 9 − 3 = 6이에요.","결과가 같아요.","같은 수가 들어 있어서가 아니라 계산해서 같아요."],"variant_rule":{"alt":[{"stem":"4 + 2와 4 − 2는 계산 결과가 같아요.","answer":"X","reason_options":[{"t":"4 + 2 = 6, 4 − 2 = 2로 다르니까","correct":true},{"t":"같은 수 4와 2가 들어 있으니 결과도 같으니까","mis":"M1-1-u3-X14"}],"explanation":["4 + 2 = 6, 4 − 2 = 2예요.","결과가 달라요.","같은 수가 들어 있어도 +, − 에 따라 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#7','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',2,'blank','auto','7이 되는 덧셈식을 차례로 썼어요. 「1 + 6, 2 + 5, 3 + (    ), 4 + 3」 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":7,"concept":"M1-1-u3-C9","difficulty":2,"kind":"blank","stem":"7이 되는 덧셈식을 차례로 썼어요. 「1 + 6, 2 + 5, 3 + (    ), 4 + 3」 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X14"},{"t":"6","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","6, 5, 다음은 4 — 3 + 4 = 7이에요.","빈칸에 넣고 7이 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"9에서 시작하는 뺄셈식을 차례로 썼어요. 「9 − 1, 9 − 2, 9 − 3, 9 − (    )」 빼는 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X14"},{"t":"5","mis":"M1-1-u3-X14"}],"explanation":["빼는 수가 1, 2, 3으로 1씩 커져요.","다음은 4 — 9 − 4예요.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#8','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',2,'mc','auto','오늘의 수는 6이에요. 결과가 6이 되는 식이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X14']::text[],true,'{"seq":8,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"오늘의 수는 6이에요. 결과가 6이 되는 식이 아닌 것은 어느 것인가요?","options":[{"t":"2 + 5","correct":true},{"t":"0 + 6","mis":"M1-1-u3-X12"},{"t":"8 − 2","mis":"M1-1-u3-X14"}],"explanation":["2 + 5 = 7이에요.","0 + 6 = 6, 8 − 2 = 6이에요.","보기마다 계산해 오늘의 수와 견주어요."],"variant_rule":{"alt":[{"stem":"오늘의 수는 5예요. 결과가 5가 되는 식이 아닌 것은 어느 것인가요?","options":[{"t":"9 − 5","correct":true},{"t":"5 − 0","mis":"M1-1-u3-X12"},{"t":"1 + 4","mis":"M1-1-u3-X14"}],"explanation":["9 − 5 = 4예요.","5 − 0 = 5, 1 + 4 = 5예요.","보기마다 계산해 오늘의 수와 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#9','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',2,'sa','auto','9 − 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-1-u3-C9","difficulty":2,"kind":"sa","stem":"9 − 4는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["9에서 4를 덜어 내요.","9 − 4 = 5예요.","4와 5를 모으면 9니까 5예요."],"variant_rule":{"addsub":{"op":"mix","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_basic#10','math',1,1,'u3','L12','g1_1_math_u3_L12_basic','lesson_basic','M1-1-u3-C9',3,'error','auto','서아가 계산 결과가 4인 식을 모았어요. 잘못 모은 것은 어느 것인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X12']::text[],true,'{"seq":10,"concept":"M1-1-u3-C9","difficulty":3,"kind":"error","stem":"서아가 계산 결과가 4인 식을 모았어요. 잘못 모은 것은 어느 것인가요?","options":[{"t":"「2 + 4」","correct":true,"mis_target":"M1-1-u3-X14"},{"t":"「7 − 3」","mis":"M1-1-u3-X14"},{"t":"「0 + 4」","mis":"M1-1-u3-X12"}],"explanation":["2 + 4 = 6이에요 — 4가 아니에요.","7 − 3 = 4, 0 + 4 = 4는 맞아요.","식에 4가 들어 있어도 결과가 4인 것은 아니에요."],"variant_rule":{"alt":[{"stem":"서아가 계산 결과가 6인 식을 모았어요. 잘못 모은 것은 어느 것인가요?","options":[{"t":"「6 − 6」","correct":true,"mis_target":"M1-1-u3-X13"},{"t":"「6 − 0」","mis":"M1-1-u3-X12"},{"t":"「3 + 3」","mis":"M1-1-u3-X14"}],"explanation":["6 − 6 = 0이에요 — 6이 아니에요.","6 − 0 = 6, 3 + 3 = 6은 맞아요.","식에 6이 들어 있어도 결과가 6인 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#1','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',2,'mc','auto','8 − 5는 얼마인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X10']::text[],true,'{"seq":1,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"8 − 5는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"13","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X10"}],"explanation":["8에서 5를 덜어 내요.","8 − 5 = 3이에요.","5와 3을 모으면 8이니까 3이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#2','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',2,'sa','auto','「□ + 4 = 9」에서 □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C9","difficulty":2,"kind":"sa","stem":"「□ + 4 = 9」에서 □에 알맞은 수를 숫자로 쓰세요.","answer":["5"],"explanation":["무엇에 4를 더하면 9일까요?","5 + 4 = 9 — □는 5예요.","9를 5와 4로 가를 수 있어요."],"variant_rule":{"addsub":{"op":"add","ask":"missing"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#3','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',3,'mc','auto','수 카드 「2」, 「5」, 「7」을 한 번씩 써서 만들 수 있는 식이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":3,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"수 카드 「2」, 「5」, 「7」을 한 번씩 써서 만들 수 있는 식이 아닌 것은 어느 것인가요?","options":[{"t":"7 + 2 = 5","correct":true},{"t":"2 + 5 = 7","mis":"M1-1-u3-X14"},{"t":"7 − 5 = 2","mis":"M1-1-u3-X14"}],"explanation":["7 + 2 = 9예요 — 5가 아니에요.","2 + 5 = 7, 7 − 5 = 2는 맞는 식이에요.","세 수로 덧셈식 2개, 뺄셈식 2개를 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"수 카드 「3」, 「6」, 「9」를 한 번씩 써서 만들 수 있는 식이 아닌 것은 어느 것인가요?","options":[{"t":"3 − 6 = 9","correct":true},{"t":"3 + 6 = 9","mis":"M1-1-u3-X14"},{"t":"9 − 3 = 6","mis":"M1-1-u3-X14"}],"explanation":["3에서 6은 뺄 수 없고, 9도 아니에요.","3 + 6 = 9, 9 − 3 = 6은 맞는 식이에요.","뺄셈식은 가장 큰 수가 앞에 와요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#4','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',3,'mc','auto','결과가 3인 뺄셈식을 차례로 쓰고 있어요. 「9 − 6, 8 − 5, 7 − 4, (    )」 빈칸에 들어갈 식은 어느 것인가요?',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":4,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"결과가 3인 뺄셈식을 차례로 쓰고 있어요. 「9 − 6, 8 − 5, 7 − 4, (    )」 빈칸에 들어갈 식은 어느 것인가요?","options":[{"t":"6 − 3","correct":true},{"t":"6 − 4","mis":"M1-1-u3-X14"},{"t":"5 − 3","mis":"M1-1-u3-X14"}],"explanation":["앞의 수도 빼는 수도 1씩 작아져요.","7 − 4 다음은 6 − 3이에요.","6 − 3 = 3 — 결과가 3인지 확인해요."],"variant_rule":{"alt":[{"stem":"결과가 5인 덧셈식을 차례로 쓰고 있어요. 「0 + 5, 1 + 4, 2 + 3, (    )」 빈칸에 들어갈 식은 어느 것인가요?","options":[{"t":"3 + 2","correct":true},{"t":"3 + 3","mis":"M1-1-u3-X14"},{"t":"2 + 4","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","2 + 3 다음은 3 + 2예요.","3 + 2 = 5 — 결과가 5인지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#5','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',3,'ox','auto','계산 결과가 같은 덧셈식과 뺄셈식은 만들 수 없어요.',ARRAY['M1-1-u3-X14']::text[],true,'{"seq":5,"concept":"M1-1-u3-C9","difficulty":3,"kind":"ox","stem":"계산 결과가 같은 덧셈식과 뺄셈식은 만들 수 없어요.","answer":"X","reason_options":[{"t":"3 + 2와 7 − 2처럼 둘 다 5인 식이 있으니까","correct":true},{"t":"덧셈은 커지고 뺄셈은 작아지니 같을 수 없으니까","mis":"M1-1-u3-X14"}],"mis":"M1-1-u3-X14","explanation":["3 + 2 = 5, 7 − 2 = 5예요.","덧셈식과 뺄셈식의 결과가 같을 수 있어요.","계산해 보기 전에 정하지 않아요."],"variant_rule":{"alt":[{"stem":"「1 + 5」와 「8 − 2」는 계산 결과가 같아요.","answer":"O","reason_options":[{"t":"둘 다 6이 되니까","correct":true},{"t":"덧셈과 뺄셈은 결과가 같을 수 없으니까","mis":"M1-1-u3-X14"}],"explanation":["1 + 5 = 6, 8 − 2 = 6이에요.","결과가 같아요.","덧셈식과 뺄셈식도 결과가 같을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#6','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',3,'mc','auto','3, 4, 7로 만들 수 있는 식을 모두 모은 것은 어느 것인가요?',ARRAY['M1-1-u3-X03','M1-1-u3-X11']::text[],true,'{"seq":6,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"3, 4, 7로 만들 수 있는 식을 모두 모은 것은 어느 것인가요?","options":[{"t":"3 + 4 = 7, 4 + 3 = 7, 7 − 3 = 4, 7 − 4 = 3","correct":true},{"t":"3 + 4 = 7, 7 − 3 = 4","mis":"M1-1-u3-X03"},{"t":"3 + 4 = 7, 4 + 3 = 7, 3 − 7 = 4","mis":"M1-1-u3-X11"}],"explanation":["덧셈식은 순서를 바꿔 2개예요.","뺄셈식은 가장 큰 7을 앞에 두고 2개예요.","모두 4개 — 빠뜨리지 않았는지 세어요."],"variant_rule":{"alt":[{"stem":"2, 6, 8로 만들 수 있는 식을 모두 모은 것은 어느 것인가요?","options":[{"t":"2 + 6 = 8, 6 + 2 = 8, 8 − 2 = 6, 8 − 6 = 2","correct":true},{"t":"2 + 6 = 8, 8 − 2 = 6","mis":"M1-1-u3-X03"},{"t":"2 + 6 = 8, 6 + 2 = 8, 2 − 8 = 6","mis":"M1-1-u3-X11"}],"explanation":["덧셈식은 순서를 바꿔 2개예요.","뺄셈식은 가장 큰 8을 앞에 두고 2개예요.","모두 4개 — 빠뜨리지 않았는지 세어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#7','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',3,'error','auto','도윤이가 결과가 6인 덧셈식을 빠짐없이 썼대요. 「1 + 5, 2 + 4, 4 + 2, 5 + 1」 무엇이 문제인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X08']::text[],true,'{"seq":7,"concept":"M1-1-u3-C9","difficulty":3,"kind":"error","stem":"도윤이가 결과가 6인 덧셈식을 빠짐없이 썼대요. 「1 + 5, 2 + 4, 4 + 2, 5 + 1」 무엇이 문제인가요?","options":[{"t":"「3 + 3」을 빠뜨렸어요","correct":true,"mis_target":"M1-1-u3-X14"},{"t":"「4 + 2」는 「2 + 4」와 같아서 쓰면 안 돼요","mis":"M1-1-u3-X08"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X14"}],"explanation":["앞의 수가 1, 2 다음에 3이 빠졌어요.","3 + 3 = 6을 빠뜨렸어요.","앞의 수를 1씩 늘리며 빈 자리를 찾아요."],"variant_rule":{"alt":[{"stem":"도윤이가 결과가 4인 덧셈식을 빠짐없이 썼대요. 「1 + 3, 3 + 1」 무엇이 문제인가요?","options":[{"t":"「2 + 2」를 빠뜨렸어요","correct":true,"mis_target":"M1-1-u3-X14"},{"t":"「3 + 1」은 「1 + 3」과 같아서 쓰면 안 돼요","mis":"M1-1-u3-X08"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X14"}],"explanation":["앞의 수가 1 다음에 2가 빠졌어요.","2 + 2 = 4를 빠뜨렸어요.","앞의 수를 1씩 늘리며 빈 자리를 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#8','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',4,'mc','auto','□ + △ = 7 이고, □는 △보다 3 커요. □는 무엇인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X02']::text[],true,'{"seq":8,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"□ + △ = 7 이고, □는 △보다 3 커요. □는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u3-X14"},{"t":"7","mis":"M1-1-u3-X02"}],"explanation":["7을 가르는 방법 가운데 차이가 3인 것을 찾아요.","5와 2 — 5 + 2 = 7, 5 − 2 = 3이에요.","그래서 □는 5예요."],"variant_rule":{"alt":[{"stem":"□ + △ = 9 이고, □는 △보다 1 커요. □는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u3-X14"},{"t":"9","mis":"M1-1-u3-X02"}],"explanation":["9를 가르는 방법 가운데 차이가 1인 것을 찾아요.","5와 4 — 5 + 4 = 9, 5 − 4 = 1이에요.","그래서 □는 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#9','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',4,'mc','auto','「9 − □」의 결과가 「2 + 3」의 결과와 같아요. □는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X14']::text[],true,'{"seq":9,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「9 − □」의 결과가 「2 + 3」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M1-1-u3-X10"},{"t":"3","mis":"M1-1-u3-X14"}],"explanation":["2 + 3 = 5예요.","9 − □ = 5 — 9에서 4를 빼면 5예요.","그래서 □는 4예요."],"variant_rule":{"alt":[{"stem":"「8 − □」의 결과가 「1 + 5」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"2","correct":true},{"t":"6","mis":"M1-1-u3-X10"},{"t":"5","mis":"M1-1-u3-X14"}],"explanation":["1 + 5 = 6이에요.","8 − □ = 6 — 8에서 2를 빼면 6이에요.","그래서 □는 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_L12_challenge#10','math',1,1,'u3','L12','g1_1_math_u3_L12_challenge','lesson_challenge','M1-1-u3-C9',4,'essay','teacher','오늘의 수를 8로 정했어요. 결과가 8이 되는 덧셈식 2개와 8에서 시작하는 뺄셈식 2개를 만들고, 빠뜨리지 않고 찾는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u3-C9","difficulty":4,"kind":"essay","stem":"오늘의 수를 8로 정했어요. 결과가 8이 되는 덧셈식 2개와 8에서 시작하는 뺄셈식 2개를 만들고, 빠뜨리지 않고 찾는 방법을 써 보세요.","answer_guide":{"answer":"덧셈식: 3 + 5 = 8, 6 + 2 = 8. 뺄셈식: 8 − 1 = 7, 8 − 4 = 4. 앞의 수를 1씩 늘리거나 빼는 수를 1씩 늘리며 차례로 찾아요.","scoring_points":["결과가 8인 덧셈식 2개가 바른가","8에서 시작하는 뺄셈식 2개가 바른가","차례로 찾는 방법(규칙)을 말했는가"]},"explanation":["8을 가르는 방법을 떠올리면 덧셈식이 나와요.","8에서 1, 2, 3… 차례로 빼 봐요.","규칙대로 쓰면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#1','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"7","correct":true},{"t":"4","mis":"M1-1-u3-X01"},{"t":"8","mis":"M1-1-u3-X15"}],"explanation":["4와 3을 모아요.","모으면 7이에요.","두 수를 합쳐서 세어요."],"asset":{"type":"number_bond","whole":null,"parts":[4,3]},"variant_rule":{"bond":{"whole":[5,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#2','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C2',1,'sa','auto','8을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"8을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["3"],"explanation":["8을 5와 무엇으로 갈랐을까요?","5와 3을 모으면 8이니 3이에요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":8,"parts":[5,null]},"variant_rule":{"bond":{"whole":[5,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#3','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C3',1,'mc','auto','나비 4마리에 나비가 더 날아왔어요. 나비는 모두 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"나비 4마리에 나비가 더 날아왔어요. 나비는 모두 몇 마리인가요?","options":[{"t":"6","correct":true},{"t":"2","mis":"M1-1-u3-X04"},{"t":"4","mis":"M1-1-u3-X01"}],"explanation":["4마리와 2마리를 모아요.","모두 6마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"asset":{"type":"group_row","groups":[{"item":"🦋","n":4},{"item":"🦋","n":2}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#4','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C4',1,'mc','auto','「3 + 5 = 8」을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],false,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"「3 + 5 = 8」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"3 더하기 5는 8과 같습니다","correct":true},{"t":"3 빼기 5는 8과 같습니다","mis":"M1-1-u3-X06"},{"t":"3과 5는 8보다 큽니다","mis":"M1-1-u3-X06"}],"explanation":["+ 는 「더하기」, = 는 「같습니다」예요.","3 더하기 5는 8과 같습니다.","「3과 5의 합은 8입니다」라고도 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#5','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C6',1,'mc','auto','그림에 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"그림에 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"7 − 2 = 5","correct":true},{"t":"7 + 2 = 9","mis":"M1-1-u3-X04"},{"t":"7 − 2 = 6","mis":"M1-1-u3-X15"}],"explanation":["7개에서 빗금 친 2개를 덜어 냈어요.","7 − 2 = 5예요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🍎","n":7,"cross":2},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#6','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C5',1,'sa','auto','3 + 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":1,"kind":"sa","stem":"3 + 4는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["4에서 3만큼 이어 세요 — 5, 6, 7.","3 + 4 = 7이에요.","큰 수부터 이어 세면 빨라요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#7','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C7',1,'mc','auto','8부터 3번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"8부터 3번 거꾸로 세면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M1-1-u3-X09"},{"t":"4","mis":"M1-1-u3-X15"}],"explanation":["8은 이미 있는 수예요 — 7부터 세어요.","7, 6, 5 — 5예요.","그래서 8 − 3 = 5예요."],"asset":{"type":"count_on","start":8,"steps":3,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#8','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C8',1,'mc','auto','5 + 0은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"5 + 0은 얼마인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"6","mis":"M1-1-u3-X15"}],"explanation":["0은 아무것도 없다는 뜻이에요.","5 + 0 = 5예요.","0을 더하면 그대로예요."],"variant_rule":{"addsub":{"op":"add","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#9','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C1',2,'match','auto','모아서 8이 되는 두 수를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u3-C1","difficulty":2,"kind":"match","stem":"모아서 8이 되는 두 수를 이어 보세요.","pairs":[{"l":"1","r":"7"},{"l":"2","r":"6"},{"l":"3","r":"5"}],"mis":"M1-1-u3-X01","explanation":["1과 7, 2와 6, 3과 5를 모으면 8이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 8이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#10','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C2',2,'mc','auto','달걀 9개를 두 바구니에 나누어 담았어요. 한 바구니에 6개를 담으면 다른 바구니에는 몇 개인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],false,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"달걀 9개를 두 바구니에 나누어 담았어요. 한 바구니에 6개를 담으면 다른 바구니에는 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"9","mis":"M1-1-u3-X02"},{"t":"15","mis":"M1-1-u3-X04"}],"explanation":["9를 6과 무엇으로 가를까요?","6과 3을 모으면 9 — 3개예요.","두 바구니를 모으면 다시 9개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#11','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C3',2,'mc','auto','사과는 배보다 몇 개 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":11,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"사과는 배보다 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"11","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["사과와 배를 하나씩 짝 지어요.","짝이 없는 사과는 3개예요.","「몇 더 많은가」는 모으지 않아요."],"asset":{"type":"compare_groups","rows":[{"label":"사과","item":"🍎","n":7},{"label":"배","item":"🍐","n":4}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#12','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C5',2,'ox','auto','2 + 6과 6 + 2의 합은 같아요.',ARRAY['M1-1-u3-X08']::text[],false,'{"seq":12,"concept":"M1-1-u3-C5","difficulty":2,"kind":"ox","stem":"2 + 6과 6 + 2의 합은 같아요.","answer":"O","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 오는 수가 크면 합도 크니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["2 + 6 = 8, 6 + 2 = 8이에요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#13','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C7',2,'sa','auto','9 − 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"9 − 3은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9에서 3을 덜어 내요.","9 − 3 = 6이에요.","3과 6을 모으면 9니까 6이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#14','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C8',2,'mc','auto','쿠키 5개를 모두 먹었어요. 남은 쿠키는 몇 개인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X04']::text[],true,'{"seq":14,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"쿠키 5개를 모두 먹었어요. 남은 쿠키는 몇 개인가요?","options":[{"t":"0","correct":true},{"t":"5","mis":"M1-1-u3-X13"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["5개를 모두 덜어 냈어요.","5 − 5 = 0이에요.","모두 빼면 0이에요."],"asset":{"type":"take_row","item":"🍪","n":5,"cross":5},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#15','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C9',2,'mc','auto','「4 + 3」과 계산 결과가 같은 식은 어느 것인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X04']::text[],false,'{"seq":15,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「4 + 3」과 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"9 − 2","correct":true},{"t":"9 − 3","mis":"M1-1-u3-X14"},{"t":"4 − 3","mis":"M1-1-u3-X04"}],"explanation":["4 + 3 = 7이에요.","9 − 2 = 7 — 결과가 같아요.","같은 수가 들어 있어도 결과는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#16','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C6',2,'ox','auto','8 − 2 = 6 입니다.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":16,"concept":"M1-1-u3-C6","difficulty":2,"kind":"ox","stem":"8 − 2 = 6 입니다.","answer":"O","reason_options":[{"t":"8에서 2를 빼면 6이 되니까","correct":true},{"t":"뺄셈도 두 수를 모으는 것이니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["8에서 2를 덜어 내요.","6이에요 — 맞아요.","덜어 낸 것은 세지 않고 남은 것만 세어요."],"variant_rule":{"addsub":{"op":"sub","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#17','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C2',3,'mc','auto','7을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 6, 6과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],false,'{"seq":17,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"7을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 6, 6과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"6","correct":true},{"t":"3","mis":"M1-1-u3-X03"},{"t":"7","mis":"M1-1-u3-X03"}],"explanation":["1과 6부터 6과 1까지 차례로 써요.","모두 6가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#18','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C3',3,'error','auto','하루가 이야기를 만들었어요. 「바구니에 귤이 5개 있었어요. 3개를 더 넣었어요. 남은 귤은 몇 개일까요?」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],false,'{"seq":18,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"하루가 이야기를 만들었어요. 「바구니에 귤이 5개 있었어요. 3개를 더 넣었어요. 남은 귤은 몇 개일까요?」 무엇이 잘못되었나요?","options":[{"t":"더 넣었으니 「모두 몇 개」를 물어야 해요","correct":true,"mis_target":"M1-1-u3-X04"},{"t":"「몇 개 더 많은가」를 물어야 해요","mis":"M1-1-u3-X05"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X04"}],"explanation":["귤을 더 넣으면 귤이 늘어요.","「모두 몇 개」를 물어야 해요.","일어난 일과 물음이 맞는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#19','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C5',3,'error','auto','하루가 6 + 3을 이어 세기로 풀었어요. 「6, 7, 8 — 답은 8이야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X07','M1-1-u3-X08']::text[],false,'{"seq":19,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"하루가 6 + 3을 이어 세기로 풀었어요. 「6, 7, 8 — 답은 8이야!」 무엇이 잘못되었나요?","options":[{"t":"6을 다시 세었어요 — 7, 8, 9로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"3부터 세어야만 해요","mis":"M1-1-u3-X08"}],"explanation":["6은 이미 있는 수라 다시 세지 않아요.","7, 8, 9 — 답은 9예요.","이어 셀 때는 다음 수부터 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#20','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C7',3,'mc','auto','빨간 구슬과 파란 구슬이 모두 7개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X15']::text[],false,'{"seq":20,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"빨간 구슬과 파란 구슬이 모두 7개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"7 − 2 = 5, 7 − 5 = 2","correct":true},{"t":"7 − 2 = 5, 2 − 7 = 5","mis":"M1-1-u3-X11"},{"t":"7 − 2 = 5, 7 − 5 = 3","mis":"M1-1-u3-X15"}],"explanation":["전체 7개에서 빨간 2개를 빼면 파란 5개예요.","전체 7개에서 파란 5개를 빼면 빨간 2개예요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":2},{"item":"🔵","n":5}],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#21','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C8',3,'error','auto','친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],false,'{"seq":21,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「4 − 4 = 4」","correct":true,"mis_target":"M1-1-u3-X13"},{"t":"「4 + 0 = 4」","mis":"M1-1-u3-X12"},{"t":"「0 + 4 = 4」","mis":"M1-1-u3-X12"}],"explanation":["4개에서 4개를 모두 빼면 0이에요.","4 − 4 = 0이에요.","0을 빼기와 모두 빼기를 가르세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#22','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C9',3,'mc','auto','규칙을 찾아 빈칸에 알맞은 식을 고르세요.',ARRAY['M1-1-u3-X14']::text[],false,'{"seq":22,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"규칙을 찾아 빈칸에 알맞은 식을 고르세요.","options":[{"t":"3 + 4","correct":true},{"t":"3 + 5","mis":"M1-1-u3-X14"},{"t":"4 + 4","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","빈칸은 3 + 4예요 — 결과는 모두 7.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["1 + 6","2 + 5",null,"4 + 3"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#23','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C1',4,'mc','auto','같은 수 두 개를 모아서 8을 만들었어요. 그 수는 무엇인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X03']::text[],false,'{"seq":23,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"같은 수 두 개를 모아서 8을 만들었어요. 그 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M1-1-u3-X01"},{"t":"6","mis":"M1-1-u3-X03"}],"explanation":["3과 3은 6, 4와 4는 8이에요.","그 수는 4예요.","같은 수를 하나씩 키워 가며 모아 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#24','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C9',4,'mc','auto','「9 − □」의 결과가 「3 + 3」의 결과와 같아요. □는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X14']::text[],false,'{"seq":24,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「9 − □」의 결과가 「3 + 3」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u3-X10"},{"t":"4","mis":"M1-1-u3-X14"}],"explanation":["3 + 3 = 6이에요.","9 − □ = 6 — 9에서 3을 빼면 6이에요.","그래서 □는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_a#25','math',1,1,'u3','','g1_1_math_u3_review_a','unit_review','M1-1-u3-C4',4,'essay','teacher','「3 + 4 = 7」에 맞는 이야기를 만들고, 이야기에서 3, 4, 7이 각각 무엇인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u3-C4","difficulty":4,"kind":"essay","stem":"「3 + 4 = 7」에 맞는 이야기를 만들고, 이야기에서 3, 4, 7이 각각 무엇인지 써 보세요.","answer_guide":{"answer":"예: 텃밭에 고추가 3개 열렸는데 4개가 더 열렸어요. 고추는 모두 7개예요. 3은 처음 열린 고추, 4는 더 열린 고추, 7은 모두 열린 고추예요.","scoring_points":["모으거나 더 오는 이야기인가","이야기의 수가 3, 4, 7과 맞는가","세 수가 각각 무엇인지 말했는가"]},"explanation":["3과 4가 모이는 장면을 떠올려요.","이야기 끝에 「모두 몇」을 넣어요.","7은 모두 모인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#1','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"6","mis":"M1-1-u3-X01"},{"t":"8","mis":"M1-1-u3-X15"}],"explanation":["6과 3을 모아요.","모으면 9예요.","두 수를 합쳐서 세어요."],"asset":{"type":"number_bond","whole":null,"parts":[6,3]},"variant_rule":{"bond":{"whole":[5,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#2','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C2',1,'sa','auto','9를 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"9를 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["2"],"explanation":["9를 7과 무엇으로 갈랐을까요?","7과 2를 모으면 9이니 2예요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":9,"parts":[7,null]},"variant_rule":{"bond":{"whole":[5,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#3','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C3',1,'mc','auto','닭 5마리에 닭이 더 왔어요. 닭은 모두 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"닭 5마리에 닭이 더 왔어요. 닭은 모두 몇 마리인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X01"}],"explanation":["5마리와 3마리를 모아요.","모두 8마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"asset":{"type":"group_row","groups":[{"item":"🐔","n":5},{"item":"🐔","n":3}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#4','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C4',1,'mc','auto','「6 + 2 = 8」을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],false,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"「6 + 2 = 8」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"6과 2의 합은 8입니다","correct":true},{"t":"6과 2의 차는 8입니다","mis":"M1-1-u3-X06"},{"t":"6 더하기 2는 8보다 작습니다","mis":"M1-1-u3-X06"}],"explanation":["+ 로 모은 수는 「합」이에요.","6과 2의 합은 8입니다.","「차」는 뺄셈에서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#5','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C6',1,'mc','auto','그림에 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"그림에 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"8 − 3 = 5","correct":true},{"t":"8 + 3 = 11","mis":"M1-1-u3-X04"},{"t":"8 − 3 = 6","mis":"M1-1-u3-X15"}],"explanation":["8개에서 빗금 친 3개를 덜어 냈어요.","8 − 3 = 5예요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🍓","n":8,"cross":3},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#6','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C5',1,'sa','auto','6 + 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":1,"kind":"sa","stem":"6 + 3은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["6에서 3만큼 이어 세요 — 7, 8, 9.","6 + 3 = 9예요.","큰 수부터 이어 세면 빨라요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#7','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C7',1,'mc','auto','7부터 2번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"7부터 2번 거꾸로 세면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M1-1-u3-X09"},{"t":"4","mis":"M1-1-u3-X15"}],"explanation":["7은 이미 있는 수예요 — 6부터 세어요.","6, 5 — 5예요.","그래서 7 − 2 = 5예요."],"asset":{"type":"count_on","start":7,"steps":2,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#8','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C8',1,'mc','auto','8 − 0은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"8 − 0은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["8에서 아무것도 덜어 내지 않아요.","8 − 0 = 8이에요.","0을 빼면 그대로예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#9','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C1',2,'match','auto','모아서 9가 되는 두 수를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u3-C1","difficulty":2,"kind":"match","stem":"모아서 9가 되는 두 수를 이어 보세요.","pairs":[{"l":"2","r":"7"},{"l":"4","r":"5"},{"l":"8","r":"1"}],"mis":"M1-1-u3-X01","explanation":["2와 7, 4와 5, 8과 1을 모으면 9예요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 9가 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#10','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C2',2,'mc','auto','사탕 8개를 두 봉지에 나누어 담았어요. 한 봉지에 2개를 담으면 다른 봉지에는 몇 개인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],false,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"사탕 8개를 두 봉지에 나누어 담았어요. 한 봉지에 2개를 담으면 다른 봉지에는 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"8","mis":"M1-1-u3-X02"},{"t":"10","mis":"M1-1-u3-X04"}],"explanation":["8을 2와 무엇으로 가를까요?","2와 6을 모으면 8 — 6개예요.","두 봉지를 모으면 다시 8개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#11','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C3',2,'mc','auto','강아지는 고양이보다 몇 마리 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":11,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"강아지는 고양이보다 몇 마리 더 많은가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M1-1-u3-X05"},{"t":"2","mis":"M1-1-u3-X10"}],"explanation":["강아지와 고양이를 하나씩 짝 지어요.","짝이 없는 강아지는 4마리예요.","「몇 더 많은가」는 모으지 않아요."],"asset":{"type":"compare_groups","rows":[{"label":"강아지","item":"🐶","n":6},{"label":"고양이","item":"🐱","n":2}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#12','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C5',2,'ox','auto','1 + 7의 합은 7 + 1의 합보다 작아요.',ARRAY['M1-1-u3-X08']::text[],false,'{"seq":12,"concept":"M1-1-u3-C5","difficulty":2,"kind":"ox","stem":"1 + 7의 합은 7 + 1의 합보다 작아요.","answer":"X","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 작은 수가 오면 합도 작으니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["1 + 7 = 8, 7 + 1 = 8이에요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#13','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C7',2,'sa','auto','7 − 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"7 − 4는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["7에서 4를 덜어 내요.","7 − 4 = 3이에요.","4와 3을 모으면 7이니까 3이에요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#14','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C8',2,'mc','auto','사탕 3개를 모두 먹었어요. 남은 사탕은 몇 개인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X04']::text[],true,'{"seq":14,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"사탕 3개를 모두 먹었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"0","correct":true},{"t":"3","mis":"M1-1-u3-X13"},{"t":"6","mis":"M1-1-u3-X04"}],"explanation":["3개를 모두 덜어 냈어요.","3 − 3 = 0이에요.","모두 빼면 0이에요."],"asset":{"type":"take_row","item":"🍬","n":3,"cross":3},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#15','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C9',2,'mc','auto','「8 − 3」과 계산 결과가 같은 식은 어느 것인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X04']::text[],false,'{"seq":15,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「8 − 3」과 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"2 + 3","correct":true},{"t":"3 + 3","mis":"M1-1-u3-X14"},{"t":"8 + 3","mis":"M1-1-u3-X04"}],"explanation":["8 − 3 = 5예요.","2 + 3 = 5 — 결과가 같아요.","같은 수가 들어 있어도 결과는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#16','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C6',2,'ox','auto','7 − 3 = 10 입니다.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":16,"concept":"M1-1-u3-C6","difficulty":2,"kind":"ox","stem":"7 − 3 = 10 입니다.","answer":"X","reason_options":[{"t":"7에서 3을 빼면 4가 되니까","correct":true},{"t":"뺄셈도 두 수를 모으는 것이니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["7에서 3을 덜어 내요.","10은 틀렸어요. 바른 답은 4예요.","덜어 내면 처음보다 작아져요."],"variant_rule":{"addsub":{"op":"sub","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#17','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C2',3,'mc','auto','8을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 7, 7과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],false,'{"seq":17,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"8을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 7, 7과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"7","correct":true},{"t":"4","mis":"M1-1-u3-X03"},{"t":"8","mis":"M1-1-u3-X03"}],"explanation":["1과 7부터 7과 1까지 차례로 써요.","모두 7가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#18','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C3',3,'error','auto','하루가 이야기를 만들었어요. 「나무에 새가 8마리 있었어요. 2마리가 날아갔어요. 새는 모두 몇 마리일까요?」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],false,'{"seq":18,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"하루가 이야기를 만들었어요. 「나무에 새가 8마리 있었어요. 2마리가 날아갔어요. 새는 모두 몇 마리일까요?」 무엇이 잘못되었나요?","options":[{"t":"날아갔으니 「남은 것은 몇 마리」를 물어야 해요","correct":true,"mis_target":"M1-1-u3-X04"},{"t":"「몇 마리 더 많은가」를 물어야 해요","mis":"M1-1-u3-X05"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X04"}],"explanation":["새가 날아가면 줄어요.","「남은 것」을 물어야 해요.","일어난 일과 물음이 맞는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#19','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C5',3,'error','auto','하루가 4 + 4를 이어 세기로 풀었어요. 「4, 5, 6, 7 — 답은 7이야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X07','M1-1-u3-X04']::text[],false,'{"seq":19,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"하루가 4 + 4를 이어 세기로 풀었어요. 「4, 5, 6, 7 — 답은 7이야!」 무엇이 잘못되었나요?","options":[{"t":"4를 다시 세었어요 — 5, 6, 7, 8로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"4 + 4는 뺄셈으로 풀어야 해요","mis":"M1-1-u3-X04"}],"explanation":["4는 이미 있는 수라 다시 세지 않아요.","5, 6, 7, 8 — 답은 8이에요.","이어 셀 때는 다음 수부터 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#20','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C7',3,'mc','auto','빨간 구슬과 파란 구슬이 모두 9개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X15']::text[],false,'{"seq":20,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"빨간 구슬과 파란 구슬이 모두 9개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"9 − 4 = 5, 9 − 5 = 4","correct":true},{"t":"9 − 4 = 5, 4 − 9 = 5","mis":"M1-1-u3-X11"},{"t":"9 − 4 = 5, 9 − 5 = 3","mis":"M1-1-u3-X15"}],"explanation":["전체 9개에서 빨간 4개를 빼면 파란 5개예요.","전체 9개에서 파란 5개를 빼면 빨간 4개예요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":4},{"item":"🔵","n":5}],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#21','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C8',3,'error','auto','친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X13']::text[],false,'{"seq":21,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「6 − 0 = 0」","correct":true,"mis_target":"M1-1-u3-X12"},{"t":"「6 − 6 = 0」","mis":"M1-1-u3-X13"},{"t":"「0 + 6 = 6」","mis":"M1-1-u3-X12"}],"explanation":["6에서 아무것도 빼지 않으면 6이에요.","6 − 0 = 6이에요.","0을 빼면 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#22','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C9',3,'mc','auto','규칙을 찾아 빈칸에 알맞은 식을 고르세요.',ARRAY['M1-1-u3-X14']::text[],false,'{"seq":22,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"규칙을 찾아 빈칸에 알맞은 식을 고르세요.","options":[{"t":"7 − 3","correct":true},{"t":"7 − 4","mis":"M1-1-u3-X14"},{"t":"6 − 3","mis":"M1-1-u3-X14"}],"explanation":["빼는 수가 1씩 커져요.","빈칸은 7 − 3이에요.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["7 − 1","7 − 2",null,"7 − 4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#23','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C1',4,'mc','auto','같은 수 두 개를 모아서 6을 만들었어요. 그 수는 무엇인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X03']::text[],false,'{"seq":23,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"같은 수 두 개를 모아서 6을 만들었어요. 그 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M1-1-u3-X01"},{"t":"4","mis":"M1-1-u3-X03"}],"explanation":["2와 2는 4, 3과 3은 6이에요.","그 수는 3이에요.","같은 수를 하나씩 키워 가며 모아 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#24','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C9',4,'mc','auto','「□ + 2」의 결과가 「8 − 1」의 결과와 같아요. □는 무엇인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X14']::text[],false,'{"seq":24,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「□ + 2」의 결과가 「8 − 1」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"6","mis":"M1-1-u3-X14"}],"explanation":["8 − 1 = 7이에요.","□ + 2 = 7 — 5에 2를 더하면 7이에요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_b#25','math',1,1,'u3','','g1_1_math_u3_review_b','unit_review','M1-1-u3-C4',4,'essay','teacher','「5 + 2 = 7」에 맞는 이야기를 만들고, 이야기에서 5, 2, 7이 각각 무엇인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u3-C4","difficulty":4,"kind":"essay","stem":"「5 + 2 = 7」에 맞는 이야기를 만들고, 이야기에서 5, 2, 7이 각각 무엇인지 써 보세요.","answer_guide":{"answer":"예: 연못에 개구리가 5마리 있었는데 2마리가 더 왔어요. 개구리는 모두 7마리예요. 5는 처음 있던 개구리, 2는 더 온 개구리, 7은 모두 모인 개구리예요.","scoring_points":["모으거나 더 오는 이야기인가","이야기의 수가 5, 2, 7과 맞는가","세 수가 각각 무엇인지 말했는가"]},"explanation":["5와 2가 모이는 장면을 떠올려요.","이야기 끝에 「모두 몇」을 넣어요.","7은 모두 모인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#1','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"5","mis":"M1-1-u3-X01"},{"t":"9","mis":"M1-1-u3-X15"}],"explanation":["5와 3을 모아요.","모으면 8이에요.","두 수를 합쳐서 세어요."],"asset":{"type":"number_bond","whole":null,"parts":[5,3]},"variant_rule":{"bond":{"whole":[5,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#2','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C2',1,'sa','auto','7을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"7을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["4"],"explanation":["7을 3과 무엇으로 갈랐을까요?","3과 4를 모으면 7이니 4예요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":7,"parts":[3,null]},"variant_rule":{"bond":{"whole":[5,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#3','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C3',1,'mc','auto','벌 3마리에 벌이 더 날아왔어요. 벌은 모두 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"벌 3마리에 벌이 더 날아왔어요. 벌은 모두 몇 마리인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M1-1-u3-X04"},{"t":"4","mis":"M1-1-u3-X01"}],"explanation":["3마리와 4마리를 모아요.","모두 7마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"asset":{"type":"group_row","groups":[{"item":"🐝","n":3},{"item":"🐝","n":4}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#4','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C4',1,'mc','auto','「4 + 5 = 9」를 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],false,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"「4 + 5 = 9」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"4 더하기 5는 9와 같습니다","correct":true},{"t":"4 빼기 5는 9와 같습니다","mis":"M1-1-u3-X06"},{"t":"4와 5는 9보다 큽니다","mis":"M1-1-u3-X06"}],"explanation":["+ 는 「더하기」, = 는 「같습니다」예요.","4 더하기 5는 9와 같습니다.","「4와 5의 합은 9입니다」라고도 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#5','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C6',1,'mc','auto','그림에 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"그림에 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"6 − 4 = 2","correct":true},{"t":"6 + 4 = 10","mis":"M1-1-u3-X04"},{"t":"6 − 4 = 3","mis":"M1-1-u3-X15"}],"explanation":["6개에서 빗금 친 4개를 덜어 냈어요.","6 − 4 = 2예요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🍪","n":6,"cross":4},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#6','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C5',1,'sa','auto','2 + 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":1,"kind":"sa","stem":"2 + 5는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["5에서 2만큼 이어 세요 — 6, 7.","2 + 5 = 7이에요.","큰 수부터 이어 세면 빨라요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#7','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C7',1,'mc','auto','9부터 2번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"9부터 2번 거꾸로 세면 얼마인가요?","options":[{"t":"7","correct":true},{"t":"8","mis":"M1-1-u3-X09"},{"t":"6","mis":"M1-1-u3-X15"}],"explanation":["9는 이미 있는 수예요 — 8부터 세어요.","8, 7 — 7이에요.","그래서 9 − 2 = 7이에요."],"asset":{"type":"count_on","start":9,"steps":2,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#8','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C8',1,'mc','auto','0 + 6은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"0 + 6은 얼마인가요?","options":[{"t":"6","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["아무것도 없는 데에 6을 더해요.","0 + 6 = 6이에요.","0에 더하면 더한 수 그대로예요."],"variant_rule":{"addsub":{"op":"add","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#9','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C1',2,'match','auto','모아서 7이 되는 두 수를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u3-C1","difficulty":2,"kind":"match","stem":"모아서 7이 되는 두 수를 이어 보세요.","pairs":[{"l":"1","r":"6"},{"l":"2","r":"5"},{"l":"3","r":"4"}],"mis":"M1-1-u3-X01","explanation":["1과 6, 2와 5, 3과 4를 모으면 7이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 7이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#10','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C2',2,'mc','auto','구슬 7개를 두 손에 나누어 쥐었어요. 왼손에 5개가 있으면 오른손에는 몇 개인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],false,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"구슬 7개를 두 손에 나누어 쥐었어요. 왼손에 5개가 있으면 오른손에는 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"7","mis":"M1-1-u3-X02"},{"t":"12","mis":"M1-1-u3-X04"}],"explanation":["7을 5와 무엇으로 가를까요?","5와 2를 모으면 7 — 2개예요.","두 손을 모으면 다시 7개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#11','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C3',2,'mc','auto','딸기는 귤보다 몇 개 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":11,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"딸기는 귤보다 몇 개 더 많은가요?","options":[{"t":"2","correct":true},{"t":"8","mis":"M1-1-u3-X05"},{"t":"3","mis":"M1-1-u3-X10"}],"explanation":["딸기와 귤을 하나씩 짝 지어요.","짝이 없는 딸기는 2개예요.","「몇 더 많은가」는 모으지 않아요."],"asset":{"type":"compare_groups","rows":[{"label":"딸기","item":"🍓","n":5},{"label":"귤","item":"🍊","n":3}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#12','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C5',2,'ox','auto','3 + 5와 5 + 3의 합은 같아요.',ARRAY['M1-1-u3-X08']::text[],false,'{"seq":12,"concept":"M1-1-u3-C5","difficulty":2,"kind":"ox","stem":"3 + 5와 5 + 3의 합은 같아요.","answer":"O","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 오는 수가 크면 합도 크니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["3 + 5 = 8, 5 + 3 = 8이에요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#13','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C7',2,'sa','auto','8 − 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"8 − 6은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8에서 6을 덜어 내요.","8 − 6 = 2예요.","6과 2를 모으면 8이니까 2예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#14','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C8',2,'mc','auto','물고기 6마리가 모두 헤엄쳐 갔어요. 남은 물고기는 몇 마리인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X04']::text[],true,'{"seq":14,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"물고기 6마리가 모두 헤엄쳐 갔어요. 남은 물고기는 몇 마리인가요?","options":[{"t":"0","correct":true},{"t":"6","mis":"M1-1-u3-X13"},{"t":"12","mis":"M1-1-u3-X04"}],"explanation":["6마리를 모두 덜어 냈어요.","6 − 6 = 0이에요.","모두 빼면 0이에요."],"asset":{"type":"take_row","item":"🐟","n":6,"cross":6},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#15','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C9',2,'mc','auto','「1 + 5」와 계산 결과가 같은 식은 어느 것인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X04']::text[],false,'{"seq":15,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「1 + 5」와 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"7 − 1","correct":true},{"t":"7 − 5","mis":"M1-1-u3-X14"},{"t":"5 − 1","mis":"M1-1-u3-X04"}],"explanation":["1 + 5 = 6이에요.","7 − 1 = 6 — 결과가 같아요.","같은 수가 들어 있어도 결과는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#16','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C6',2,'ox','auto','9 − 4 = 5 입니다.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":16,"concept":"M1-1-u3-C6","difficulty":2,"kind":"ox","stem":"9 − 4 = 5 입니다.","answer":"O","reason_options":[{"t":"9에서 4를 빼면 5가 되니까","correct":true},{"t":"뺄셈도 두 수를 모으는 것이니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["9에서 4를 덜어 내요.","5예요 — 맞아요.","덜어 낸 것은 세지 않고 남은 것만 세어요."],"variant_rule":{"addsub":{"op":"sub","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#17','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C2',3,'mc','auto','6을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 5, 5와 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],false,'{"seq":17,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"6을 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 5, 5와 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"5","correct":true},{"t":"3","mis":"M1-1-u3-X03"},{"t":"6","mis":"M1-1-u3-X03"}],"explanation":["1과 5부터 5와 1까지 차례로 써요.","모두 5가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#18','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C3',3,'error','auto','하루가 이야기를 만들었어요. 「연필이 7자루, 지우개가 3개 있어요. 연필과 지우개를 모으면 연필이 몇 개 더 많을까요?」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],false,'{"seq":18,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"하루가 이야기를 만들었어요. 「연필이 7자루, 지우개가 3개 있어요. 연필과 지우개를 모으면 연필이 몇 개 더 많을까요?」 무엇이 잘못되었나요?","options":[{"t":"몇 개 더 많은지는 모으지 않고 짝 지어 견주어야 해요","correct":true,"mis_target":"M1-1-u3-X05"},{"t":"「남은 것은 몇 개」를 물어야 해요","mis":"M1-1-u3-X10"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X05"}],"explanation":["「몇 개 더 많은가」는 견주는 물음이에요.","모으는 것이 아니라 하나씩 짝 지어야 해요.","일어난 일과 물음이 맞는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#19','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C5',3,'error','auto','하루가 5 + 2를 이어 세기로 풀었어요. 「5, 6 — 답은 6이야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X07','M1-1-u3-X08']::text[],false,'{"seq":19,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"하루가 5 + 2를 이어 세기로 풀었어요. 「5, 6 — 답은 6이야!」 무엇이 잘못되었나요?","options":[{"t":"5를 다시 세었어요 — 6, 7로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"2부터 세어야만 해요","mis":"M1-1-u3-X08"}],"explanation":["5는 이미 있는 수라 다시 세지 않아요.","6, 7 — 답은 7이에요.","이어 셀 때는 다음 수부터 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#20','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C7',3,'mc','auto','빨간 구슬과 파란 구슬이 모두 8개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X15']::text[],false,'{"seq":20,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"빨간 구슬과 파란 구슬이 모두 8개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"8 − 6 = 2, 8 − 2 = 6","correct":true},{"t":"8 − 6 = 2, 2 − 8 = 6","mis":"M1-1-u3-X11"},{"t":"8 − 6 = 2, 8 − 2 = 5","mis":"M1-1-u3-X15"}],"explanation":["전체 8개에서 빨간 6개를 빼면 파란 2개예요.","전체 8개에서 파란 2개를 빼면 빨간 6개예요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":6},{"item":"🔵","n":2}],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#21','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C8',3,'error','auto','친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X13']::text[],false,'{"seq":21,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「0 + 8 = 0」","correct":true,"mis_target":"M1-1-u3-X12"},{"t":"「8 − 8 = 0」","mis":"M1-1-u3-X13"},{"t":"「8 − 0 = 8」","mis":"M1-1-u3-X12"}],"explanation":["0에 8을 더하면 8이에요.","0 + 8 = 8이에요.","0이 있다고 답이 0은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#22','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C9',3,'mc','auto','규칙을 찾아 빈칸에 알맞은 식을 고르세요.',ARRAY['M1-1-u3-X14']::text[],false,'{"seq":22,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"규칙을 찾아 빈칸에 알맞은 식을 고르세요.","options":[{"t":"2 + 6","correct":true},{"t":"2 + 7","mis":"M1-1-u3-X14"},{"t":"3 + 6","mis":"M1-1-u3-X14"}],"explanation":["앞의 수는 1씩 커지고 뒤의 수는 1씩 작아져요.","빈칸은 2 + 6이에요 — 결과는 모두 8.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["0 + 8","1 + 7",null,"3 + 5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#23','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C1',4,'mc','auto','지우와 서아의 사탕을 모으면 7개예요. 지우가 서아보다 1개 더 많아요. 지우의 사탕은 몇 개인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X03']::text[],false,'{"seq":23,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"지우와 서아의 사탕을 모으면 7개예요. 지우가 서아보다 1개 더 많아요. 지우의 사탕은 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"7","mis":"M1-1-u3-X01"},{"t":"6","mis":"M1-1-u3-X03"}],"explanation":["7을 가르는 방법 가운데 차이가 1인 것을 찾아요.","4와 3 — 지우는 4개예요.","두 수를 모아 7이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#24','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C9',4,'mc','auto','「7 − □」의 결과가 「1 + 2」의 결과와 같아요. □는 무엇인가요?',ARRAY['M1-1-u3-X10','M1-1-u3-X14']::text[],false,'{"seq":24,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「7 − □」의 결과가 「1 + 2」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M1-1-u3-X10"},{"t":"5","mis":"M1-1-u3-X14"}],"explanation":["1 + 2 = 3이에요.","7 − □ = 3 — 7에서 4를 빼면 3이에요.","그래서 □는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_c#25','math',1,1,'u3','','g1_1_math_u3_review_c','unit_review','M1-1-u3-C4',4,'essay','teacher','「6 + 3 = 9」에 맞는 이야기를 만들고, 이야기에서 6, 3, 9가 각각 무엇인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u3-C4","difficulty":4,"kind":"essay","stem":"「6 + 3 = 9」에 맞는 이야기를 만들고, 이야기에서 6, 3, 9가 각각 무엇인지 써 보세요.","answer_guide":{"answer":"예: 꽃밭에 나비가 6마리 있었는데 3마리가 더 날아왔어요. 나비는 모두 9마리예요. 6은 처음 있던 나비, 3은 더 온 나비, 9는 모두 모인 나비예요.","scoring_points":["모으거나 더 오는 이야기인가","이야기의 수가 6, 3, 9와 맞는가","세 수가 각각 무엇인지 말했는가"]},"explanation":["6과 3이 모이는 장면을 떠올려요.","이야기 끝에 「모두 몇」을 넣어요.","9는 모두 모인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#1','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C1',1,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X15']::text[],true,'{"seq":1,"concept":"M1-1-u3-C1","difficulty":1,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"4","mis":"M1-1-u3-X01"},{"t":"7","mis":"M1-1-u3-X15"}],"explanation":["2와 4를 모아요.","모으면 6이에요.","두 수를 합쳐서 세어요."],"asset":{"type":"number_bond","whole":null,"parts":[2,4]},"variant_rule":{"bond":{"whole":[5,9],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#2','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C2',1,'sa','auto','6을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u3-C2","difficulty":1,"kind":"sa","stem":"6을 둘로 갈랐어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["5"],"explanation":["6을 1과 무엇으로 갈랐을까요?","1과 5를 모으면 6이니 5예요.","가른 두 수를 다시 모아 확인해요."],"asset":{"type":"number_bond","whole":6,"parts":[1,null]},"variant_rule":{"bond":{"whole":[5,9],"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#3','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C3',1,'mc','auto','병아리 2마리에 병아리가 더 왔어요. 병아리는 모두 몇 마리인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X01']::text[],true,'{"seq":3,"concept":"M1-1-u3-C3","difficulty":1,"kind":"mc","stem":"병아리 2마리에 병아리가 더 왔어요. 병아리는 모두 몇 마리인가요?","options":[{"t":"7","correct":true},{"t":"3","mis":"M1-1-u3-X04"},{"t":"5","mis":"M1-1-u3-X01"}],"explanation":["2마리와 5마리를 모아요.","모두 7마리예요.","더 오는 이야기는 모두 몇인지 세어요."],"asset":{"type":"group_row","groups":[{"item":"🐤","n":2},{"item":"🐤","n":5}],"op":"+"},"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#4','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C4',1,'mc','auto','「1 + 6 = 7」을 바르게 읽은 것은 어느 것인가요?',ARRAY['M1-1-u3-X06']::text[],false,'{"seq":4,"concept":"M1-1-u3-C4","difficulty":1,"kind":"mc","stem":"「1 + 6 = 7」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1과 6의 합은 7입니다","correct":true},{"t":"1과 6의 차는 7입니다","mis":"M1-1-u3-X06"},{"t":"1 더하기 6은 7보다 큽니다","mis":"M1-1-u3-X06"}],"explanation":["+ 로 모은 수는 「합」이에요.","1과 6의 합은 7입니다.","「차」는 뺄셈에서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#5','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C6',1,'mc','auto','그림에 알맞은 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X04','M1-1-u3-X15']::text[],true,'{"seq":5,"concept":"M1-1-u3-C6","difficulty":1,"kind":"mc","stem":"그림에 알맞은 뺄셈식은 어느 것인가요?","options":[{"t":"9 − 5 = 4","correct":true},{"t":"9 + 5 = 14","mis":"M1-1-u3-X04"},{"t":"9 − 5 = 3","mis":"M1-1-u3-X15"}],"explanation":["9개에서 빗금 친 5개를 덜어 냈어요.","9 − 5 = 4예요.","덜어 내는 그림은 − 로 나타내요."],"asset":{"type":"take_row","item":"🐟","n":9,"cross":5},"variant_rule":{"addsub":{"op":"sub","ask":"expr"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#6','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C5',1,'sa','auto','4 + 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u3-C5","difficulty":1,"kind":"sa","stem":"4 + 4는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["4에서 4만큼 이어 세요 — 5, 6, 7, 8.","4 + 4 = 8이에요.","센 만큼 손가락을 펴며 세어요."],"variant_rule":{"addsub":{"op":"add","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#7','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C7',1,'mc','auto','6부터 3번 거꾸로 세면 얼마인가요?',ARRAY['M1-1-u3-X09','M1-1-u3-X15']::text[],true,'{"seq":7,"concept":"M1-1-u3-C7","difficulty":1,"kind":"mc","stem":"6부터 3번 거꾸로 세면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M1-1-u3-X09"},{"t":"2","mis":"M1-1-u3-X15"}],"explanation":["6은 이미 있는 수예요 — 5부터 세어요.","5, 4, 3 — 3이에요.","그래서 6 − 3 = 3이에요."],"asset":{"type":"count_on","start":6,"steps":3,"dir":"down"},"variant_rule":{"counton":{"dir":"down","start":[4,9],"steps":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#8','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C8',1,'mc','auto','3 − 0은 얼마인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":8,"concept":"M1-1-u3-C8","difficulty":1,"kind":"mc","stem":"3 − 0은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"2","mis":"M1-1-u3-X15"}],"explanation":["3에서 아무것도 덜어 내지 않아요.","3 − 0 = 3이에요.","0을 빼면 그대로예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#9','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C1',2,'match','auto','모아서 6이 되는 두 수를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u3-C1","difficulty":2,"kind":"match","stem":"모아서 6이 되는 두 수를 이어 보세요.","pairs":[{"l":"1","r":"5"},{"l":"2","r":"4"},{"l":"3","r":"3"}],"mis":"M1-1-u3-X01","explanation":["1과 5, 2와 4, 3과 3을 모으면 6이에요.","한쪽이 커지면 다른 쪽은 작아져요.","짝을 모아 6이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#10','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C2',2,'mc','auto','공 9개를 두 상자에 나누어 넣었어요. 한 상자에 4개를 넣으면 다른 상자에는 몇 개인가요?',ARRAY['M1-1-u3-X02','M1-1-u3-X04']::text[],false,'{"seq":10,"concept":"M1-1-u3-C2","difficulty":2,"kind":"mc","stem":"공 9개를 두 상자에 나누어 넣었어요. 한 상자에 4개를 넣으면 다른 상자에는 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M1-1-u3-X02"},{"t":"13","mis":"M1-1-u3-X04"}],"explanation":["9를 4와 무엇으로 가를까요?","4와 5를 모으면 9 — 5개예요.","두 상자를 모으면 다시 9개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#11','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C3',2,'mc','auto','노란 꽃은 빨간 꽃보다 몇 송이 더 많은가요?',ARRAY['M1-1-u3-X05','M1-1-u3-X10']::text[],true,'{"seq":11,"concept":"M1-1-u3-C3","difficulty":2,"kind":"mc","stem":"노란 꽃은 빨간 꽃보다 몇 송이 더 많은가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M1-1-u3-X05"},{"t":"4","mis":"M1-1-u3-X10"}],"explanation":["노란 꽃과 빨간 꽃을 하나씩 짝 지어요.","짝이 없는 노란 꽃은 5송이예요.","「몇 더 많은가」는 모으지 않아요."],"asset":{"type":"compare_groups","rows":[{"label":"노란 꽃","item":"🌼","n":9},{"label":"빨간 꽃","item":"🌹","n":4}]},"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#12','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C5',2,'ox','auto','4 + 2의 합은 2 + 4의 합보다 커요.',ARRAY['M1-1-u3-X08']::text[],false,'{"seq":12,"concept":"M1-1-u3-C5","difficulty":2,"kind":"ox","stem":"4 + 2의 합은 2 + 4의 합보다 커요.","answer":"X","reason_options":[{"t":"두 수의 순서를 바꾸어 더해도 합은 같으니까","correct":true},{"t":"앞에 큰 수가 오면 합도 크니까","mis":"M1-1-u3-X08"}],"mis":"M1-1-u3-X08","explanation":["4 + 2 = 6, 2 + 4 = 6이에요.","순서를 바꾸어도 합은 같아요.","그래서 큰 수부터 이어 세어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#13','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C7',2,'sa','auto','6 − 1은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-1-u3-C7","difficulty":2,"kind":"sa","stem":"6 − 1은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["6에서 1을 덜어 내요.","6 − 1 = 5예요.","1을 빼면 바로 앞의 수예요."],"variant_rule":{"addsub":{"op":"sub","ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#14','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C8',2,'mc','auto','딸기 7개에서 하나도 먹지 않았어요(빗금 0개). 남은 딸기는 몇 개인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X15']::text[],true,'{"seq":14,"concept":"M1-1-u3-C8","difficulty":2,"kind":"mc","stem":"딸기 7개에서 하나도 먹지 않았어요(빗금 0개). 남은 딸기는 몇 개인가요?","options":[{"t":"7","correct":true},{"t":"0","mis":"M1-1-u3-X12"},{"t":"6","mis":"M1-1-u3-X15"}],"explanation":["빗금 친 딸기가 없어요 — 0개를 뺐어요.","7 − 0 = 7이에요.","0을 빼면 그대로예요."],"asset":{"type":"take_row","item":"🍓","n":7,"cross":0},"variant_rule":{"addsub":{"op":"sub","ask":"value","zero":"only"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#15','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C9',2,'mc','auto','「9 − 5」와 계산 결과가 같은 식은 어느 것인가요?',ARRAY['M1-1-u3-X14','M1-1-u3-X04']::text[],false,'{"seq":15,"concept":"M1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「9 − 5」와 계산 결과가 같은 식은 어느 것인가요?","options":[{"t":"2 + 2","correct":true},{"t":"5 + 2","mis":"M1-1-u3-X14"},{"t":"9 + 5","mis":"M1-1-u3-X04"}],"explanation":["9 − 5 = 4예요.","2 + 2 = 4 — 결과가 같아요.","같은 수가 들어 있어도 결과는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#16','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C6',2,'ox','auto','6 − 5 = 11 입니다.',ARRAY['M1-1-u3-X04']::text[],true,'{"seq":16,"concept":"M1-1-u3-C6","difficulty":2,"kind":"ox","stem":"6 − 5 = 11 입니다.","answer":"X","reason_options":[{"t":"6에서 5를 빼면 1이 되니까","correct":true},{"t":"뺄셈도 두 수를 모으는 것이니까","mis":"M1-1-u3-X04"}],"mis":"M1-1-u3-X04","explanation":["6에서 5를 덜어 내요.","11은 틀렸어요. 바른 답은 1이에요.","덜어 내면 처음보다 작아져요."],"variant_rule":{"addsub":{"op":"sub","ask":"check"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#17','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C2',3,'mc','auto','9를 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 8, 8과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)',ARRAY['M1-1-u3-X03']::text[],false,'{"seq":17,"concept":"M1-1-u3-C2","difficulty":3,"kind":"mc","stem":"9를 두 수로 가르는 방법은 모두 몇 가지인가요? (1과 8, 8과 1은 다른 방법으로 세어요. 0은 쓰지 않아요.)","options":[{"t":"8","correct":true},{"t":"4","mis":"M1-1-u3-X03"},{"t":"9","mis":"M1-1-u3-X03"}],"explanation":["1과 8부터 8과 1까지 차례로 써요.","모두 8가지예요.","한쪽 수를 1부터 차례로 늘리면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#18','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C3',3,'error','auto','하루가 이야기를 만들었어요. 「풍선이 6개 있었어요. 친구가 2개를 더 주었어요. 터진 풍선은 몇 개일까요?」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X04','M1-1-u3-X05']::text[],false,'{"seq":18,"concept":"M1-1-u3-C3","difficulty":3,"kind":"error","stem":"하루가 이야기를 만들었어요. 「풍선이 6개 있었어요. 친구가 2개를 더 주었어요. 터진 풍선은 몇 개일까요?」 무엇이 잘못되었나요?","options":[{"t":"더 받았으니 「모두 몇 개」를 물어야 해요","correct":true,"mis_target":"M1-1-u3-X04"},{"t":"「몇 개 더 많은가」를 물어야 해요","mis":"M1-1-u3-X05"},{"t":"잘못된 곳이 없어요","mis":"M1-1-u3-X04"}],"explanation":["풍선을 더 받으면 늘어요.","「모두 몇 개」를 물어야 해요.","일어난 일과 물음이 맞는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#19','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C5',3,'error','auto','하루가 7 + 2를 이어 세기로 풀었어요. 「7, 8 — 답은 8이야!」 무엇이 잘못되었나요?',ARRAY['M1-1-u3-X07','M1-1-u3-X04']::text[],false,'{"seq":19,"concept":"M1-1-u3-C5","difficulty":3,"kind":"error","stem":"하루가 7 + 2를 이어 세기로 풀었어요. 「7, 8 — 답은 8이야!」 무엇이 잘못되었나요?","options":[{"t":"7을 다시 세었어요 — 8, 9로 세어야 해요","correct":true,"mis_target":"M1-1-u3-X07"},{"t":"잘못한 것이 없어요","mis":"M1-1-u3-X07"},{"t":"7 + 2는 뺄셈으로 풀어야 해요","mis":"M1-1-u3-X04"}],"explanation":["7은 이미 있는 수라 다시 세지 않아요.","8, 9 — 답은 9예요.","이어 셀 때는 다음 수부터 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#20','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C7',3,'mc','auto','빨간 구슬과 파란 구슬이 모두 6개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?',ARRAY['M1-1-u3-X11','M1-1-u3-X15']::text[],false,'{"seq":20,"concept":"M1-1-u3-C7","difficulty":3,"kind":"mc","stem":"빨간 구슬과 파란 구슬이 모두 6개 있어요. 그림에 맞는 두 뺄셈식은 어느 것인가요?","options":[{"t":"6 − 1 = 5, 6 − 5 = 1","correct":true},{"t":"6 − 1 = 5, 1 − 6 = 5","mis":"M1-1-u3-X11"},{"t":"6 − 1 = 5, 6 − 5 = 2","mis":"M1-1-u3-X15"}],"explanation":["전체 6개에서 빨간 1개를 빼면 파란 5개예요.","전체 6개에서 파란 5개를 빼면 빨간 1개예요.","전체 수는 언제나 − 앞에 써요."],"asset":{"type":"group_row","groups":[{"item":"🔴","n":1},{"item":"🔵","n":5}],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#21','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C8',3,'error','auto','친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?',ARRAY['M1-1-u3-X13','M1-1-u3-X12']::text[],false,'{"seq":21,"concept":"M1-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 0이 있는 식을 풀었어요. 잘못 푼 것은 어느 것인가요?","options":[{"t":"「9 − 9 = 9」","correct":true,"mis_target":"M1-1-u3-X13"},{"t":"「9 + 0 = 9」","mis":"M1-1-u3-X12"},{"t":"「9 − 0 = 9」","mis":"M1-1-u3-X12"}],"explanation":["9개에서 9개를 모두 빼면 0이에요.","9 − 9 = 0이에요.","0을 빼기와 모두 빼기를 가르세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#22','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C9',3,'mc','auto','규칙을 찾아 빈칸에 알맞은 식을 고르세요.',ARRAY['M1-1-u3-X14']::text[],false,'{"seq":22,"concept":"M1-1-u3-C9","difficulty":3,"kind":"mc","stem":"규칙을 찾아 빈칸에 알맞은 식을 고르세요.","options":[{"t":"7 − 3","correct":true},{"t":"7 − 4","mis":"M1-1-u3-X14"},{"t":"6 − 4","mis":"M1-1-u3-X14"}],"explanation":["앞의 수도 빼는 수도 1씩 작아져요.","빈칸은 7 − 3이에요 — 결과는 모두 4.","규칙대로 쓰면 빠뜨리지 않아요."],"asset":{"type":"expr_grid","rows":[["9 − 5","8 − 4",null,"6 − 2"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#23','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C1',4,'mc','auto','도이와 유나의 구슬을 모으면 9개예요. 도이가 유나보다 3개 더 많아요. 도이의 구슬은 몇 개인가요?',ARRAY['M1-1-u3-X01','M1-1-u3-X03']::text[],false,'{"seq":23,"concept":"M1-1-u3-C1","difficulty":4,"kind":"mc","stem":"도이와 유나의 구슬을 모으면 9개예요. 도이가 유나보다 3개 더 많아요. 도이의 구슬은 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"9","mis":"M1-1-u3-X01"},{"t":"5","mis":"M1-1-u3-X03"}],"explanation":["9를 가르는 방법 가운데 차이가 3인 것을 찾아요.","6과 3 — 도이는 6개예요.","두 수를 모아 9가 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#24','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C9',4,'mc','auto','「□ + 4」의 결과가 「9 − 0」의 결과와 같아요. □는 무엇인가요?',ARRAY['M1-1-u3-X12','M1-1-u3-X14']::text[],false,'{"seq":24,"concept":"M1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「□ + 4」의 결과가 「9 − 0」의 결과와 같아요. □는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M1-1-u3-X12"},{"t":"4","mis":"M1-1-u3-X14"}],"explanation":["9 − 0 = 9예요.","□ + 4 = 9 — 5에 4를 더하면 9예요.","그래서 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u3_review_d#25','math',1,1,'u3','','g1_1_math_u3_review_d','unit_review','M1-1-u3-C4',4,'essay','teacher','「2 + 6 = 8」에 맞는 이야기를 만들고, 이야기에서 2, 6, 8이 각각 무엇인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u3-C4","difficulty":4,"kind":"essay","stem":"「2 + 6 = 8」에 맞는 이야기를 만들고, 이야기에서 2, 6, 8이 각각 무엇인지 써 보세요.","answer_guide":{"answer":"예: 바구니에 사과가 2개 있었는데 6개를 더 넣었어요. 사과는 모두 8개예요. 2는 처음 있던 사과, 6은 더 넣은 사과, 8은 모두 모인 사과예요.","scoring_points":["모으거나 더 오는 이야기인가","이야기의 수가 2, 6, 8과 맞는가","세 수가 각각 무엇인지 말했는가"]},"explanation":["2와 6이 모이는 장면을 떠올려요.","이야기 끝에 「모두 몇」을 넣어요.","8은 모두 모인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
